css:
.dbm-pacing {
  /* re-theme with these five */
  --dbm-pacing-bg: oklch(0.205 0.017 58);
  --dbm-pacing-ink: oklch(0.95 0.014 82);
  --dbm-pacing-accent: oklch(0.84 0.15 82);
  --dbm-pacing-hot: oklch(0.7 0.165 33);
  --dbm-pacing-cool: oklch(0.75 0.075 240);
  /* derived */
  --dbm-pacing-ok: oklch(from var(--dbm-pacing-accent) 0.8 0.11 155);
  --dbm-pacing-panel: color-mix(in oklch, var(--dbm-pacing-bg), var(--dbm-pacing-ink) 4%);
  --dbm-pacing-raise: color-mix(in oklch, var(--dbm-pacing-bg), var(--dbm-pacing-ink) 9%);
  --dbm-pacing-line: color-mix(in oklch, var(--dbm-pacing-ink) 13%, transparent);
  --dbm-pacing-hair: color-mix(in oklch, var(--dbm-pacing-ink) 7%, transparent);
  --dbm-pacing-mute: color-mix(in oklch, var(--dbm-pacing-ink) 64%, var(--dbm-pacing-bg));
  --dbm-pacing-faint: color-mix(in oklch, var(--dbm-pacing-ink) 42%, var(--dbm-pacing-bg));
  --dbm-pacing-c-search: var(--dbm-pacing-accent);
  --dbm-pacing-c-social: oklch(0.75 0.12 355);
  --dbm-pacing-c-shopping: oklch(0.83 0.12 128);
  --dbm-pacing-c-video: oklch(0.74 0.1 295);
  --dbm-pacing-c-display: oklch(0.8 0.06 62);
  --dbm-pacing-c-partners: oklch(0.8 0.08 198);
  --dbm-pacing-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-pacing-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-pacing-out: cubic-bezier(.16, 1, .3, 1);
  --dbm-pacing-inout: cubic-bezier(.65, 0, .35, 1);
  --dbm-pacing-spring: linear(0, .06 2.2%, .25 4.8%, .53 8.4%, .8 12.8%, .96 17.6%, 1.03 22.6%, 1.045 27%, 1.03 33%, 1.005 42%, .998 55%, 1);
  width: 100%;
  height: var(--dbm-pacing-h, 680px);
  container-type: inline-size;
  container-name: dbm-pacing;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 18px;
  background: var(--dbm-pacing-bg);
  color: var(--dbm-pacing-ink);
  font: 13px/1.45 var(--dbm-pacing-sans);
  accent-color: var(--dbm-pacing-accent);
  color-scheme: dark;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-pacing-accent); outline-offset: 2px; border-radius: 6px; }
  & ::selection { background: color-mix(in oklch, var(--dbm-pacing-accent) 40%, transparent); }
}

.dbm-pacing__app {
  height: 100%;
  display: grid;
  grid-template-columns: 68px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "rail top" "rail kpi" "rail main";
  column-gap: 0;
}

/* ------------------------------------------------------------ rail */
.dbm-pacing__rail {
  grid-area: rail;
  display: flex; flex-direction: column; align-items: center; gap: 18px;
  padding: 16px 0;
  border-right: 1px solid var(--dbm-pacing-line);
  background: color-mix(in oklch, var(--dbm-pacing-bg), black 18%);
}
.dbm-pacing__mark {
  width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center;
  background: var(--dbm-pacing-accent); color: var(--dbm-pacing-bg);
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
}
.dbm-pacing__tabs {
  display: flex; flex-direction: column; gap: 6px; flex: 1;
  & button {
    position: relative; width: 52px; padding: 8px 0 6px; border-radius: 12px;
    display: grid; justify-items: center; gap: 3px;
    color: var(--dbm-pacing-faint);
    font-size: 10px; font-weight: 600; letter-spacing: .02em;
    transition: color .2s, background-color .2s;
  }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { color: var(--dbm-pacing-ink); background: var(--dbm-pacing-hair); }
  & button[aria-selected="true"] { color: var(--dbm-pacing-ink); background: var(--dbm-pacing-raise); }
  & button::before {
    content: ""; position: absolute; left: -8px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0;
    background: var(--dbm-pacing-accent); scale: 1 0; transition: scale .4s var(--dbm-pacing-out);
  }
  & button[aria-selected="true"]::before { scale: 1 1; }
}
.dbm-pacing__who {
  width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center;
  font-size: 11px; font-weight: 700; letter-spacing: .03em;
  background: color-mix(in oklch, var(--dbm-pacing-c-social) 30%, var(--dbm-pacing-bg));
  box-shadow: 0 0 0 2px var(--dbm-pacing-bg), 0 0 0 3px var(--dbm-pacing-line);
}

/* ------------------------------------------------------------ top */
.dbm-pacing__top {
  grid-area: top;
  display: flex; align-items: end; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  padding: 16px 20px 12px;
}
.dbm-pacing__eyebrow {
  font: 600 10.5px/1.3 var(--dbm-pacing-mono); letter-spacing: .08em; text-transform: uppercase;
  color: var(--dbm-pacing-faint);
}
.dbm-pacing__title h2 {
  font-size: clamp(19px, 2.3cqi, 25px); font-weight: 680; letter-spacing: -.025em; line-height: 1.15; margin-top: 4px;
  text-wrap: balance;
}
.dbm-pacing__filters { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.dbm-pacing__chips {
  display: flex; gap: 4px; flex-wrap: wrap;
  & button {
    --c: var(--dbm-pacing-ink);
    display: inline-flex; align-items: center; gap: 6px;
    height: 28px; padding: 0 10px 0 8px; border-radius: 999px;
    font-size: 12px; font-weight: 560; color: var(--dbm-pacing-faint);
    box-shadow: inset 0 0 0 1px var(--dbm-pacing-line);
    transition: color .2s, background-color .2s, box-shadow .2s;
  }
  & button::before {
    content: ""; width: 8px; height: 8px; border-radius: 50%;
    background: color-mix(in oklch, var(--c) 25%, transparent);
    box-shadow: inset 0 0 0 1.5px var(--c);
    transition: background-color .2s;
  }
  & button[aria-pressed="true"] { color: var(--dbm-pacing-ink); background: color-mix(in oklch, var(--c) 13%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent); }
  & button[aria-pressed="true"]::before { background: var(--c); }
  & button:hover { color: var(--dbm-pacing-ink); }
  & button.is-nope { animation: dbm-pacing-nope .38s var(--dbm-pacing-inout); }
}
@keyframes dbm-pacing-nope { 20%, 60% { translate: -3px 0; } 40%, 80% { translate: 3px 0; } }
.dbm-pacing__seg {
  position: relative; display: inline-grid; grid-auto-flow: column; grid-auto-columns: 1fr;
  padding: 3px; border-radius: 10px; background: var(--dbm-pacing-panel);
  box-shadow: inset 0 0 0 1px var(--dbm-pacing-line);
  & button {
    position: relative; z-index: 1; height: 24px; min-width: 40px; padding: 0 8px; border-radius: 7px;
    font: 600 11px/1 var(--dbm-pacing-mono); letter-spacing: .04em; color: var(--dbm-pacing-faint);
    transition: color .25s;
  }
  & button[aria-checked="true"] { color: var(--dbm-pacing-bg); }
  &::before {
    content: ""; position: absolute; top: 3px; bottom: 3px; left: 3px;
    width: calc((100% - 6px) / 4); border-radius: 7px; background: var(--dbm-pacing-accent);
    translate: calc(var(--k, 1) * 100%) 0;
    transition: translate .45s var(--dbm-pacing-spring);
  }
  &:has([data-r="7"][aria-checked="true"]) { --k: 0; }
  &:has([data-r="14"][aria-checked="true"]) { --k: 1; }
  &:has([data-r="30"][aria-checked="true"]) { --k: 2; }
  &:has([data-r="0"][aria-checked="true"]) { --k: 3; }
}

/* ------------------------------------------------------------ kpis */
.dbm-pacing__kpis {
  grid-area: kpi;
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1px;
  margin: 0 20px 14px; border-radius: 14px; overflow: hidden;
  background: var(--dbm-pacing-line);
  box-shadow: 0 0 0 1px var(--dbm-pacing-line);
}
.dbm-pacing__kpi {
  position: relative; padding: 11px 14px 10px; background: var(--dbm-pacing-panel);
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "k s" "v s" "d d"; column-gap: 8px;
  animation: dbm-pacing-rise .7s var(--dbm-pacing-out) both; animation-delay: calc(var(--i, 0) * 55ms);
  & .k { grid-area: k; font: 600 10px/1.2 var(--dbm-pacing-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbm-pacing-faint); }
  & .v { grid-area: v; font-size: clamp(17px, 2cqi, 23px); font-weight: 650; letter-spacing: -.03em; font-variant-numeric: tabular-nums; margin-top: 3px; white-space: nowrap; }
  & .d { grid-area: d; font-size: 11px; color: var(--dbm-pacing-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .d b { font-weight: 650; }
  & .d .good { color: var(--dbm-pacing-ok); }
  & .d .bad { color: var(--dbm-pacing-hot); }
  & svg { grid-area: s; align-self: center; width: 60px; height: 30px; overflow: visible; }
  & svg path { fill: none; stroke: var(--dbm-pacing-accent); stroke-width: 1.5; stroke-linejoin: round; }
  & svg path.ar { fill: color-mix(in oklch, var(--dbm-pacing-accent) 14%, transparent); stroke: none; }
}
.dbm-pacing__kpi.is-pace .v { color: var(--pc, var(--dbm-pacing-ink)); }
@keyframes dbm-pacing-rise { from { opacity: 0; translate: 0 8px; } }

/* ------------------------------------------------------------ main + views */
.dbm-pacing__main { grid-area: main; min-height: 0; padding: 0 20px 18px; }
.dbm-pacing__view { height: 100%; min-height: 0; display: grid; gap: 14px; }
.dbm-pacing__view:not([hidden]) { animation: dbm-pacing-view .5s var(--dbm-pacing-out) both; }
.dbm-pacing__view[hidden] { display: none; }
@keyframes dbm-pacing-view { from { opacity: 0; translate: 0 10px; filter: blur(3px); } }
.dbm-pacing__v-pacing { grid-template-columns: minmax(0, 1.4fr) minmax(330px, 1fr); grid-template-areas: "table detail"; }
.dbm-pacing__v-roas { grid-template-columns: minmax(0, 1.4fr) minmax(280px, 1fr); }
.dbm-pacing__v-flights { grid-template-columns: minmax(0, 1fr); }

.dbm-pacing__panel {
  min-height: 0; border-radius: 14px; background: var(--dbm-pacing-panel);
  box-shadow: inset 0 0 0 1px var(--dbm-pacing-line);
  overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbm-pacing-line) transparent;
}
.dbm-pacing__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  padding: 14px 16px 6px;
  & h3 { font-size: 14px; font-weight: 650; letter-spacing: -.01em; text-wrap: balance; }
  & h3 small { font: 500 11px var(--dbm-pacing-mono); color: var(--dbm-pacing-faint); margin-left: 4px; }
}
.dbm-pacing__note { font-size: 11.5px; color: var(--dbm-pacing-mute); text-wrap: pretty; max-width: 46ch; }

/* ------------------------------------------------------------ table */
.dbm-pacing__tablep { grid-area: table; }
.dbm-pacing__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & thead th {
    position: sticky; top: 0; z-index: 2; text-align: left; padding: 0;
    background: color-mix(in oklch, var(--dbm-pacing-panel), var(--dbm-pacing-bg) 30%);
    border-bottom: 1px solid var(--dbm-pacing-line);
  }
  & thead button {
    width: 100%; display: flex; align-items: center; gap: 4px; padding: 10px 10px 9px;
    font: 600 10px/1 var(--dbm-pacing-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-pacing-faint);
    white-space: nowrap;
  }
  & thead button small { font-size: 9.5px; opacity: .8; letter-spacing: .03em; }
  & thead th.n button { justify-content: flex-end; }
  & thead button::after {
    content: ""; width: 7px; height: 7px; border: solid currentColor; border-width: 0 1.5px 1.5px 0;
    rotate: 45deg; translate: 0 -2px; opacity: 0; transition: opacity .2s, rotate .3s var(--dbm-pacing-out);
  }
  & thead th[aria-sort="ascending"] button::after { rotate: -135deg; translate: 0 2px; opacity: 1; }
  & thead th[aria-sort="descending"] button::after { opacity: 1; }
  & thead th[aria-sort$="ending"] button { color: var(--dbm-pacing-ink); }
  & thead button:hover { color: var(--dbm-pacing-ink); }
  & td { padding: 9px 10px; border-bottom: 1px solid var(--dbm-pacing-hair); vertical-align: middle; white-space: nowrap; }
  & td.n { text-align: right; }
  & td small { color: var(--dbm-pacing-faint); font-size: 11px; }
  & tbody tr { cursor: pointer; transition: background-color .18s; position: relative; }
  & tbody tr:hover { background: var(--dbm-pacing-hair); }
  & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dbm-pacing-accent) 9%, transparent); }
  & tbody tr[aria-selected="true"] td:first-child { box-shadow: inset 3px 0 0 var(--dbm-pacing-accent); }
  & tbody tr:focus-visible { outline-offset: -2px; border-radius: 0; }
}
.dbm-pacing__nm {
  display: flex; align-items: center; gap: 9px; min-width: 150px; max-width: 250px;
  & .dot { flex: none; width: 8px; height: 8px; border-radius: 3px; background: var(--c); }
  & span { min-width: 0; display: grid; }
  & b { font-weight: 600; overflow: hidden; text-overflow: ellipsis; }
  & small { overflow: hidden; text-overflow: ellipsis; }
}
.dbm-pacing__bar {
  --st: var(--dbm-pacing-ok);
  position: relative; width: 100%; min-width: 90px; height: 8px; border-radius: 4px;
  background: var(--dbm-pacing-hair);
  box-shadow: inset 0 0 0 1px var(--dbm-pacing-hair);
  &.is-over { --st: var(--dbm-pacing-hot); }
  &.is-under { --st: var(--dbm-pacing-cool); }
  & i {
    position: absolute; inset: 0 auto 0 0; width: calc(min(var(--s), 1) * 100%); border-radius: inherit;
    background: linear-gradient(90deg, color-mix(in oklch, var(--st) 35%, transparent), var(--st));
    transform-origin: left; transition: width .6s var(--dbm-pacing-out);
  }
  & b {
    position: absolute; top: -4px; bottom: -4px; left: calc(var(--e) * 100%); width: 2px; margin-left: -1px; border-radius: 1px;
    background: var(--dbm-pacing-ink); box-shadow: 0 0 0 2px var(--dbm-pacing-panel);
    transition: left .6s var(--dbm-pacing-out);
  }
}
.dbm-pacing__table.is-intro .dbm-pacing__bar i { animation: dbm-pacing-grow .9s var(--dbm-pacing-out) both; animation-delay: calc(120ms + var(--i, 0) * 45ms); }
.dbm-pacing__table.is-intro tbody tr { animation: dbm-pacing-rise .6s var(--dbm-pacing-out) both; animation-delay: calc(var(--i, 0) * 35ms); }
@keyframes dbm-pacing-grow { from { scale: 0 1; } }
.dbm-pacing__pc { font-weight: 650; &.is-over { color: var(--dbm-pacing-hot); } &.is-under { color: var(--dbm-pacing-cool); } &.is-on { color: var(--dbm-pacing-ok); } }
.dbm-pacing__c-bar { width: 22%; }

/* ------------------------------------------------------------ detail */
.dbm-pacing__detail { grid-area: detail; padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 12px; }
.dbm-pacing__dh {
  display: flex; justify-content: space-between; gap: 12px; align-items: start;
  & h3 { font-size: 16px; font-weight: 650; letter-spacing: -.02em; margin-top: 3px; text-wrap: balance; }
}
.dbm-pacing__pill {
  flex: none; padding: 4px 9px; border-radius: 999px; font: 650 10.5px/1 var(--dbm-pacing-mono); letter-spacing: .06em; text-transform: uppercase;
  color: var(--st); background: color-mix(in oklch, var(--st) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--st) 40%, transparent);
  --st: var(--dbm-pacing-ok);
  &.is-over { --st: var(--dbm-pacing-hot); } &.is-under { --st: var(--dbm-pacing-cool); }
}
.dbm-pacing__stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & div { display: grid; gap: 1px; padding-left: 9px; border-left: 2px solid var(--dbm-pacing-line); }
  & dt { font: 600 9.5px/1.2 var(--dbm-pacing-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-pacing-faint); }
  & dd { font-size: 14.5px; font-weight: 630; font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & dd small { display: block; font-size: 10.5px; color: var(--dbm-pacing-faint); font-weight: 500; letter-spacing: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dbm-pacing__fig {
  display: grid; gap: 6px;
  & figcaption { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; font-size: 12px; font-weight: 600; color: var(--dbm-pacing-mute); }
  & figcaption small { font: 500 10.5px var(--dbm-pacing-mono); color: var(--dbm-pacing-faint); }
}
.dbm-pacing__key {
  display: flex; gap: 10px; font: 500 10.5px var(--dbm-pacing-mono); color: var(--dbm-pacing-faint);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li::before { content: ""; width: 12px; height: 2px; border-radius: 1px; background: var(--dbm-pacing-accent); }
  & li.p::before { background: repeating-linear-gradient(90deg, var(--dbm-pacing-mute) 0 3px, transparent 3px 5px); }
  & li.f::before { background: repeating-linear-gradient(90deg, var(--dbm-pacing-accent) 0 1.5px, transparent 1.5px 4px); }
  & li.t::before { background: var(--dbm-pacing-ink); height: 1px; }
}
.dbm-pacing__plot { position: relative; min-height: 0; & svg { display: block; width: 100%; height: 100%; overflow: visible; } }
.dbm-pacing__cum .dbm-pacing__plot { height: 168px; }
.dbm-pacing__rb .dbm-pacing__plot { height: 92px; }

.dbm-pacing__svg-txt, .dbm-pacing__plot text { font: 500 10px var(--dbm-pacing-mono); fill: var(--dbm-pacing-faint); font-variant-numeric: tabular-nums; }
.dbm-pacing__plot {
  & .gl { stroke: var(--dbm-pacing-hair); }
  & .ax { stroke: var(--dbm-pacing-line); }
  & .area { fill: color-mix(in oklch, var(--dbm-pacing-accent) 13%, transparent); }
  & .act { fill: none; stroke: var(--dbm-pacing-accent); stroke-width: 2; stroke-linejoin: round; }
  & .ideal { fill: none; stroke: var(--dbm-pacing-mute); stroke-width: 1.3; stroke-dasharray: 4 3; }
  & .proj { fill: none; stroke: var(--dbm-pacing-accent); stroke-width: 1.6; stroke-dasharray: 1.5 3.5; stroke-linecap: round; }
  & .band { fill: color-mix(in oklch, var(--dbm-pacing-accent) 9%, transparent); }
  & .budget { stroke: var(--dbm-pacing-ink); stroke-width: 1; opacity: .7; }
  & .budget-t { fill: var(--dbm-pacing-ink); font-weight: 650; }
  & .over-zone { fill: color-mix(in oklch, var(--dbm-pacing-hot) 5%, transparent); }
  & .today { stroke: var(--dbm-pacing-ink); stroke-width: 1; stroke-dasharray: 2 2; opacity: .55; }
  & .today-t { fill: var(--dbm-pacing-ink); }
  & .xh { stroke: var(--dbm-pacing-ink); stroke-width: 1; opacity: .45; }
  & .xd { fill: var(--dbm-pacing-bg); stroke: var(--dbm-pacing-accent); stroke-width: 2; }
  & .xd.i { stroke: var(--dbm-pacing-mute); }
  & .hit { fill: transparent; cursor: crosshair; }
  & .tgt { stroke: var(--dbm-pacing-ink); stroke-width: 1; stroke-dasharray: 3 3; opacity: .7; }
  & .rbar { fill: color-mix(in oklch, var(--dbm-pacing-accent) 72%, transparent); transform-box: fill-box; transform-origin: bottom; transition: fill .2s; }
  & .rbar.lo { fill: color-mix(in oklch, var(--dbm-pacing-hot) 60%, transparent); }
  & .rbar.on { fill: var(--dbm-pacing-ink); }
}
.dbm-pacing__plot svg.is-intro {
  & .act, & .area { animation: dbm-pacing-wipe 1.15s var(--dbm-pacing-out) both; }
  & .proj, & .band { animation: dbm-pacing-fade .6s .85s ease-out both; }
  & .rbar { animation: dbm-pacing-grow .7s var(--dbm-pacing-out) both; animation-delay: calc(var(--i, 0) * 18ms); }
}
@keyframes dbm-pacing-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbm-pacing-fade { from { opacity: 0; } }

.dbm-pacing__whatif {
  padding: 11px 12px 10px; border-radius: 12px; background: var(--dbm-pacing-raise);
  display: grid; gap: 7px;
  & input[type="range"] { width: 100%; margin: 0; height: 18px; }
}
.dbm-pacing__wl { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 12px; color: var(--dbm-pacing-mute); & b { color: var(--dbm-pacing-ink); font-weight: 600; } }
