const full = v => '$' + NF.format(Math.round(v));
const sgnPct = v => (v > 0.0005 ? '+' : v < -0.0005 ? '−' : '±') + Math.abs(v * 100).toFixed(1) + '%';
const sum = (a, f) => a.reduce((s, x) => s + f(x), 0);

/* ---------------------------------------------------------------- calendar: day 0 = Jul 1 2026, data closed through Oct 1 */
const DAY = 864e5, D0 = Date.UTC(2026, 6, 1);
const di = (m, d) => Math.round((Date.UTC(2026, m - 1, d) - D0) / DAY);
