const dt = i => new Date(D0 + i * DAY);
const fD = i => dt(i).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const wd = i => dt(i).getUTCDay();

/* ---------------------------------------------------------------- campaigns */
const CH = { search: 'Search', social: 'Social', shopping: 'Shopping', video: 'Video', display: 'Display', partners: 'Partners' };
const AOV = { search: 152, social: 138, shopping: 121, video: 164, display: 129, partners: 147 };
// id, name, short, channel, start, end, budget, pace at start, pace now, base ROAS, target ROAS, owner
const DEF = [
  ['brand', 'Brand search, always on', 'Brand search', 'search', di(7, 1), di(12, 31), 240000, 1.0, 1.01, 9.4, 6, 'Imani Brooks'],
  ['bed', 'Nonbrand search: bedding', 'Bedding search', 'search', di(9, 8), di(12, 20), 150000, 0.93, 0.8, 3.4, 3, 'Imani Brooks'],
  ['lamp', 'Nonbrand search: lighting', 'Lighting search', 'search', di(9, 8), di(12, 20), 90000, 0.98, 1.02, 2.9, 3, 'Imani Brooks'],
  ['prosp', 'Autumn Nest prospecting', 'Prospecting', 'social', di(9, 1), di(11, 15), 180000, 1.02, 1.21, 2.6, 2.5, 'Theo Marchetti'],
  ['retarg', 'Autumn Nest retargeting', 'Retargeting', 'social', di(9, 1), di(11, 15), 60000, 1.0, 0.99, 6.8, 5, 'Theo Marchetti'],
  ['linen', 'Linen sale shopping feed', 'Linen sale', 'shopping', di(9, 21), di(10, 18), 70000, 1.1, 1.32, 4.1, 4, 'Rosa Elling'],
  ['ctv', 'Living Room streaming TV', 'Streaming TV', 'video', di(9, 15), di(11, 30), 160000, 1.03, 1.11, 1.5, 1.4, 'Kwame Asante'],
  ['teaser', 'Holiday teaser online video', 'Holiday teaser', 'video', di(9, 24), di(12, 24), 120000, 0.95, 0.93, 1.2, 1.5, 'Kwame Asante'],
  ['look', 'Lookalike display', 'Lookalikes', 'display', di(8, 24), di(11, 1), 85000, 0.86, 0.71, 1.8, 2, 'Rosa Elling'],
  ['gift', 'Gift guide affiliates', 'Gift guides', 'partners', di(9, 14), di(12, 15), 50000, 1.0, 1.0, 5.2, 4, 'Dana Ruiz']
