const CAMPS = DEF.map(([id, name, short, ch, s, e, budget, p0, p1, roas, target, owner]) => {
  const D = e - s + 1, plan = budget / D, days = [], n = Math.max(0, LAST - s + 1);
  for (let k = 0; k < n; k++) {
    const i = s + k, t = n > 1 ? k / (n - 1) : 1, w = wd(i), we = w === 0 || w === 6;
    const wk = ch === 'social' || ch === 'video' ? (we ? 1.12 : 0.96) : (we ? 0.84 : 1.06);
