});
const byId = Object.fromEntries(CAMPS.map(c => [c.id, c]));
const STATUS = { over: 'Over-pacing', under: 'Under-pacing', on: 'On pace' };

/* ---------------------------------------------------------------- state */
const S = { view: 'pacing', range: 14, ch: new Set(Object.keys(CH)), sort: 'pace', dir: -1, sel: 'prosp', cap: null };
const visible = () => CAMPS.filter(c => S.ch.has(c.ch));
const win = () => S.range ? [LAST - S.range + 1, LAST] : [0, LAST];
