/* ---------------------------------------------------------------- tooltip */
const tip = $('.dbm-pacing__tip');
function showTip(html, x, y) {
  tip.innerHTML = html; tip.classList.add('is-on');
  const rr = root.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let lx = x - rr.left + 14, ly = y - rr.top - th - 12;
  if (lx + tw > rr.width - 8) lx = x - rr.left - tw - 14;
