/* ---------------------------------------------------------------- KPIs */
const kpiBox = $('.dbm-pacing__kpis');
const KPIS = [
  { k: 'Spend', f: money, good: 0 },
  { k: 'Revenue', f: money, good: 1 },
  { k: 'ROAS', f: v => v.toFixed(2) + '×', good: 1 },
