  for (let v = 0; v <= ny.max + 1e-9; v += ny.step) g += `<line class="gl" x1="${m.l}" x2="${W - m.r}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${m.l - 6}" y="${Y(v) + 3}" text-anchor="end">${+v.toFixed(1)}×</text>`;
  for (let v = 0; v <= nx.max + 1e-9; v += nx.step) g += `<line class="gl" x1="${X(v)}" x2="${X(v)}" y1="${m.t}" y2="${H - m.b}"/><text x="${X(v)}" y="${H - 12}" text-anchor="middle">${money(v)}</text>`;
  g += `<text x="${W - m.r}" y="${H - 1}" text-anchor="end">spend · ${rangeLabel()}</text>`;
  g += `<line class="ax" x1="${X(mid)}" x2="${X(mid)}" y1="${m.t}" y2="${H - m.b}" stroke-dasharray="3 4"/>`;
  g += `<line class="tgt" x1="${m.l}" x2="${W - m.r}" y1="${Y(tgt)}" y2="${Y(tgt)}"/><text x="${W - m.r - 2}" y="${Y(tgt) - 5}" text-anchor="end" style="fill:var(--dbm-pacing-ink)">target ${tgt.toFixed(2)}×</text>`;
  [['SCALE', m.l + 8, m.t + 12, 'start'], ['PROTECT', W - m.r - 8, m.t + 12, 'end'], ['TEST', m.l + 8, H - m.b - 8, 'start'], ['FIX', W - m.r - 8, H - m.b - 8, 'end']]
    .forEach(([t, x, y, an]) => g += `<text class="quad" x="${x}" y="${y}" text-anchor="${an}">${t}</text>`);
  $('.dbm-pacing__bgrid', bubSvg).innerHTML = g;
  bubSvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const layer = $('.dbm-pacing__bubs', bubSvg), seen = new Set();
  const first = !BUB;
  rows.sort((p, q) => q.x.rv - p.x.rv).forEach(({ c, x }) => {
    seen.add(c.id);
    let gEl = layer.querySelector(`[data-id="${c.id}"]`);
    const rr = 5 + (rMax - 5) * Math.sqrt(x.rv / maxRv), cx = X(x.sp), cy = Y(x.rv / x.sp);
    if (!gEl) {
      layer.insertAdjacentHTML('beforeend', `<g class="dbm-pacing__bub" data-id="${c.id}" tabindex="0" role="button" style="--c:var(--dbm-pacing-c-${c.ch});transform:translate(${first ? X(0) : cx}px,${first ? Y(0) : cy}px)"><circle r="${first ? 0 : rr}"/><text dy="0.32em"></text></g>`);
      gEl = layer.lastElementChild;
    }
    gEl.classList.remove('is-gone'); gEl.classList.toggle('is-sel', c.id === S.sel);
    gEl.setAttribute('aria-label', `${c.name}: spend ${money(x.sp)}, ROAS ${(x.rv / x.sp).toFixed(2)}`);
    const tx = $('text', gEl); tx.textContent = c.short;
    const right = cx + rr + 4 + c.short.length * 5.6 < W - m.r;
    tx.setAttribute('x', right ? rr + 4 : -(rr + 4)); tx.setAttribute('text-anchor', right ? 'start' : 'end');
    Object.assign(gEl.dataset, { sp: x.sp, rv: x.rv });
    const apply = () => { gEl.style.transform = `translate(${cx}px,${cy}px)`; $('circle', gEl).style.r = rr + 'px'; };
    if (first && !RM) requestAnimationFrame(() => requestAnimationFrame(() => { if (!root.isConnected) return; apply(); })); else apply();
  });
  $$('.dbm-pacing__bub', layer).forEach(gEl => { if (!seen.has(gEl.dataset.id)) gEl.classList.add('is-gone'); });
  BUB = true;
}
bubSvg.addEventListener('pointermove', e => {
  const g = e.target.closest('.dbm-pacing__bub'); if (!g) { hideTip(); return; }
  const c = byId[g.dataset.id], sp = +g.dataset.sp, rv = +g.dataset.rv;
  showTip(`<h4>${esc(c.name)}</h4><p><span>Spend</span><b>${full(sp)}</b></p><p><span>Revenue</span><b>${full(rv)}</b></p><p><span>ROAS</span><b>${(rv / sp).toFixed(2)}× <small>(target ${c.target}×)</small></b></p>`, e.clientX, e.clientY);
});
bubSvg.addEventListener('pointerleave', hideTip);
bubSvg.addEventListener('click', e => { const g = e.target.closest('.dbm-pacing__bub'); if (g) select(g.dataset.id); });
bubSvg.addEventListener('keydown', e => { const g = e.target.closest('.dbm-pacing__bub'); if (g && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); select(g.dataset.id); } });

const divList = $('.dbm-pacing__div');
function drawDiverging() {
  const [a, b] = win();
  const rows = visible().map(c => { const x = agg(c, a, b); return { c, v: x.rv - x.sp * c.target, x }; }).filter(r => r.x.sp > 0).sort((p, q) => q.v - p.v);
  const mx = Math.max(...rows.map(r => Math.abs(r.v))) || 1;
  const old = new Map($$('li', divList).map(li => [li.dataset.id, li]));
  flip(divList, 'li', () => {
    rows.forEach(r => {
      let li = old.get(r.c.id);
      if (!li) { li = document.createElement('li'); li.dataset.id = r.c.id; li.innerHTML = '<span class="lb"></span><span class="tr"><i></i></span><span class="vv"></span>'; }
      old.delete(r.c.id);
      $('.lb', li).textContent = r.c.short;
      const bar = $('i', li); bar.classList.toggle('neg', r.v < 0); bar.style.setProperty('--w', (Math.abs(r.v) / mx).toFixed(4));
      $('.vv', li).textContent = (r.v >= 0 ? '+' : '−') + money(Math.abs(r.v));
      li.classList.toggle('is-sel', r.c.id === S.sel);
      li.title = `${r.c.name}: revenue ${full(r.x.rv)} vs ${full(r.x.sp * r.c.target)} at ${r.c.target}× target`;
      divList.appendChild(li);
    });
    old.forEach(li => li.remove());
  });
}
divList.addEventListener('click', e => { const li = e.target.closest('li'); if (li) select(li.dataset.id); });

/* ---------------------------------------------------------------- flights view */
const G0 = di(7, 1), G1 = H2END + 1, gx = i => ((i - G0) / (G1 - G0) * 100).toFixed(3) + '%';
$('.dbm-pacing__gmonths').innerHTML = [7, 8, 9, 10, 11, 12].map(mo => `<span style="left:${gx(di(mo, 1))}">${dt(di(mo, 1)).toLocaleDateString('en-US', { month: 'short', timeZone: 'UTC' })}</span>`).join('') + `<span class="tdy" style="left:${gx(TODAY)}">Today</span>`;
$('.dbm-pacing__gtoday').style.setProperty('--f', ((TODAY - G0) / (G1 - G0)).toFixed(4));
const gRows = $('.dbm-pacing__grows');
function drawGantt(intro) {
  const vs = visible().slice().sort((a, b) => Object.keys(CH).indexOf(a.ch) - Object.keys(CH).indexOf(b.ch) || a.s - b.s);
  const focusId = (vs.find(c => c.id === S.sel) || vs[0]).id;
  gRows.innerHTML = vs.map((c, i) => {
    const p = c.p, t = p.el / c.D, mny = Math.min(1.08, p.spent / c.budget);
    return `<li data-id="${c.id}" style="--i:${i};--c:var(--dbm-pacing-c-${c.ch})" class="${c.id === S.sel ? 'is-sel' : ''}" tabindex="${c.id === focusId ? 0 : -1}" aria-label="${esc(c.name)}: ${Math.round(t * 100)}% of time elapsed, ${Math.round(p.spent / c.budget * 100)}% of budget spent"><span class="gl"><i class="dot"></i><span>${esc(c.name)}</span></span><span class="gt"><span class="dbm-pacing__gbar" style="--i:${i};left:${gx(c.s)};width:calc(${gx(c.e + 1)} - ${gx(c.s)});--t:${t.toFixed(4)};--m:${mny.toFixed(4)}"><i class="el"></i><i class="dm is-${p.status}"></i></span></span></li>`;
  }).join('');
  const gp = $('.dbm-pacing__ganttp'); gp.classList.remove('is-intro');
  if (intro && !RM) { void gp.offsetWidth; gp.classList.add('is-intro'); }
}
gRows.addEventListener('keydown', e => {
  const lis = $$('li', gRows), i = lis.indexOf(document.activeElement); if (i < 0) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(lis[i].dataset.id); setView('pacing'); return; }
  const n = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: lis.length - 1 }[e.key]; if (n == null) return;
  e.preventDefault(); const t = lis[Math.max(0, Math.min(lis.length - 1, n))];
  lis.forEach(l => l.tabIndex = l === t ? 0 : -1); t.focus();
});
gRows.addEventListener('pointermove', e => {
  const li = e.target.closest('li[data-id]'); if (!li) { hideTip(); return; }
  const c = byId[li.dataset.id], p = c.p;
  showTip(`<h4>${esc(c.name)}</h4><p><span>Flight</span><b>${fD(c.s)} to ${fD(c.e)}</b></p><p><span>Time elapsed</span><b>${Math.round(p.el / c.D * 100)}%</b></p><p><span>Budget spent</span><b>${Math.round(p.spent / c.budget * 100)}%</b></p><p><span>Lands at</span><b>${money(p.proj)} of ${money(c.budget)}</b></p>`, e.clientX, e.clientY);
});
gRows.addEventListener('pointerleave', hideTip);
gRows.addEventListener('click', e => { const li = e.target.closest('li[data-id]'); if (li) { select(li.dataset.id); setView('pacing'); } });

/* ---------------------------------------------------------------- orchestration */
const drawn = { pacing: false, roas: false, flights: false };
function renderView(fromNav) {
  if (S.view === 'pacing') { renderTable(!drawn.pacing); renderDetail(!drawn.pacing); drawn.pacing = true; }
  else if (S.view === 'roas') { drawBubbles(); drawDiverging(); drawn.roas = true; }
  else { drawGantt(!drawn.flights); drawn.flights = true; }
}
function renderAll() { renderKpis(); renderView(false); }

let rsT = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(rsT);
  rsT = requestAnimationFrame(() => {
    if (!root.isConnected) return;
    if (S.view === 'pacing') { drawCum(false); drawProj(); drawBars(false); }
    else if (S.view === 'roas') drawBubbles();
  });
});
$$('.dbm-pacing__plot').forEach(p => ro.observe(p));

renderKpis();
renderView(true);

css:
.dbm-attrib {
  /* re-theme with these three */
  --dbm-attrib-paper: oklch(0.976 0.007 85);
  --dbm-attrib-ink: oklch(0.23 0.02 265);
  --dbm-attrib-accent: oklch(0.62 0.2 33);
  /* derived */
  --dbm-attrib-card: color-mix(in oklch, var(--dbm-attrib-paper), white 55%);
  --dbm-attrib-side: color-mix(in oklch, var(--dbm-attrib-paper), var(--dbm-attrib-ink) 3.5%);
  --dbm-attrib-line: color-mix(in oklch, var(--dbm-attrib-ink) 13%, transparent);
  --dbm-attrib-hair: color-mix(in oklch, var(--dbm-attrib-ink) 7%, transparent);
  --dbm-attrib-mute: color-mix(in oklch, var(--dbm-attrib-ink) 62%, var(--dbm-attrib-paper));
  --dbm-attrib-faint: color-mix(in oklch, var(--dbm-attrib-ink) 42%, var(--dbm-attrib-paper));
  --dbm-attrib-tint: color-mix(in oklch, var(--dbm-attrib-accent) 9%, var(--dbm-attrib-card));
  --dbm-attrib-c-org: oklch(0.6 0.13 150);
  --dbm-attrib-c-ppc: oklch(0.55 0.15 255);
  --dbm-attrib-c-soc: oklch(0.62 0.19 345);
  --dbm-attrib-c-eml: oklch(0.73 0.14 78);
  --dbm-attrib-c-ref: oklch(0.6 0.1 195);
  --dbm-attrib-c-web: oklch(0.5 0.15 295);
  --dbm-attrib-c-dir: oklch(0.58 0.02 260);
  --dbm-attrib-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-attrib-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --dbm-attrib-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-attrib-out: cubic-bezier(.2, .9, .25, 1);
  --dbm-attrib-snap: cubic-bezier(.5, 0, .1, 1);
  --dbm-attrib-spring: linear(0, .045 2%, .19 5%, .45 9.5%, .75 15%, .93 21%, 1.02 27%, 1.04 32%, 1.025 40%, 1.004 52%, .999 70%, 1);
  width: 100%;
  height: var(--dbm-attrib-h, 680px);
  container-type: inline-size;
  container-name: dbm-attrib;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 14px;
  background: var(--dbm-attrib-paper);
  color: var(--dbm-attrib-ink);
  font: 13px/1.45 var(--dbm-attrib-sans);
  accent-color: var(--dbm-attrib-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dbm-attrib-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, ul, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-attrib-accent); outline-offset: 2px; border-radius: 5px; }
}
.dbm-attrib__app {
  height: 100%;
  display: grid;
  grid-template-columns: 208px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head" "side main";
}

/* ------------------------------------------------------------ sidebar */
.dbm-attrib__side {
  grid-area: side; min-height: 0; overflow: auto; scrollbar-width: thin;
  display: flex; flex-direction: column; gap: 18px; padding: 18px 14px 16px;
  background: var(--dbm-attrib-side); border-right: 1px solid var(--dbm-attrib-line);
}
.dbm-attrib__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & svg { width: 26px; height: 26px; flex: none; fill: none; stroke: var(--dbm-attrib-ink); stroke-width: 1.5; stroke-linejoin: round; }
  & span { display: grid; line-height: 1.15; }
  & b { font-weight: 750; letter-spacing: -.02em; font-size: 14px; }
  & small { font: 500 10px var(--dbm-attrib-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dbm-attrib-faint); }
}
.dbm-attrib__nav {
  display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 8px;
    font-weight: 560; color: var(--dbm-attrib-mute); text-align: left; transition: background-color .18s, color .18s;
  }
  & svg { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { background: var(--dbm-attrib-hair); color: var(--dbm-attrib-ink); }
  & button[aria-selected="true"] { background: var(--dbm-attrib-card); color: var(--dbm-attrib-ink); box-shadow: 0 1px 0 var(--dbm-attrib-line), 0 0 0 1px var(--dbm-attrib-hair); }
  & button[aria-selected="true"] svg { stroke: var(--dbm-attrib-accent); }
}
.dbm-attrib__ctl { display: grid; gap: 7px; }
.dbm-attrib__lbl {
  font: 600 10px/1.2 var(--dbm-attrib-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--dbm-attrib-faint); padding: 0 2px;
  & span { text-transform: none; letter-spacing: 0; font-family: var(--dbm-attrib-sans); font-weight: 500; }
}
.dbm-attrib__seg {
  display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: 2px; padding: 2px; border-radius: 8px;
  background: var(--dbm-attrib-hair);
  & button { height: 26px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--dbm-attrib-mute); transition: background-color .2s, color .2s, box-shadow .2s; white-space: nowrap; padding: 0 6px; }
  & button:hover { color: var(--dbm-attrib-ink); }
  & button[aria-checked="true"] { background: var(--dbm-attrib-card); color: var(--dbm-attrib-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbm-attrib-ink) 14%, transparent); }
  &.dbm-attrib__seg--col { grid-auto-flow: row; }
  &.dbm-attrib__seg--col button { text-align: left; padding: 0 10px; }
}
.dbm-attrib__foot { margin-top: auto; font-size: 11px; color: var(--dbm-attrib-faint); line-height: 1.5; text-wrap: pretty; padding: 0 2px; & b { color: var(--dbm-attrib-mute); font-weight: 600; font-variant-numeric: tabular-nums; } }

/* ------------------------------------------------------------ head */
.dbm-attrib__head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 18px; align-items: end;
  padding: 18px 22px 14px; border-bottom: 1px solid var(--dbm-attrib-line);
}
.dbm-attrib__eyebrow { font: 600 10.5px var(--dbm-attrib-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--dbm-attrib-accent); }
.dbm-attrib__hl h2 {
  font: 600 clamp(22px, 2.9cqi, 32px)/1.05 var(--dbm-attrib-serif); letter-spacing: -.02em; margin: 4px 0 6px; text-wrap: balance;
}
.dbm-attrib__insight {
  font-size: 13px; color: var(--dbm-attrib-mute); max-width: 62ch; text-wrap: pretty; min-height: 2.9em;
  & b { color: var(--dbm-attrib-ink); font-weight: 650; }
  & .up { color: oklch(from var(--dbm-attrib-c-org) 0.48 c h); font-weight: 650; }
  & .dn { color: var(--dbm-attrib-accent); font-weight: 650; }
}
.dbm-attrib__insight.is-swap { animation: dbm-attrib-swap .5s var(--dbm-attrib-out); }
@keyframes dbm-attrib-swap { from { opacity: 0; filter: blur(4px); translate: 0 4px; } }
.dbm-attrib__lens { display: grid; gap: 7px; justify-items: end; }
.dbm-attrib__models {
  position: relative; display: grid; grid-template-columns: repeat(6, auto); gap: 0; padding: 3px; border-radius: 10px;
  background: var(--dbm-attrib-card); box-shadow: inset 0 0 0 1px var(--dbm-attrib-line);
  & button {
    position: relative; z-index: 1; height: 30px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600;
    color: var(--dbm-attrib-mute); white-space: nowrap; transition: color .25s;
  }
  & button:hover { color: var(--dbm-attrib-ink); }
  & button[aria-checked="true"] { color: var(--dbm-attrib-paper); }
  & .dbm-attrib__pill {
    position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; border-radius: 7px; background: var(--dbm-attrib-ink);
    transition: translate .5s var(--dbm-attrib-spring), width .5s var(--dbm-attrib-spring);
  }
}

/* ------------------------------------------------------------ views */
.dbm-attrib__main { grid-area: main; min-height: 0; padding: 14px 22px 18px; }
.dbm-attrib__view { height: 100%; min-height: 0; display: grid; gap: 14px; }
.dbm-attrib__view[hidden] { display: none; }
.dbm-attrib__view:not([hidden]) { animation: dbm-attrib-in .45s var(--dbm-attrib-out) both; }
@keyframes dbm-attrib-in { from { opacity: 0; translate: 0 8px; } }
.dbm-attrib__v-compare { grid-template-columns: minmax(0, 1.55fr) minmax(290px, 1fr); }
.dbm-attrib__panel {
  min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbm-attrib-line) transparent;
  border-radius: 12px; background: var(--dbm-attrib-card);
  box-shadow: 0 0 0 1px var(--dbm-attrib-line), 0 1px 2px color-mix(in oklch, var(--dbm-attrib-ink) 6%, transparent);
}
.dbm-attrib__ph {
  padding: 13px 16px 4px;
  & h3 { font-size: 13.5px; font-weight: 680; letter-spacing: -.01em; text-wrap: balance; }
  & h3 small { font: 500 11px var(--dbm-attrib-sans); color: var(--dbm-attrib-faint); margin-left: 4px; }
  & p { font-size: 11.5px; color: var(--dbm-attrib-mute); margin-top: 2px; text-wrap: pretty; }
}

/* ------------------------------------------------------------ slope chart */
.dbm-attrib__slope { display: flex; flex-direction: column; }
.dbm-attrib__plot { position: relative; flex: 1; min-height: 260px; margin: 2px 6px 8px; & svg { display: block; width: 100%; height: 100%; overflow: visible; } }
.dbm-attrib__plot {
  & text { font: 500 10.5px var(--dbm-attrib-sans); fill: var(--dbm-attrib-mute); font-variant-numeric: tabular-nums; }
  & .gl { stroke: var(--dbm-attrib-hair); }
  & .col { cursor: pointer; }
  & .col rect { fill: transparent; transition: fill .2s; }
  & .col:hover rect { fill: var(--dbm-attrib-hair); }
  & .col text { font-weight: 650; fill: var(--dbm-attrib-mute); font-size: 10.5px; transition: fill .2s; }
  & .col.is-lens text { fill: var(--dbm-attrib-accent); }
  & .col .ax { stroke: var(--dbm-attrib-line); }
  & .col.is-lens .ax { stroke: var(--dbm-attrib-accent); stroke-width: 1.5; }
  & .lensband { fill: var(--dbm-attrib-tint); transition: transform .55s var(--dbm-attrib-spring); }
  & .ln { fill: none; stroke: var(--c); stroke-width: 2.2; stroke-linejoin: round; stroke-linecap: round; transition: d .65s var(--dbm-attrib-out), opacity .25s, stroke-width .2s; }
  & .dt { fill: var(--dbm-attrib-card); stroke: var(--c); stroke-width: 2; transition: transform .65s var(--dbm-attrib-out), opacity .25s; }
  & .dt.on { fill: var(--c); }
  & .lab { font-weight: 650; fill: var(--c); transition: transform .65s var(--dbm-attrib-out), opacity .25s; }
  & .lab tspan { fill: var(--dbm-attrib-mute); font-weight: 500; }
  & .ch { cursor: pointer; }
  & svg.is-hover .ch:not(.is-hot) { opacity: .16; }
  & svg.is-hover .ch.is-hot .ln { stroke-width: 3.2; }
}
.dbm-attrib__plot svg.is-intro {
  & .ln { stroke-dasharray: 1 1; animation: dbm-attrib-draw 1.3s var(--dbm-attrib-out) both; animation-delay: calc(var(--i) * 70ms); }
  & .dt, & .lab { animation: dbm-attrib-pop .5s var(--dbm-attrib-out) both; animation-delay: calc(500ms + var(--i) * 70ms); }
}
@keyframes dbm-attrib-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbm-attrib-pop { from { opacity: 0; } }

/* ------------------------------------------------------------ shift bars */
.dbm-attrib__bars {
  padding: 8px 16px 14px; display: grid; gap: 4px;
  & li {
    display: grid; grid-template-columns: 112px minmax(0, 1fr) 52px; grid-template-rows: auto auto; column-gap: 10px; align-items: center;
    padding: 4px 4px; border-radius: 8px; transition: background-color .15s;
  }
  & li:hover, & li.is-hot { background: var(--dbm-attrib-hair); }
