  & .nm i { width: 9px; height: 9px; border-radius: 2px; background: var(--c); flex: none; }
  & .nm span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .nm .short { display: none; }
  & .tr { position: relative; height: 18px; }
  & .bl, & .le { position: absolute; left: 0; top: 2px; bottom: 2px; border-radius: 3px; width: calc(var(--w) * 100%); transition: width .7s var(--dbm-attrib-spring); }
  & .bl { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--dbm-attrib-ink) 45%, transparent); top: 0; bottom: 0; background: repeating-linear-gradient(-45deg, transparent 0 3px, var(--dbm-attrib-hair) 3px 4.5px); }
  & .le { background: var(--c); top: 5px; bottom: 5px; }
  & .vl { font: 650 12px var(--dbm-attrib-sans); font-variant-numeric: tabular-nums; text-align: right; }
  & .dl { grid-column: 3; font: 600 10.5px var(--dbm-attrib-mono); text-align: right; color: var(--dbm-attrib-faint); }
  & .dl.up { color: oklch(from var(--dbm-attrib-c-org) 0.48 c h); }
  & .dl.dn { color: var(--dbm-attrib-accent); }
  & .sub { grid-column: 2; font-size: 10.5px; color: var(--dbm-attrib-faint); font-variant-numeric: tabular-nums; }
}
.dbm-attrib__bars.is-intro .le { animation: dbm-attrib-grow .9s var(--dbm-attrib-out) both; animation-delay: calc(300ms + var(--i) * 60ms); }
@keyframes dbm-attrib-grow { from { width: 0; } }

/* ------------------------------------------------------------ table */
.dbm-attrib__v-channels { grid-template-columns: minmax(0, 1fr); }
.dbm-attrib__table {
  width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbm-attrib-card); padding: 0; border-bottom: 1px solid var(--dbm-attrib-ink); text-align: left; }
  & th button { width: 100%; display: flex; gap: 5px; align-items: center; padding: 12px 14px 9px; font: 600 10.5px var(--dbm-attrib-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-attrib-mute); white-space: nowrap; }
  & th.n button { justify-content: flex-end; }
  & th button::after { content: "↓"; font-family: var(--dbm-attrib-sans); opacity: 0; transition: opacity .2s, rotate .3s var(--dbm-attrib-out); }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort$="ending"] button { color: var(--dbm-attrib-ink); }
  & td { padding: 11px 14px; border-bottom: 1px solid var(--dbm-attrib-hair); white-space: nowrap; }
  & td.n { text-align: right; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dbm-attrib-hair); }
  & tfoot td { font-weight: 700; border-bottom: 0; border-top: 1px solid var(--dbm-attrib-line); }
  & .nm { display: flex; gap: 8px; align-items: center; font-weight: 600; }
  & .nm i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .sh { display: flex; align-items: center; gap: 8px; min-width: 140px; }
  & .sh span { flex: 1; height: 6px; border-radius: 3px; background: var(--dbm-attrib-hair); position: relative; overflow: hidden; }
  & .sh span::before { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(var(--w) * 100%); background: var(--c); border-radius: 3px; transition: width .6s var(--dbm-attrib-out); }
  & .sh b { width: 44px; text-align: right; font-weight: 600; font-size: 12px; }
  & .up { color: oklch(from var(--dbm-attrib-c-org) 0.48 c h); font-weight: 650; }
  & .dn { color: var(--dbm-attrib-accent); font-weight: 650; }
  & small { color: var(--dbm-attrib-faint); }
}
@supports (animation-timeline: view()) {
  .dbm-attrib__table tbody tr, .dbm-attrib__paths li {
    animation: dbm-attrib-scrollin linear both;
    animation-timeline: view();
    animation-range: entry 0% entry 60%;
  }
}
@keyframes dbm-attrib-scrollin { from { opacity: .2; translate: 0 10px; } }

/* ------------------------------------------------------------ paths */
.dbm-attrib__v-paths { grid-template-columns: minmax(0, 1fr); }
.dbm-attrib__pathh { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; position: sticky; top: 0; z-index: 2; background: var(--dbm-attrib-card); padding-bottom: 10px; border-bottom: 1px solid var(--dbm-attrib-hair); }
.dbm-attrib__pfilter {
  display: flex; gap: 4px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11px; font-weight: 600; color: var(--dbm-attrib-mute); box-shadow: inset 0 0 0 1px var(--dbm-attrib-line); transition: background-color .15s, color .15s; }
  & button i { width: 7px; height: 7px; border-radius: 2px; background: var(--c); }
  & button:hover { color: var(--dbm-attrib-ink); }
  & button[aria-pressed="true"] { background: var(--dbm-attrib-ink); color: var(--dbm-attrib-paper); box-shadow: none; }
}
.dbm-attrib__paths {
  padding: 6px 16px 16px; counter-reset: dbm-attrib-p;
