    padding: 10px 4px; border-bottom: 1px solid var(--dbm-attrib-hair);
  }
  & li::before { content: counter(dbm-attrib-p, decimal-leading-zero); grid-row: 1 / 3; font: 600 11px var(--dbm-attrib-mono); color: var(--dbm-attrib-faint); }
