  & h4 { margin: 0 0 5px; font-size: 12px; font-weight: 650; }
  & p { display: flex; justify-content: space-between; gap: 16px; color: color-mix(in oklch, var(--dbm-attrib-paper) 70%, transparent); }
  & p b { color: var(--dbm-attrib-paper); font-weight: 600; }
  & p.is-lens { color: var(--dbm-attrib-paper); }
  & p.is-lens b { color: color-mix(in oklch, var(--dbm-attrib-accent), white 35%); }
}

/* ------------------------------------------------------------ container responses */
@container dbm-attrib (width < 1100px) {
