/* ---------------------------------------------------------------- tooltip */
const tip = $('.dbm-attrib__tip');
function showTip(html, x, y) {
  tip.innerHTML = html; tip.classList.add('is-on');
  const rr = root.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let lx = x - rr.left + 16, ly = y - rr.top - th / 2;
  if (lx + tw > rr.width - 8) lx = x - rr.left - tw - 16;
  ly = Math.max(8, Math.min(ly, rr.height - th - 8));
  tip.style.translate = `${Math.max(8, lx)}px ${ly}px`;
}
const hideTip = () => tip.classList.remove('is-on');

/* ---------------------------------------------------------------- controls */
function radios(group, onPick) {
  const bs = $$('[role="radio"]', group);
  const set = (b, focus) => { bs.forEach(x => { const on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; }); if (focus) b.focus(); onPick(b.dataset.v); };
  group.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') set(b); });
  group.addEventListener('keydown', e => {
    const i = bs.indexOf(document.activeElement), d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
    if (i < 0 || d == null) return; e.preventDefault(); set(bs[(i + d + bs.length) % bs.length], true);
  });
  return set;
}
$$('.dbm-attrib__side [role="radiogroup"]').forEach(g => radios(g, v => { const k = g.dataset.key; S[k] = k === 'win' ? +v : v; if (k !== 'metric') compute(); renderAll(false); }));

const modelBox = $('.dbm-attrib__models');
modelBox.innerHTML = MODELS.map(m => `<button role="radio" aria-checked="${m.k === S.lens}" tabindex="${m.k === S.lens ? 0 : -1}" data-v="${m.k}">${m.s}</button>`).join('') + '<span class="dbm-attrib__pill" aria-hidden="true"></span>';
const setLens = radios(modelBox, v => { S.lens = v; movePill(); renderAll(true); });
function movePill() {
  const b = $(`[data-v="${S.lens}"]`, modelBox), pill = $('.dbm-attrib__pill', modelBox);
  if (!b.offsetWidth) return;
  pill.style.width = b.offsetWidth + 'px'; pill.style.translate = b.offsetLeft + 'px 0';
}

const tabs = $$('.dbm-attrib__nav [role="tab"]');
function setView(v, focus) {
  S.view = v; hideTip();
  tabs.forEach(t => { const on = t.dataset.view === v; t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); });
  $$('.dbm-attrib__view').forEach(p => p.hidden = p.dataset.view !== v);
  renderView(true);
}
$('.dbm-attrib__nav').addEventListener('click', e => { const t = e.target.closest('[role="tab"]'); if (t) setView(t.dataset.view); });
$('.dbm-attrib__nav').addEventListener('keydown', e => {
  const i = tabs.indexOf(document.activeElement), d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
  if (i < 0 || d == null) return; e.preventDefault(); setView(tabs[(i + d + tabs.length) % tabs.length].dataset.view, true);
});

/* ---------------------------------------------------------------- headline copy, written from the numbers */
function renderInsight(animate) {
  const L = MI[S.lens], B = MI.last, el = $('.dbm-attrib__insight');
  const rows = CHS.map((c, i) => ({ c, r: share(L, i) / Math.max(1e-9, share(B, i)), s: share(L, i), b: share(B, i) }));
  let html;
  if (S.lens === 'last') {
    const top = rows.slice().sort((a, b) => b.b - a.b);
    html = `Last touch hands every ${S.metric === 'conv' ? 'conversion' : 'dollar of ACV'} to the final click: <b>${top[0].c.n}</b> and <b>${top[1].c.n}</b> take <b>${pct(top[0].b + top[1].b, 0)}</b> between them. Pick another lens to see who did the earlier work.`;
  } else {
    const up = rows.slice().sort((a, b) => b.r - a.r)[0], dn = rows.slice().sort((a, b) => a.r - b.r)[0];
    const name = MODELS[L].n;
    html = `Under <b>${name}</b>, <b>${up.c.n}</b> earns <span class="up">${up.r.toFixed(1)}×</span> the credit last touch gives it (${pct(up.b)} → ${pct(up.s)}), while <b>${dn.c.n}</b> gives up <span class="dn">${pct(1 - dn.r, 0)}</span> of its last-touch share.`;
  }
  el.innerHTML = html;
  if (animate && !RM) { el.classList.remove('is-swap'); void el.offsetWidth; el.classList.add('is-swap'); }
}
function renderFoot() {
  $('.dbm-attrib__foot').innerHTML = `<b>${NF.format(M.js.length)}</b> journeys, <b>${NF.format(M.conv)}</b> converted (${pct(M.conv / M.js.length)}), averaging <b>${(M.touches / M.conv).toFixed(1)}</b> touches over <b>${(M.span / M.conv).toFixed(1)}</b> days. Data-driven fits a logistic model of conversion on channel exposure and splits each conversion by how much each touch raised its odds.`;
}

/* ---------------------------------------------------------------- slope chart */
const slopeSvg = $('.dbm-attrib__slope svg');
let SL = null;
function nice(max, n) { const raw = max / n, p = 10 ** Math.floor(Math.log10(raw)), f = raw / p; const st = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p; return { st, max: Math.ceil(max / st) * st }; }
function drawSlope(intro) {
  const box = slopeSvg.parentElement, W = box.clientWidth, H = box.clientHeight; if (!W || !H) return;
  const tight = W < 520;
  const m = { l: 36, r: tight ? 86 : Math.min(150, W * .24), t: 34, b: 14 };
  const ny = nice(Math.max(...MODELS.flatMap((_, mi) => CHS.map((_, ci) => share(mi, ci)))) * 1.05, 4);
  const X = mi => m.l + 14 + mi * (W - m.l - m.r - 28) / (MODELS.length - 1);
  const Y = v => H - m.b - v / ny.max * (H - m.t - m.b);
  const colW = (W - m.l - m.r - 28) / (MODELS.length - 1);
  SL = { X, Y, m, W, H, colW, tight };
  let g = '';
  for (let v = 0; v <= ny.max + 1e-9; v += ny.st) g += `<line class="gl" x1="${m.l}" x2="${W - m.r + 6}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${m.l - 6}" y="${Y(v) + 3.5}" text-anchor="end">${Math.round(v * 100)}%</text>`;
  const lensX = X(MI[S.lens]);
  g += `<rect class="lensband" x="${-colW / 2 + 6}" y="${m.t - 26}" width="${colW - 12}" height="${H - m.t - m.b + 26}" rx="8" style="transform:translateX(${lensX}px)"/>`;
  MODELS.forEach((md, mi) => g += `<g class="col${md.k === S.lens ? ' is-lens' : ''}" data-m="${md.k}" role="button" tabindex="-1" aria-label="Use ${md.n} as the lens"><rect x="${X(mi) - colW / 2}" y="${m.t - 26}" width="${colW}" height="${H - m.t - m.b + 26}" rx="8"/><line class="ax" x1="${X(mi)}" x2="${X(mi)}" y1="${m.t}" y2="${H - m.b}"/><text x="${X(mi)}" y="${m.t - 12}" text-anchor="middle">${colW < 62 ? md.t : md.s}</text></g>`);
  const order = CHS.map((c, ci) => ci);
  g += order.map(ci => `<g class="ch" data-c="${ci}" style="--c:var(--dbm-attrib-c-${CHS[ci].k});--i:${ci}"><path class="ln" pathLength="1"/>${MODELS.map((_, mi) => `<circle class="dt" r="${mi === MI[S.lens] ? 4.5 : 3.2}" data-m="${mi}"/>`).join('')}<text class="lab" x="0" y="0" dy=".35em"></text></g>`).join('');
  slopeSvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  slopeSvg.innerHTML = g;
  updateSlope(true);
  slopeSvg.classList.remove('is-intro');
  if (intro && !RM) { void slopeSvg.getBoundingClientRect(); slopeSvg.classList.add('is-intro'); }
}
function updateSlope(instant) {
  if (!SL) return;
  const { X, Y, W, m } = SL, L = MI[S.lens];
  const labs = CHS.map((c, ci) => ({ ci, y: Y(share(MODELS.length - 1, ci)) })).sort((a, b) => a.y - b.y);
  for (let k = 1; k < labs.length; k++) if (labs[k].y - labs[k - 1].y < 14) labs[k].y = labs[k - 1].y + 14;
  const over = labs[labs.length - 1].y - (SL.H - m.b);
  if (over > 0) labs.forEach(l => l.y -= over);
  const ly = Object.fromEntries(labs.map(l => [l.ci, l.y]));
  $$('.ch', slopeSvg).forEach(gEl => {
    const ci = +gEl.dataset.c;
    const pts = MODELS.map((_, mi) => [X(mi), Y(share(mi, ci))]);
    const d = 'M' + pts.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' L');
    const ln = $('.ln', gEl);
    ln.setAttribute('d', d);
    ln.style.d = `path("${d}")`;
    $$('.dt', gEl).forEach((c, mi) => { c.style.transform = `translate(${pts[mi][0]}px,${pts[mi][1]}px)`; c.setAttribute('r', mi === L ? 4.6 : 3.2); c.classList.toggle('on', mi === L); });
    const lab = $('.lab', gEl);
    lab.style.transform = `translate(${W - m.r + 12}px,${ly[ci]}px)`;
    lab.innerHTML = `${SL.tight ? CHS[ci].s : CHS[ci].n} <tspan>${pct(share(MODELS.length - 1, ci), 0)}</tspan>`;
  });
  const band = $('.lensband', slopeSvg); if (band) band.style.transform = `translateX(${X(L)}px)`;
  $$('.col', slopeSvg).forEach(c => c.classList.toggle('is-lens', c.dataset.m === S.lens));
  slopeSvg.setAttribute('aria-label', `Slope chart: share of credit for seven channels across six models; lens is ${MODELS[L].n}`);
}
slopeSvg.addEventListener('click', e => {
  const col = e.target.closest('.col'); if (col) { setLens($(`[data-v="${col.dataset.m}"]`, modelBox)); return; }
});
slopeSvg.addEventListener('pointermove', e => {
  const ch = e.target.closest('.ch');
  $$('.ch', slopeSvg).forEach(g => g.classList.toggle('is-hot', g === ch));
  slopeSvg.classList.toggle('is-hover', !!ch);
  $$('.dbm-attrib__bars li').forEach(li => li.classList.toggle('is-hot', ch && li.dataset.c === ch.dataset.c));
  if (!ch) { hideTip(); return; }
  const ci = +ch.dataset.c;
  showTip(`<h4>${CHS[ci].n}</h4>` + MODELS.map((md, mi) => `<p class="${mi === MI[S.lens] ? 'is-lens' : ''}"><span>${md.n}</span><b>${fmtV(shownVal(mi, ci))} · ${pct(share(mi, ci))}</b></p>`).join(''), e.clientX, e.clientY);
});
slopeSvg.addEventListener('pointerleave', () => { slopeSvg.classList.remove('is-hover'); $$('.ch', slopeSvg).forEach(g => g.classList.remove('is-hot')); $$('.dbm-attrib__bars li').forEach(li => li.classList.remove('is-hot')); hideTip(); });

/* ---------------------------------------------------------------- shift bars */
const barList = $('.dbm-attrib__bars');
function flip(container, sel, key, mutate) {
  const before = new Map($$(sel, container).map(el => [el.dataset[key], el.getBoundingClientRect().top]));
  mutate();
  if (RM) return;
  $$(sel, container).forEach(el => {
    const b = before.get(el.dataset[key]); if (b == null) return;
    const dy = b - el.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) el.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function renderBars(intro) {
  const L = MI[S.lens], B = MI.last;
  $('.dbm-attrib__shift-h').textContent = `${MODELS[L].n} vs last touch`;
  const rows = CHS.map((c, ci) => ({ c, ci, l: share(L, ci), b: share(B, ci) })).sort((a, b) => b.l - a.l);
  const mx = Math.max(...rows.map(r => Math.max(r.l, r.b)));
  const old = new Map($$('li', barList).map(li => [li.dataset.c, li]));
  flip(barList, 'li', 'c', () => {
    rows.forEach((r, i) => {
      let li = old.get(String(r.ci));
      if (!li) { li = document.createElement('li'); li.dataset.c = r.ci; li.style.setProperty('--c', `var(--dbm-attrib-c-${r.c.k})`); li.style.setProperty('--i', i); li.innerHTML = `<span class="nm"><i></i><span class="full">${r.c.n}</span><span class="short">${r.c.s}</span></span><span class="tr"><i class="bl"></i><i class="le"></i></span><span class="vl"></span><span class="sub"></span><span class="dl"></span>`; }
      old.delete(String(r.ci));
      $('.bl', li).style.setProperty('--w', (r.b / mx).toFixed(4));
      $('.le', li).style.setProperty('--w', (r.l / mx).toFixed(4));
      $('.vl', li).textContent = fmtV(shownVal(L, r.ci));
      $('.sub', li).textContent = `${pct(r.l)} vs ${pct(r.b)}`;
      const d = r.b ? r.l / r.b - 1 : 0, dl = $('.dl', li);
      dl.textContent = S.lens === 'last' ? 'baseline' : sgn(d); dl.className = 'dl' + (S.lens === 'last' ? '' : d > .02 ? ' up' : d < -.02 ? ' dn' : '');
      barList.appendChild(li);
    });
  });
  barList.classList.toggle('is-intro', !!intro && !RM);
}

/* ---------------------------------------------------------------- channel table */
const tbody = $('.dbm-attrib__table tbody');
function renderTable() {
  const L = MI[S.lens], B = MI.last, conv = S.metric === 'conv';
  $('.dbm-attrib__cpa-h').textContent = conv ? 'Cost / conv.' : 'ACV per $1';
  const rows = CHS.map((c, ci) => {
    const v = shownVal(L, ci), b = shownVal(B, ci);
    return { c, ci, n: c.n, cost: costOf(c), v, share: share(L, ci), d: b ? v / b - 1 : 0, lift: Math.exp(M.beta[ci + 1]), cpa: c.cost ? (conv ? costOf(c) / v : v / costOf(c)) : (conv ? Infinity : -1) };
  });
  rows.sort((a, b) => { const x = a[S.sort], y = b[S.sort]; return (typeof x === 'string' ? x.localeCompare(y) : x - y) * S.dir; });
  $$('.dbm-attrib__table th').forEach(th => th.setAttribute('aria-sort', th.dataset.k === S.sort ? (S.dir > 0 ? 'ascending' : 'descending') : 'none'));
  const old = new Map($$('tr', tbody).map(tr => [tr.dataset.c, tr]));
  const mx = Math.max(...rows.map(r => r.share));
  flip(tbody, 'tr', 'c', () => {
    rows.forEach(r => {
      let tr = old.get(String(r.ci)); if (!tr) { tr = document.createElement('tr'); tr.dataset.c = r.ci; }
      old.delete(String(r.ci));
      tr.style.setProperty('--c', `var(--dbm-attrib-c-${r.c.k})`);
      tr.innerHTML = `<td><span class="nm"><i></i>${r.n}</span></td><td class="n">${r.cost ? money(r.cost) : '<small>none</small>'}</td><td class="n"><b>${fmtV(r.v)}</b></td><td><span class="sh" style="--w:${(r.share / mx).toFixed(4)}"><span></span><b>${pct(r.share)}</b></span></td><td class="n ${S.lens === 'last' ? '' : r.d > .02 ? 'up' : r.d < -.02 ? 'dn' : ''}">${S.lens === 'last' ? '<small>baseline</small>' : sgn(r.d)}</td><td class="n">${r.cost ? (conv ? '$' + NF.format(Math.round(r.cpa)) : '$' + r.cpa.toFixed(2)) : '<small>n/a</small>'}</td><td class="n">×${r.lift.toFixed(2)}</td>`;
      tbody.appendChild(tr);
    });
  });
  const totCost = CHS.reduce((a, c) => a + costOf(c), 0), totV = CHS.reduce((a, c, ci) => a + shownVal(L, ci), 0);
  $('.dbm-attrib__table tfoot').innerHTML = `<tr><td>All channels</td><td class="n">${money(totCost)}</td><td class="n">${fmtV(totV)}</td><td><small>100%</small></td><td></td><td class="n">${conv ? '$' + NF.format(Math.round(totCost / totV)) : '$' + (totV / totCost).toFixed(2)}</td><td></td></tr>`;
}
$('.dbm-attrib__table thead').addEventListener('click', e => {
  const th = e.target.closest('th'); if (!th) return;
  if (S.sort === th.dataset.k) S.dir *= -1; else { S.sort = th.dataset.k; S.dir = th.dataset.k === 'n' ? 1 : -1; }
  renderTable();
});

/* ---------------------------------------------------------------- paths */
const pf = $('.dbm-attrib__pfilter'), pathList = $('.dbm-attrib__paths');
pf.innerHTML = CHS.map((c, ci) => `<button aria-pressed="false" data-c="${ci}" style="--c:var(--dbm-attrib-c-${c.k})"><i></i>${c.n}</button>`).join('');
pf.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  const ci = +b.dataset.c; S.pf.has(ci) ? S.pf.delete(ci) : S.pf.add(ci);
  b.setAttribute('aria-pressed', S.pf.has(ci)); renderPaths(true);
});
const CHEV = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M3 2l3 3-3 3"/></svg>';
function renderPaths(rebuild) {
  const L = MI[S.lens];
  const mv = p => S.metric === 'conv' ? p.conv : p.rev;
  const single = M.paths.filter(p => p.t.length === 1).reduce((a, p) => a + mv(p), 0);
  const list = M.paths.filter(p => p.t.length > 1 && [...S.pf].every(ci => p.t.includes(ci))).sort((a, b) => mv(b) - mv(a)).slice(0, 14);
  const covered = list.reduce((a, p) => a + mv(p), 0);
  $('.dbm-attrib__pathsub').textContent = list.length ? `· these ${list.length} cover ${pct(covered / tot())}; single-touch paths, where every model agrees, are another ${pct(single / tot())}` : '· no multi-touch paths match';
  const keyed = new Map($$('li', pathList).map(li => [li.dataset.k, li]));
  if (rebuild) { pathList.innerHTML = ''; keyed.clear(); }
  flip(pathList, 'li', 'k', () => {
    list.forEach(p => {
      let li = keyed.get(p.key);
      if (!li) {
        li = document.createElement('li'); li.dataset.k = p.key;
        li.innerHTML = `<div class="seq">${p.t.map((c, i) => `${i ? CHEV : ''}<span style="--c:var(--dbm-attrib-c-${CHS[c].k})">${CHS[c].n}</span>`).join('')}</div><div class="split" role="img">${p.t.map(c => `<i style="--c:var(--dbm-attrib-c-${CHS[c].k})"></i>`).join('')}</div><div class="cnt"><b></b><small></small></div>`;
      }
      keyed.delete(p.key);
      const w = [...p.w[L]].map(x => x / p.conv);
      $$('.split i', li).forEach((s, i) => { s.style.setProperty('--w', Math.max(w[i], 0.0001).toFixed(4)); s.textContent = w[i] >= .12 ? Math.round(w[i] * 100) + '%' : ''; });
      $('.split', li).setAttribute('aria-label', `${MODELS[L].n} splits credit ` + p.t.map((c, i) => `${CHS[c].n} ${Math.round(w[i] * 100)}%`).join(', '));
      $('.cnt b', li).textContent = S.metric === 'conv' ? NF.format(p.conv) : money(p.rev);
      $('.cnt small', li).textContent = `${pct(p.conv / p.jn)} of ${NF.format(p.jn)}`;
      $('.cnt', li).title = `${NF.format(p.conv)} of ${NF.format(p.jn)} journeys on this exact path converted`;
      pathList.appendChild(li);
    });
    keyed.forEach(li => li.remove());
  });
}

/* ---------------------------------------------------------------- orchestration */
const drawn = {};
function renderView(entering) {
  if (S.view === 'compare') { drawSlope(!drawn.compare); renderBars(!drawn.compare); movePill(); drawn.compare = 1; }
  else if (S.view === 'channels') renderTable();
  else renderPaths(entering);
}
function renderAll(lensOnly) {
  renderInsight(true); renderFoot();
  if (S.view === 'compare' && SL) { if (!lensOnly) rescaleSlope(); updateSlope(false); renderBars(false); }
  else renderView(false);
}
// filters change the data range: redraw the y grid but keep the line elements so their d transitions
function rescaleSlope() {
  const ny = nice(Math.max(...MODELS.flatMap((_, mi) => CHS.map((_, ci) => share(mi, ci)))) * 1.05, 4);
  const { m, H, W } = SL;
  SL.Y = v => H - m.b - v / ny.max * (H - m.t - m.b);
  $$('.gl, .gl + text', slopeSvg).forEach(n => n.remove());
  let g = '';
  for (let v = 0; v <= ny.max + 1e-9; v += ny.st) g += `<line class="gl" x1="${m.l}" x2="${W - m.r + 6}" y1="${SL.Y(v)}" y2="${SL.Y(v)}"/><text x="${m.l - 6}" y="${SL.Y(v) + 3.5}" text-anchor="end">${Math.round(v * 100)}%</text>`;
  slopeSvg.insertAdjacentHTML('afterbegin', g);
}

compute();
renderInsight(false); renderFoot();
renderView(true);
let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; if (S.view === 'compare') { drawSlope(false); movePill(); } });
});
ro.observe(slopeSvg.parentElement);
ro.observe(modelBox);

