@property --dbm-email-heatk {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}
.dbm-email {
  /* re-theme with these four */
  --dbm-email-bg: oklch(0.985 0.004 240);
  --dbm-email-ink: oklch(0.25 0.03 258);
  --dbm-email-accent: oklch(0.585 0.2 27);
  --dbm-email-air: oklch(0.5 0.13 258);
  /* derived */
  --dbm-email-card: oklch(1 0 0);
  --dbm-email-side: color-mix(in oklch, var(--dbm-email-bg), var(--dbm-email-air) 4%);
  --dbm-email-line: color-mix(in oklch, var(--dbm-email-ink) 12%, transparent);
  --dbm-email-hair: color-mix(in oklch, var(--dbm-email-ink) 6.5%, transparent);
  --dbm-email-mute: color-mix(in oklch, var(--dbm-email-ink) 62%, var(--dbm-email-bg));
  --dbm-email-faint: color-mix(in oklch, var(--dbm-email-ink) 42%, var(--dbm-email-bg));
  --dbm-email-good: oklch(0.55 0.13 155);
  --dbm-email-t-launch: var(--dbm-email-accent);
  --dbm-email-t-newsletter: var(--dbm-email-air);
  --dbm-email-t-promo: oklch(0.7 0.15 68);
  --dbm-email-t-lifecycle: oklch(0.58 0.11 165);
  --dbm-email-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-email-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-email-out: cubic-bezier(.22, 1, .36, 1);
  --dbm-email-spring: linear(0, .05 2%, .22 5.5%, .5 10%, .78 15.5%, .95 21%, 1.03 27%, 1.05 32%, 1.03 40%, 1.005 52%, .998 68%, 1);
  width: 100%;
  height: var(--dbm-email-h, 680px);
  container-type: inline-size;
  container-name: dbm-email;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dbm-email-bg);
  color: var(--dbm-email-ink);
  font: 13px/1.45 var(--dbm-email-sans);
  accent-color: var(--dbm-email-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dbm-email-line);
  /* airmail edge */
  &::before {
    content: ""; position: absolute; inset: 0 0 auto 0; height: 5px; z-index: 5;
    background: repeating-linear-gradient(-45deg, var(--dbm-email-accent) 0 10px, var(--dbm-email-card) 10px 16px, var(--dbm-email-air) 16px 26px, var(--dbm-email-card) 26px 32px);
  }
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button, select, input) { font: inherit; color: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-email-air); outline-offset: 2px; border-radius: 6px; }
}
.dbm-email__app {
  height: 100%;
  padding-top: 5px;
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head" "side main";
}

/* ------------------------------------------------------------ sends sidebar */
.dbm-email__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px;
  padding: 16px 0 0; background: var(--dbm-email-side); border-right: 1px solid var(--dbm-email-line);
}
.dbm-email__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 16px;
  & svg { width: 28px; height: 28px; padding: 5px; border-radius: 8px; background: var(--dbm-email-accent); fill: none; stroke: white; stroke-width: 1.8; stroke-linejoin: round; flex: none; }
  & span { display: grid; line-height: 1.2; }
  & b { font-weight: 720; letter-spacing: -.015em; }
  & small { font-size: 11px; color: var(--dbm-email-faint); }
}
.dbm-email__search {
  margin: 4px 16px 0; display: flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px; border-radius: 9px;
  background: var(--dbm-email-card); box-shadow: inset 0 0 0 1px var(--dbm-email-line);
  & svg { width: 15px; height: 15px; fill: none; stroke: var(--dbm-email-faint); stroke-width: 2; stroke-linecap: round; flex: none; }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 12.5px; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dbm-email-air); }
}
.dbm-email__types {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 0 16px;
  & button { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 999px; font-size: 11px; font-weight: 600; color: var(--dbm-email-mute); box-shadow: inset 0 0 0 1px var(--dbm-email-line); transition: background-color .15s, color .15s; }
  & button i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
  & button[aria-pressed="true"] { background: color-mix(in oklch, var(--c) 13%, var(--dbm-email-card)); color: var(--dbm-email-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent); }
}
.dbm-email__sortrow { display: flex; justify-content: space-between; align-items: center; padding: 0 16px; font-size: 11px; color: var(--dbm-email-faint); }
.dbm-email__sort {
  display: inline-flex; align-items: center; gap: 6px;
  & select { height: 24px; border-radius: 6px; border: 0; padding: 0 6px; background: var(--dbm-email-card); box-shadow: inset 0 0 0 1px var(--dbm-email-line); font-size: 11.5px; font-weight: 600; }
}
.dbm-email__list {
  flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbm-email-line) transparent;
  padding: 2px 10px 12px; display: grid; align-content: start; gap: 2px;
  & li {
    --c: var(--dbm-email-faint);
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 8px;
    padding: 9px 10px 9px 13px; border-radius: 10px; cursor: pointer; transition: background-color .15s;
  }
  & li::before { content: ""; position: absolute; left: 4px; top: 11px; bottom: 11px; width: 3px; border-radius: 2px; background: var(--c); }
  & li:hover { background: var(--dbm-email-hair); }
  & li[aria-selected="true"] { background: var(--dbm-email-card); box-shadow: 0 0 0 1px var(--dbm-email-line), 0 4px 14px -8px color-mix(in oklch, var(--dbm-email-ink) 35%, transparent); }
  & li:focus-visible { outline-offset: -2px; }
  & .sj { grid-column: 1 / -1; font-size: 12.5px; font-weight: 620; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: pretty; }
  & .mt { font-size: 11px; color: var(--dbm-email-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .st { font: 600 11px var(--dbm-email-mono); color: var(--dbm-email-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .live { color: var(--dbm-email-accent); }
  & mark { background: color-mix(in oklch, var(--dbm-email-t-promo) 35%, transparent); color: inherit; border-radius: 2px; }
}
.dbm-email__list.is-intro li { animation: dbm-email-in .55s var(--dbm-email-out) both; animation-delay: calc(var(--i) * 32ms); }
@keyframes dbm-email-in { from { opacity: 0; translate: -10px 0; } }
.dbm-email__empty { padding: 20px 16px; font-size: 12px; color: var(--dbm-email-faint); text-align: center; }

/* ------------------------------------------------------------ header */
.dbm-email__head {
  grid-area: head; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 16px; align-items: center;
  padding: 14px 20px 12px; border-bottom: 1px solid var(--dbm-email-line);
}
.dbm-email__stamp {
  width: 62px; height: 62px; rotate: -9deg; color: var(--dbm-email-accent);
  & svg { width: 100%; height: 100%; overflow: visible; }
  & circle { fill: none; stroke: currentColor; stroke-width: 1.6; }
  & circle + circle { stroke-width: .8; stroke-dasharray: 2 2; }
  & text { fill: currentColor; font: 800 13px var(--dbm-email-mono); letter-spacing: .04em; }
  & .dbm-email__st-t { font-size: 10px; font-weight: 600; }
}
.dbm-email__stamp.is-stamp { animation: dbm-email-stamp .55s cubic-bezier(.3, 1.6, .5, 1) both; }
@keyframes dbm-email-stamp { from { scale: 1.45; opacity: 0; rotate: -2deg; } }
.dbm-email__meta { font: 600 10.5px var(--dbm-email-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-email-faint); display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.dbm-email__meta .tg { color: var(--c); }
.dbm-email__subject { font-size: clamp(17px, 2.1cqi, 22px); font-weight: 700; letter-spacing: -.025em; line-height: 1.2; margin: 3px 0 2px; text-wrap: balance; }
.dbm-email__pre { font-size: 12px; color: var(--dbm-email-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dbm-email__tabs {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dbm-email-hair); align-self: start;
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dbm-email-mute); white-space: nowrap; transition: background-color .2s, color .2s, box-shadow .2s; }
  & button[aria-selected="true"] { background: var(--dbm-email-card); color: var(--dbm-email-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbm-email-ink) 16%, transparent); }
}

/* ------------------------------------------------------------ report view */
.dbm-email__main { grid-area: main; min-height: 0; padding: 14px 20px 18px; }
.dbm-email__view { height: 100%; min-height: 0; display: grid; gap: 12px; }
.dbm-email__view[hidden] { display: none; }
.dbm-email__view:not([hidden]) { animation: dbm-email-fade .4s var(--dbm-email-out) both; }
@keyframes dbm-email-fade { from { opacity: 0; } }
.dbm-email__v-report {
  grid-template-columns: minmax(0, 1.12fr) minmax(290px, .88fr);
  grid-template-rows: auto minmax(0, 1.05fr) minmax(0, 1fr);
  grid-template-areas: "funnel funnel" "curve prev" "links prev";
}
.dbm-email__panel {
  min-height: 0; border-radius: 12px; background: var(--dbm-email-card);
  box-shadow: 0 0 0 1px var(--dbm-email-line), 0 1px 3px color-mix(in oklch, var(--dbm-email-ink) 5%, transparent);
  overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbm-email-line) transparent;
}
.dbm-email__ph {
  display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; padding: 11px 14px 4px;
  & h3 { font-size: 13px; font-weight: 680; letter-spacing: -.01em; }
  & h3 small { font-weight: 500; color: var(--dbm-email-faint); font-size: 11px; margin-left: 3px; }
  & p { width: 100%; font-size: 11.5px; color: var(--dbm-email-mute); text-wrap: pretty; }
}

.dbm-email__funnel {
  grid-area: funnel; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0;
  border-radius: 12px; background: var(--dbm-email-card); box-shadow: 0 0 0 1px var(--dbm-email-line);
  & li { position: relative; padding: 10px 14px 11px; display: grid; gap: 1px; }
  & li + li { border-left: 1px solid var(--dbm-email-hair); }
  & .k { font: 600 10px var(--dbm-email-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbm-email-faint); display: flex; gap: 6px; align-items: center; white-space: nowrap; }
  & .k em { font-style: normal; letter-spacing: 0; text-transform: none; padding: 1px 5px; border-radius: 4px; background: var(--dbm-email-hair); color: var(--dbm-email-mute); overflow: hidden; text-overflow: ellipsis; }
  & .v { font-size: clamp(16px, 1.9cqi, 21px); font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & .d { font-size: 11px; color: var(--dbm-email-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .d .up { color: var(--dbm-email-good); font-weight: 650; }
  & .d .dn { color: var(--dbm-email-accent); font-weight: 650; }
  & .bar { height: 4px; border-radius: 2px; background: var(--dbm-email-hair); margin-top: 5px; overflow: hidden; }
  & .bar i { display: block; height: 100%; width: calc(var(--w) * 100%); min-width: 2px; background: var(--dbm-email-air); border-radius: 2px; transition: width .7s var(--dbm-email-out); }
  & li:last-child .bar i { background: var(--dbm-email-accent); }
}

.dbm-email__curvep { grid-area: curve; display: flex; flex-direction: column; }
.dbm-email__key {
  display: flex; gap: 10px; font-size: 10.5px; color: var(--dbm-email-faint);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li::before { content: ""; width: 10px; height: 8px; border-radius: 2px; background: color-mix(in oklch, var(--dbm-email-air) 30%, transparent); }
  & li.c::before { height: 2px; background: var(--dbm-email-air); }
  & li.a::before { height: 0; border-top: 1.5px dashed var(--dbm-email-mute); }
}
.dbm-email__plot { position: relative; flex: 1; min-height: 120px; margin: 0 8px 6px; & svg { display: block; width: 100%; height: 100%; overflow: visible; } }
.dbm-email__plot {
  & text { font: 500 10px var(--dbm-email-mono); fill: var(--dbm-email-faint); font-variant-numeric: tabular-nums; }
  & .gl { stroke: var(--dbm-email-hair); }
  & .night { fill: color-mix(in oklch, var(--dbm-email-air) 5%, transparent); }
  & .hb { fill: color-mix(in oklch, var(--dbm-email-air) 30%, transparent); transform-box: fill-box; transform-origin: bottom; transition: fill .15s; }
  & .hb.on { fill: var(--dbm-email-air); }
  & .cum { fill: none; stroke: var(--dbm-email-air); stroke-width: 2; stroke-linejoin: round; }
  & .avg { fill: none; stroke: var(--dbm-email-mute); stroke-width: 1.4; stroke-dasharray: 4 3; }
  & .now { stroke: var(--dbm-email-accent); stroke-dasharray: 2 2; }
  & .now-t { fill: var(--dbm-email-accent); font-weight: 650; }
  & .xh { stroke: var(--dbm-email-ink); opacity: .35; }
  & .hit { fill: transparent; }
}
.dbm-email__plot svg.is-intro {
  & .hb { animation: dbm-email-grow .6s var(--dbm-email-out) both; animation-delay: calc(var(--i) * 9ms); }
  & .cum { stroke-dasharray: 1 1; animation: dbm-email-draw 1.2s .25s var(--dbm-email-out) both; }
  & .avg { animation: dbm-email-fade .6s .9s both; }
}
@keyframes dbm-email-grow { from { scale: 1 0; } }
@keyframes dbm-email-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }

.dbm-email__linksp { grid-area: links; }
.dbm-email__links {
  width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; font-size: 12px;
  & th { position: sticky; top: 0; background: var(--dbm-email-card); text-align: left; padding: 6px 14px; font: 600 10px var(--dbm-email-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-email-faint); border-bottom: 1px solid var(--dbm-email-line); z-index: 1; }
  & th.n, & td.n { text-align: right; }
  & td { padding: 6px 14px; border-bottom: 1px solid var(--dbm-email-hair); white-space: nowrap; }
  & td:first-child { max-width: 200px; overflow: hidden; text-overflow: ellipsis; }
  & tr { transition: background-color .15s; }
  & tbody tr:hover, & tbody tr.is-hot { background: color-mix(in oklch, var(--dbm-email-accent) 8%, transparent); }
  & .sh { display: flex; align-items: center; gap: 8px; }
  & .sh span { flex: 1; height: 5px; border-radius: 3px; background: var(--dbm-email-hair); min-width: 50px; position: relative; overflow: hidden; }
  & .sh span::before { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(var(--w) * 100%); background: var(--dbm-email-accent); border-radius: 3px; }
  & .sh b { font-weight: 600; width: 40px; text-align: right; }
  & .warn { color: var(--dbm-email-accent); }
}

/* ------------------------------------------------------------ email preview + click map */
.dbm-email__prevp { grid-area: prev; display: flex; flex-direction: column; background: color-mix(in oklch, var(--dbm-email-side), var(--dbm-email-ink) 2%); }
.dbm-email__prevh { position: sticky; top: 0; z-index: 3; background: inherit; padding-bottom: 8px; }
.dbm-email__toggle { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 600; color: var(--dbm-email-mute); cursor: pointer; & input { margin: 0; } }
.dbm-email__mail {
  --dbm-email-heatk: 0;
  margin: 0 14px 16px; border-radius: 6px; background: var(--dbm-email-card); color: oklch(0.28 0.03 50);
  box-shadow: 0 0 0 1px var(--dbm-email-line), 0 10px 26px -14px color-mix(in oklch, var(--dbm-email-ink) 40%, transparent);
  font: 12px/1.5 var(--dbm-email-sans); overflow: hidden;
  & .top { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; border-bottom: 1px solid oklch(0.93 0.01 70); }
  & .logo { font: 800 11px var(--dbm-email-mono); letter-spacing: .22em; }
  & .pre { font-size: 10px; color: oklch(0.55 0.02 60); max-width: 55%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .hero { display: grid; place-items: center; height: 128px; margin: 14px 16px 0; border-radius: 4px; background: linear-gradient(140deg, var(--g1), var(--g2)); position: relative; }
  & .hero svg { width: 96px; height: 96px; fill: none; stroke: oklch(1 0 0 / .85); stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
  & .hero .tag { position: absolute; left: 10px; bottom: 9px; font: 700 9.5px var(--dbm-email-mono); letter-spacing: .14em; color: white; text-transform: uppercase; }
  & h4 { font-size: 17px; line-height: 1.2; letter-spacing: -.02em; margin: 14px 16px 6px; text-wrap: balance; }
  & p { margin: 0 16px 12px; color: oklch(0.42 0.02 60); text-wrap: pretty; }
  & .cta { display: block; width: fit-content; margin: 2px auto 14px; padding: 9px 18px; border-radius: 4px; background: oklch(0.3 0.03 50); color: white; font-weight: 700; font-size: 12px; }
  & .code { display: block; margin: 14px 16px 0; padding: 10px; border: 1.5px dashed oklch(0.7 0.15 68); border-radius: 4px; text-align: center; font-size: 11px; }
  & .code b { display: block; font: 800 16px var(--dbm-email-mono); letter-spacing: .12em; }
  & .grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 0 16px 14px; }
  & .prod { display: grid; gap: 4px; padding: 6px; border-radius: 4px; font-size: 10.5px; line-height: 1.3; }
  & .prod i { display: block; aspect-ratio: 1; border-radius: 3px; background: linear-gradient(160deg, color-mix(in oklch, var(--pc) 60%, white), var(--pc)); }
  & .prod b { font-weight: 650; }
  & .prod span { color: oklch(0.55 0.02 60); }
  & .art { display: grid; grid-template-columns: 54px 1fr; gap: 10px; margin: 0 16px 10px; padding: 6px; border-radius: 4px; align-items: center; font-size: 11.5px; }
  & .art i { aspect-ratio: 1; border-radius: 3px; background: linear-gradient(160deg, color-mix(in oklch, var(--pc) 50%, white), var(--pc)); }
  & .art b { display: block; font-size: 12px; }
  & .more { display: block; margin: 0 16px 14px; font-weight: 650; color: oklch(0.45 0.12 40); }
  & .foot { padding: 12px 16px 14px; border-top: 1px solid oklch(0.93 0.01 70); font-size: 10px; color: oklch(0.55 0.02 60); text-align: center; }
  & .foot .lk { text-decoration: underline; }
  & .lk { position: relative; cursor: default; border-radius: 4px; transition: box-shadow .25s; }
  & .logo, & .foot .lk { display: inline-block; }
  & .lk::before { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; background: transparent; transition: background-color .3s; }
  & .lk:focus-visible { outline-offset: 1px; }
}
.dbm-email__prevp:has(input:checked) .dbm-email__mail {
  --dbm-email-heatk: 1;
  transition: --dbm-email-heatk .6s var(--dbm-email-out);
  & .lk { box-shadow: 0 0 0 calc(1px + var(--heat) * 2px) color-mix(in oklch, var(--dbm-email-accent) calc(25% + var(--heat) * 75%), transparent); }
  & .lk::before { background-color: color-mix(in oklch, var(--dbm-email-accent) calc(var(--heat) * 24%), transparent); }
  & .lk::after {
    content: attr(data-pct); position: absolute; right: -8px; top: -11px; z-index: 2;
    padding: 1px 5px; border-radius: 999px; background: var(--dbm-email-accent); color: white;
    font: 700 9.5px/1.4 var(--dbm-email-mono); white-space: nowrap; box-shadow: 0 2px 6px -2px rgb(0 0 0 / .35);
    scale: var(--dbm-email-heatk);
  }
  & .lk.is-hot { box-shadow: 0 0 0 3px var(--dbm-email-ink); }
  & .foot .lk::after { top: -16px; }
}
.dbm-email__mail.is-swap { animation: dbm-email-letter .55s var(--dbm-email-out) both; }
.dbm-email__prevp:has(input:checked) .dbm-email__mail.is-swap .lk::after { animation: dbm-email-badge .5s var(--dbm-email-spring) both; animation-delay: calc(280ms + var(--i, 0) * 45ms); }
@keyframes dbm-email-badge { from { scale: 0; } }
@keyframes dbm-email-letter { from { opacity: 0; translate: 0 14px; rotate: .6deg; } }

/* ------------------------------------------------------------ trends view */
.dbm-email__v-trends { grid-template-columns: minmax(0, 1.6fr) minmax(250px, 1fr); }
.dbm-email__trendp { display: flex; flex-direction: column; }
.dbm-email__tplot { margin: 4px 10px 10px; min-height: 300px; }
.dbm-email__tplot {
  & .dot { stroke: var(--dbm-email-card); stroke-width: 1.5; fill: var(--c); cursor: pointer; transition: r .2s var(--dbm-email-out); }
  & .dot.is-sel { stroke: var(--dbm-email-ink); stroke-width: 2; }
  & .dot.on { r: 7px; }
  & .stem { stroke: var(--dbm-email-line); }
  & .med { stroke: var(--dbm-email-mute); stroke-dasharray: 3 3; }
  & .rowt { fill: var(--dbm-email-ink); font: 650 11px var(--dbm-email-sans); }
  & .band { fill: var(--dbm-email-hair); }
}
.dbm-email__tplot svg.is-intro .dot { animation: dbm-email-pop .5s var(--dbm-email-spring) both; animation-delay: calc(var(--i) * 35ms); transform-box: fill-box; transform-origin: center; }
@keyframes dbm-email-pop { from { scale: 0; } }
.dbm-email__typegrid {
  padding: 6px 14px 14px; display: grid; gap: 12px;
  & .ty { display: grid; gap: 6px; padding: 10px 12px; border-radius: 10px; background: color-mix(in oklch, var(--c) 6%, var(--dbm-email-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 22%, transparent); }
  & .ty h4 { font-size: 12.5px; display: flex; justify-content: space-between; align-items: baseline; }
  & .ty h4 small { font: 500 10.5px var(--dbm-email-mono); color: var(--dbm-email-faint); }
  & .ty h4::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--c); margin-right: 6px; display: inline-block; }
  & .ty h4 span { display: inline-flex; align-items: center; }
  & dl { margin: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
  & dt { font: 600 9.5px var(--dbm-email-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dbm-email-faint); }
  & dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; font-size: 14px; letter-spacing: -.02em; }
}

/* ------------------------------------------------------------ tooltip */
.dbm-email__tip {
  position: absolute; z-index: 30; left: 0; top: 0; pointer-events: none; min-width: 160px; max-width: 260px; padding: 8px 10px; border-radius: 8px;
  background: var(--dbm-email-card); box-shadow: 0 0 0 1px var(--dbm-email-line), 0 12px 28px -10px color-mix(in oklch, var(--dbm-email-ink) 45%, transparent);
  font-size: 11.5px; font-variant-numeric: tabular-nums; opacity: 0; transition: opacity .15s;
  &.is-on { opacity: 1; }
  & h4 { font-size: 12px; margin-bottom: 4px; line-height: 1.3; }
  & p { display: flex; justify-content: space-between; gap: 14px; color: var(--dbm-email-mute); }
  & p b { color: var(--dbm-email-ink); }
}

/* ------------------------------------------------------------ container responses */
@container dbm-email (width < 1060px) {
  .dbm-email__app { grid-template-columns: 240px minmax(0, 1fr); }
  .dbm-email__head { grid-template-columns: minmax(0, 1fr) auto; }
  .dbm-email__stamp { display: none; }
}
@container dbm-email (width < 960px) {
  .dbm-email__main { overflow: auto; scrollbar-width: thin; }
  .dbm-email__view { height: auto; }
  .dbm-email__v-report { grid-template-columns: minmax(0, 1fr); grid-template-rows: none; grid-template-areas: "funnel" "curve" "prev" "links"; }
  .dbm-email__curvep { height: 240px; }
  .dbm-email__prevp, .dbm-email__linksp { overflow: visible; }
  .dbm-email__funnel { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .dbm-email__funnel li:nth-child(4) { border-left: 0; }
  .dbm-email__funnel li:nth-child(n+4) { border-top: 1px solid var(--dbm-email-hair); }
  .dbm-email__v-trends { grid-template-columns: minmax(0, 1fr); }
  .dbm-email__tplot { height: 360px; flex: none; }
}
@container dbm-email (width < 760px) {
  .dbm-email__app { display: block; overflow: auto; scrollbar-width: thin; }
  .dbm-email__side { position: sticky; top: 0; z-index: 10; padding: 10px 0 8px; gap: 8px; border-right: 0; border-bottom: 1px solid var(--dbm-email-line); }
  .dbm-email__brand small, .dbm-email__sortrow { display: none; }
  .dbm-email__search { margin-top: 0; }
  .dbm-email__list {
    flex: none; display: flex; overflow-x: auto; overflow-y: hidden; scroll-snap-type: x mandatory; padding: 2px 12px 4px; gap: 6px;
    & li { flex: 0 0 210px; scroll-snap-align: start; background: var(--dbm-email-card); box-shadow: 0 0 0 1px var(--dbm-email-hair); }
    & .sj { -webkit-line-clamp: 1; }
  }
  .dbm-email__head { padding: 12px 14px 10px; grid-template-columns: minmax(0, 1fr); }
  .dbm-email__tabs { justify-self: start; }
  .dbm-email__main { padding: 12px 14px 16px; overflow: visible; }
}
@container dbm-email (width < 480px) {
  .dbm-email__funnel { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dbm-email__funnel li:nth-child(n) { border-left: 0; border-top: 1px solid var(--dbm-email-hair); }
  .dbm-email__funnel li:nth-child(even) { border-left: 1px solid var(--dbm-email-hair); }
  .dbm-email__funnel li:first-child { border-top: 0; grid-column: 1 / -1; }
  .dbm-email__funnel li:nth-child(2) { border-left: 0; }
  .dbm-email__funnel li:nth-child(3) { border-left: 1px solid var(--dbm-email-hair); }
  .dbm-email__funnel li:nth-child(4) { border-left: 0; }
  .dbm-email__funnel li:nth-child(5) { border-left: 1px solid var(--dbm-email-hair); }
  .dbm-email__c-share, .dbm-email__links td:nth-child(3) { display: none; }
  .dbm-email__key li.a { display: none; }
  .dbm-email__mail .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dbm-email__mail .grid .prod:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dbm-email__list.is-intro li, .dbm-email__view:not([hidden]), .dbm-email__stamp.is-stamp, .dbm-email__mail.is-swap,
  .dbm-email__prevp:has(input:checked) .dbm-email__mail.is-swap .lk::after,
  .dbm-email__tplot svg.is-intro .dot { animation: none; }
  .dbm-email__plot svg.is-intro * { animation: none; stroke-dasharray: none; }
  .dbm-email__plot svg.is-intro .avg { stroke-dasharray: 4 3; }
  .dbm-email__funnel .bar i, .dbm-email__mail .lk, .dbm-email__prevp:has(input:checked) .dbm-email__mail .lk::after,
  .dbm-email__prevp:has(input:checked) .dbm-email__mail { transition-duration: .01s; }
}

