const LINKW = { logo: .03, hero: .17, cta: .36, p0: .11, p1: .08, p2: .06, more: .08, a0: .3, a1: .22, a2: .16, code: .14, prefs: .015 };
function diurnal(h) { const x = ((h % 24) + 24) % 24; return x < 6 ? .12 : x < 7 ? .5 : x < 10 ? 1 : x < 12 ? .7 : x < 14 ? .9 : x < 17 ? .6 : x < 19 ? .75 : x < 23 ? .95 : .35; }
const SENDS = DEF.map(d => {
  const P = PROFILE[d.ty], t0 = Date.UTC(2026, d.at[0] - 1, d.at[1], d.at[2], d.at[3]);
