const hl = s => { const t = esc(s); if (!S.q) return t; const i = s.toLowerCase().indexOf(S.q); return i < 0 ? t : esc(s.slice(0, i)) + '<mark>' + esc(s.slice(i, i + S.q.length)) + '</mark>' + esc(s.slice(i + S.q.length)); };
