  renderSend(true);
}
list.addEventListener('click', e => { const li = e.target.closest('li[role="option"]'); if (li) { select(li.dataset.id); if (S.view !== 'report') setView('report'); } });
list.addEventListener('keydown', e => {
  const items = $$('li[role="option"]', list), i = items.indexOf(document.activeElement); if (i < 0) return;
  const n = { ArrowDown: i + 1, ArrowUp: i - 1, ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: items.length - 1 }[e.key];
  if (n == null) return; e.preventDefault();
  select(items[Math.max(0, Math.min(items.length - 1, n))].dataset.id, true);
});

/* ---------------------------------------------------------------- tabs */
const tabs = $$('.dbm-email__tabs [role="tab"]');
function setView(v, focus) {
  S.view = v; hideTip();
  tabs.forEach(t => { const on = t.dataset.view === v; t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); });
  $$('.dbm-email__view').forEach(p => p.hidden = p.dataset.view !== v);
  if (v === 'trends') renderTrends(true); else drawCurve(false);
}
$('.dbm-email__tabs').addEventListener('click', e => { const t = e.target.closest('[role="tab"]'); if (t) setView(t.dataset.view); });
$('.dbm-email__tabs').addEventListener('keydown', e => {
  if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
  e.preventDefault(); const i = tabs.indexOf(document.activeElement); setView(tabs[(i + 1) % 2].dataset.view, true);
});

/* ---------------------------------------------------------------- the selected send */
function renderSend(swap) {
  const s = byId[S.sel], A = typeAvg(s.ty, s.id);
  $('.dbm-email__st-d').textContent = new Date(s.t0).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }).toUpperCase();
  $('.dbm-email__st-t').textContent = timeFmt(s.t0);
  const st = $('.dbm-email__stamp'); st.classList.remove('is-stamp'); if (swap && !RM) { void st.offsetWidth; st.classList.add('is-stamp'); }
  $('.dbm-email__meta').innerHTML = `<span class="tg" style="--c:var(--dbm-email-t-${s.ty})">${TYPES[s.ty]}</span><span>${esc(s.list)}</span><span>${dayFmt(s.t0)}, ${timeFmt(s.t0)}</span>${s.live ? `<span class="tg" style="--c:var(--dbm-email-accent)">collecting, ${s.elapsed}h of 72h</span>` : ''}`;
  $('.dbm-email__subject').textContent = s.sj;
  $('.dbm-email__pre').textContent = s.pre;
  const dlt = (v, a) => `<span class="${v >= a ? 'up' : 'dn'}">${pts(v - a)}</span> vs ${TYPES[s.ty].toLowerCase()} avg`;
  const steps = [
    ['Sent', NF.format(s.sent), 1, '', `${esc(s.list)}`],
    ['Delivered', NF.format(s.delivered), s.delivered / s.sent, pct(s.delivered / s.sent), `${NF.format(s.sent - s.delivered)} bounced`],
    ['Opened', pct(openRate(s)), s.opens / s.sent, pct(openRate(s)), dlt(openRate(s), A.open)],
    ['Clicked', pct(ctr(s), 2), s.clicks / s.sent, pct(s.clicks / s.opens) + ' CTOR', dlt(ctr(s), A.ctr)],
    ['Revenue', money(s.revenue), s.orders / s.sent, pct(s.orders / s.clicks) + ' conv.', `${NF.format(s.orders)} orders · $${rev1k(s).toFixed(0)} per 1k`]
  ];
  $('.dbm-email__funnel').innerHTML = steps.map(([k, v, w, rate, d]) => `<li><span class="k">${k}${rate ? `<em>${rate}</em>` : ''}</span><span class="v">${v}</span><span class="d">${d}</span><span class="bar"><i style="--w:${w.toFixed(4)}"></i></span></li>`).join('');
  drawCurve(swap);
  renderLinks();
  renderMail(swap);
}

/* ---------------------------------------------------------------- opens curve */
const cSvg = $('.dbm-email__curvep svg');
let CV = null;
function drawCurve(intro) {
  const s = byId[S.sel], box = cSvg.parentElement, W = box.clientWidth, H = box.clientHeight; if (!W || !H) return;
  const prior = SENDS.filter(x => x.t0 < s.t0 && !x.live).slice(-10);
  const avg = Array.from({ length: 72 }, (_, h) => prior.reduce((a, x) => a + x.opensH.slice(0, h + 1).reduce((p, q) => p + q, 0) / x.delivered, 0) / Math.max(1, prior.length));
  const m = { l: 40, r: 38, t: 8, b: 20 }, bw = (W - m.l - m.r) / 72;
  const shown = s.opensH.slice(0, s.elapsed), mx = Math.max(...s.opensH) * 1.08;
  const cum = []; let run = 0; shown.forEach(v => { run += v; cum.push(run / s.delivered); });
  const cmx = Math.ceil(Math.max(avg[71], cum[cum.length - 1], .1) * 10 + .5) / 10;
  const X = h => m.l + h * bw, Y = v => H - m.b - v / mx * (H - m.t - m.b), YC = v => H - m.b - v / cmx * (H - m.t - m.b);
  let g = '';
  for (let h = 0; h < 72; h++) { const hr = (s.at[2] + h) % 24; if (hr === 0) g += `<rect class="night" x="${X(h)}" y="${m.t}" width="${bw * 6}" height="${H - m.t - m.b}"/>`; }
  for (let k = 0; k <= 4; k++) { const v = cmx * k / 4; g += `<line class="gl" x1="${m.l}" x2="${W - m.r}" y1="${YC(v)}" y2="${YC(v)}"/><text x="${W - m.r + 5}" y="${YC(v) + 3}">${Math.round(v * 100)}%</text><text x="${m.l - 5}" y="${YC(v) + 3}" text-anchor="end">${NF.format(Math.round(mx * k / 4 / 10) * 10)}</text>`; }
  [0, 12, 24, 36, 48, 60, 72].forEach(h => g += `<text x="${X(h)}" y="${H - 5}" text-anchor="middle">${h}h</text>`);
  shown.forEach((v, h) => g += `<rect class="hb" data-h="${h}" style="--i:${h}" x="${(X(h) + .5).toFixed(1)}" y="${Y(v).toFixed(1)}" width="${Math.max(1, bw - 1).toFixed(1)}" height="${(H - m.b - Y(v)).toFixed(1)}"/>`);
  g += `<path class="avg" d="M${avg.map((v, h) => X(h + 1).toFixed(1) + ' ' + YC(v).toFixed(1)).join('L')}"/>`;
  g += `<path class="cum" pathLength="1" d="M${X(0)} ${YC(0)}L${cum.map((v, h) => X(h + 1).toFixed(1) + ' ' + YC(v).toFixed(1)).join('L')}"/>`;
  if (s.live) g += `<line class="now" x1="${X(s.elapsed)}" x2="${X(s.elapsed)}" y1="${m.t}" y2="${H - m.b}"/><text class="now-t" x="${X(s.elapsed) + 4}" y="${m.t + 10}">now</text>`;
  g += `<line class="xh" y1="${m.t}" y2="${H - m.b}" style="display:none"/><rect class="hit" x="${m.l}" y="${m.t}" width="${W - m.l - m.r}" height="${H - m.t - m.b}"/>`;
  cSvg.setAttribute('viewBox', `0 0 ${W} ${H}`); cSvg.innerHTML = g;
  CV = { s, X, bw, m, W, cum, avg };
  cSvg.classList.remove('is-intro');
  if (intro && !RM) { void cSvg.getBoundingClientRect(); cSvg.classList.add('is-intro'); }
}
cSvg.addEventListener('pointermove', e => {
  if (!CV) return;
  const { s, bw, m, W, cum, avg } = CV, r = cSvg.getBoundingClientRect(), px = (e.clientX - r.left) * W / r.width;
  const h = Math.floor((px - m.l) / bw); if (h < 0 || h > 71) return;
  const xh = $('.xh', cSvg); xh.style.display = ''; xh.setAttribute('x1', CV.X(h + .5)); xh.setAttribute('x2', CV.X(h + .5));
  $$('.hb', cSvg).forEach(b => b.classList.toggle('on', +b.dataset.h === h));
  const clock = timeFmt(s.t0 + h * HOUR), day = dayFmt(s.t0 + h * HOUR);
  if (h >= s.elapsed) { showTip(`<h4>Hour ${h + 1} · ${day} ${clock}</h4><p><span>Not reached yet</span></p><p><span>Avg of last 10</span><b>${pct(avg[h])}</b></p>`, e.clientX, e.clientY); return; }
  showTip(`<h4>Hour ${h + 1} · ${day} ${clock}</h4><p><span>Opens this hour</span><b>${NF.format(s.opensH[h])}</b></p><p><span>Open rate so far</span><b>${pct(cum[h])}</b></p><p><span>Avg of last 10</span><b>${pct(avg[h])}</b></p>`, e.clientX, e.clientY);
});
cSvg.addEventListener('pointerleave', () => { const xh = $('.xh', cSvg); if (xh) xh.style.display = 'none'; $$('.hb', cSvg).forEach(b => b.classList.remove('on')); hideTip(); });

/* ---------------------------------------------------------------- links table + rendered email */
function linkLabel(s, k) {
  if (k === 'logo') return 'Logo';
  if (k === 'hero') return 'Hero image';
  if (k === 'cta') return 'Button: ' + s.cta;
  if (k === 'code') return 'Code ' + s.code;
  if (k === 'more') return s.more;
  if (k === 'prefs') return 'Manage preferences';
  if (k === 'unsub') return 'Unsubscribe';
  if (k[0] === 'p') return s.prods[+k[1]][0];
  return s.arts[+k[1]][0];
}
const ltb = $('.dbm-email__links tbody');
function renderLinks() {
  const s = byId[S.sel], tot = s.links.reduce((a, l) => a + l.n, 0), mx = Math.max(...s.links.map(l => l.n));
  $('.dbm-email__lsub').textContent = `· ${NF.format(tot)} total, ${NF.format(s.clicks)} unique`;
  ltb.innerHTML = s.links.slice().sort((a, b) => b.n - a.n).map(l => `<tr data-l="${l.k}"><td${l.k === 'unsub' ? ' class="warn"' : ''}>${esc(linkLabel(s, l.k))}</td><td class="n">${NF.format(l.n)}</td><td><span class="sh" style="--w:${(l.n / mx).toFixed(4)}"><span></span><b>${pct(l.n / tot)}</b></span></td></tr>`).join('');
}
function renderMail(swap) {
  const s = byId[S.sel], tot = s.links.reduce((a, l) => a + l.n, 0), mx = Math.max(...s.links.map(l => l.n));
  const L = Object.fromEntries(s.links.map(l => [l.k, l.n]));
  let i = 0;
  const lk = (k, cls, inner, tag = 'span') => `<${tag} class="lk ${cls}" data-l="${k}" tabindex="0" role="link" aria-label="${esc(linkLabel(s, k))}: ${NF.format(L[k])} clicks, ${pct(L[k] / tot)}" data-pct="${pct(L[k] / tot)}" style="--heat:${(L[k] / mx).toFixed(3)};--i:${i++}">${inner}</${tag}>`;
  const hero = k => lk(k, 'hero', `<svg viewBox="0 0 96 96" aria-hidden="true">${s.ic}</svg><span class="tag">${esc(s.tag)}</span>`);
  const prod = (p, j) => lk('p' + j, 'prod', `<i style="--pc:oklch(0.62 0.12 ${p[2]})"></i><b>${esc(p[0])}</b><span>${esc(p[1])}</span>`);
  let body = `<div class="top">${lk('logo', 'logo', 'KESTREL &amp; RYE')}<span class="pre">${esc(s.pre)}</span></div>`;
  const hg = `--g1:oklch(0.62 0.13 ${s.g[0]});--g2:oklch(0.42 0.1 ${s.g[1]})`;
  if (s.ty === 'promo') body += `<div style="padding-top:2px">${lk('code', 'code', `Use code at checkout<b>${esc(s.code)}</b>`)}</div>`;
  if (s.ty !== 'lifecycle') body += `<div style="${hg}">${hero('hero')}</div>`;
  body += `<h4>${esc(s.h)}</h4><p>${esc(s.body)}</p>`;
  if (s.ty === 'newsletter') body += s.arts.map((a, j) => lk('a' + j, 'art', `<i style="--pc:oklch(0.62 0.1 ${a[2]})"></i><span><b>${esc(a[0])}</b>${esc(a[1])}</span>`)).join('');
  else {
    body += `<div style="text-align:center">${lk('cta', 'cta', esc(s.cta))}</div>`;
    body += `<div class="grid"${s.prods.length === 1 ? ' style="grid-template-columns:minmax(0,1fr) 2fr"' : ''}>${s.prods.map(prod).join('')}${s.note ? `<p style="margin:0;align-self:center;font-size:11px">${esc(s.note)}</p>` : ''}</div>`;
  }
  if (s.more) body += lk('more', 'more', esc(s.more) + ' →');
  body += `<div class="foot">Kestrel &amp; Rye Roasters · 14 Wharf Lane, Portland<br>${lk('prefs', '', 'Manage preferences')} · ${lk('unsub', '', 'Unsubscribe')}</div>`;
  const mail = $('.dbm-email__mail');
  mail.innerHTML = body;
  mail.classList.remove('is-swap');
  if (swap && !RM) { void mail.offsetWidth; mail.classList.add('is-swap'); }
}
const mailBox = $('.dbm-email__mail');
function hot(k) {
  $$('.lk', mailBox).forEach(e => e.classList.toggle('is-hot', e.dataset.l === k));
  $$('tr', ltb).forEach(r => r.classList.toggle('is-hot', r.dataset.l === k));
}
mailBox.addEventListener('pointerover', e => { const l = e.target.closest('.lk'); hot(l ? l.dataset.l : null); });
mailBox.addEventListener('pointerleave', () => hot(null));
mailBox.addEventListener('focusin', e => { const l = e.target.closest('.lk'); if (l) hot(l.dataset.l); });
mailBox.addEventListener('focusout', () => hot(null));
ltb.addEventListener('pointerover', e => {
  const r = e.target.closest('tr'); if (!r) return; hot(r.dataset.l);
  const el = $(`.lk[data-l="${r.dataset.l}"]`, mailBox), sc = $('.dbm-email__prevp');
  if (el && sc.scrollHeight > sc.clientHeight) { const er = el.getBoundingClientRect(), sr = sc.getBoundingClientRect(); if (er.top < sr.top + 40 || er.bottom > sr.bottom) sc.scrollTo({ top: sc.scrollTop + er.top - sr.top - sr.height / 2, behavior: RM ? 'auto' : 'smooth' }); }
});
ltb.addEventListener('pointerleave', () => hot(null));

/* ---------------------------------------------------------------- trends: three small multiples with one crosshair */
const tSvg = $('.dbm-email__tplot svg');
let TR = null;
const median = a => { const b = a.slice().sort((x, y) => x - y), n = b.length; return n % 2 ? b[(n - 1) / 2] : (b[n / 2 - 1] + b[n / 2]) / 2; };
function renderTrends(intro) {
  const box = tSvg.parentElement, W = box.clientWidth, H = box.clientHeight; if (!W || !H) return;
  const vs = SENDS.filter(s => S.types.has(s.ty));
  const rows = [['Open rate', openRate, v => pct(v)], ['Click rate', ctr, v => pct(v, 2)], ['Revenue per 1k delivered', rev1k, v => '$' + Math.round(v)]];
  const m = { l: 52, r: 16, t: 6, b: 22 }, gap = 14, rh = (H - m.t - m.b - gap * 2) / 3;
  const t0 = Date.UTC(2026, 7, 16), t1 = Date.UTC(2026, 9, 2), X = t => m.l + (t - t0) / (t1 - t0) * (W - m.l - m.r);
  let g = '';
  [Date.UTC(2026, 7, 17), Date.UTC(2026, 7, 31), Date.UTC(2026, 8, 14), Date.UTC(2026, 8, 28)].forEach(t => g += `<text x="${X(t)}" y="${H - 6}" text-anchor="middle">${new Date(t).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' })}</text>`);
  const all = SENDS;
  rows.forEach(([name, f, fm], ri) => {
    const y0 = m.t + ri * (rh + gap), vals = all.map(f), mx = Math.max(...vals) * 1.12, mn = Math.min(...vals) * .8;
    const Y = v => y0 + rh - (v - mn) / (mx - mn) * rh;
    g += `<rect class="band" x="${m.l}" y="${y0}" width="${W - m.l - m.r}" height="${rh}" rx="6"/><text class="rowt" x="${m.l + 8}" y="${y0 + 15}">${name}</text>`;
    [mn + (mx - mn) * .25, mn + (mx - mn) * .75].forEach(v => g += `<text x="${m.l - 6}" y="${Y(v) + 3}" text-anchor="end">${fm(v)}</text>`);
    const md = median(vs.map(f));
    if (vs.length) g += `<line class="med" x1="${m.l}" x2="${W - m.r}" y1="${Y(md)}" y2="${Y(md)}"/>`;
    vs.forEach((s, i) => g += `<line class="stem" x1="${X(s.t0)}" x2="${X(s.t0)}" y1="${y0 + rh}" y2="${Y(f(s))}"/><circle class="dot${s.id === S.sel ? ' is-sel' : ''}" data-id="${s.id}" style="--c:var(--dbm-email-t-${s.ty});--i:${i}" cx="${X(s.t0).toFixed(1)}" cy="${Y(f(s)).toFixed(1)}" r="5"/>`);
  });
  g += `<line class="xh" y1="${m.t}" y2="${H - m.b}" style="display:none;stroke:var(--dbm-email-ink);opacity:.3"/>`;
  tSvg.setAttribute('viewBox', `0 0 ${W} ${H}`); tSvg.innerHTML = g;
  TR = { vs, X };
  tSvg.classList.remove('is-intro');
  if (intro && !RM) { void tSvg.getBoundingClientRect(); tSvg.classList.add('is-intro'); }
  // type summary cards
  $('.dbm-email__typegrid').innerHTML = Object.keys(TYPES).filter(t => S.types.has(t)).map(t => {
    const xs = SENDS.filter(s => s.ty === t), f = g2 => xs.reduce((a, s) => a + g2(s), 0) / xs.length, revTot = xs.reduce((a, s) => a + s.revenue, 0);
    return `<div class="ty" style="--c:var(--dbm-email-t-${t})"><h4><span>${TYPES[t]}</span><small>${xs.length} sends · ${money(revTot)}</small></h4><dl><div><dt>Open</dt><dd>${pct(f(openRate))}</dd></div><div><dt>Click</dt><dd>${pct(f(ctr), 2)}</dd></div><div><dt>Per 1k</dt><dd>$${Math.round(f(rev1k))}</dd></div></dl></div>`;
  }).join('');
}
tSvg.addEventListener('pointermove', e => {
  if (!TR || !TR.vs.length) return;
  const r = tSvg.getBoundingClientRect(), W = tSvg.viewBox.baseVal.width, px = (e.clientX - r.left) * W / r.width;
  const s = TR.vs.reduce((b, x) => Math.abs(TR.X(x.t0) - px) < Math.abs(TR.X(b.t0) - px) ? x : b);
  if (Math.abs(TR.X(s.t0) - px) > 30) { hideTip(); $('.xh', tSvg).style.display = 'none'; $$('.dot', tSvg).forEach(d => d.classList.remove('on')); return; }
  const xh = $('.xh', tSvg); xh.style.display = ''; xh.setAttribute('x1', TR.X(s.t0)); xh.setAttribute('x2', TR.X(s.t0));
  $$('.dot', tSvg).forEach(d => d.classList.toggle('on', d.dataset.id === s.id));
  showTip(`<h4>${esc(s.sj)}</h4><p><span>${TYPES[s.ty]} · ${dayFmt(s.t0)}</span></p><p><span>Open rate</span><b>${pct(openRate(s))}</b></p><p><span>Click rate</span><b>${pct(ctr(s), 2)}</b></p><p><span>Revenue / 1k</span><b>$${rev1k(s).toFixed(2)}</b></p>`, e.clientX, e.clientY);
  tSvg.dataset.hover = s.id;
});
tSvg.addEventListener('pointerleave', () => { hideTip(); const xh = $('.xh', tSvg); if (xh) xh.style.display = 'none'; $$('.dot', tSvg).forEach(d => d.classList.remove('on')); delete tSvg.dataset.hover; });
tSvg.addEventListener('click', () => { const id = tSvg.dataset.hover; if (!id) return; S.sel = id; renderList(); renderSend(true); setView('report'); });

$('.dbm-email__toggle input').addEventListener('change', e => $('.dbm-email__mail').setAttribute('aria-description', e.target.checked ? 'Click shares shown on each link' : ''));

/* ---------------------------------------------------------------- mount */
renderList(true);
renderSend(true);
let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; if (S.view === 'report') drawCurve(false); else renderTrends(false); });
});
ro.observe(cSvg.parentElement); ro.observe(tSvg.parentElement);

css:
@property --dbm-social-sweep {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
.dbm-social {
  /* re-theme with these three */
  --dbm-social-bg: oklch(0.984 0.01 350);
  --dbm-social-ink: oklch(0.22 0.02 15);
  --dbm-social-accent: oklch(0.6 0.22 2);
  /* derived */
  --dbm-social-card: color-mix(in oklch, var(--dbm-social-bg), white 70%);
  --dbm-social-side: color-mix(in oklch, var(--dbm-social-bg), var(--dbm-social-accent) 4%);
  --dbm-social-line: color-mix(in oklch, var(--dbm-social-ink) 11%, transparent);
  --dbm-social-hair: color-mix(in oklch, var(--dbm-social-ink) 6%, transparent);
  --dbm-social-mute: color-mix(in oklch, var(--dbm-social-ink) 60%, var(--dbm-social-bg));
  --dbm-social-faint: color-mix(in oklch, var(--dbm-social-ink) 40%, var(--dbm-social-bg));
  --dbm-social-up: oklch(0.55 0.14 150);
  --dbm-social-f-video: var(--dbm-social-accent);
  --dbm-social-f-carousel: oklch(0.72 0.16 55);
  --dbm-social-f-photo: oklch(0.62 0.11 192);
  --dbm-social-f-story: oklch(0.7 0.15 125);
  --dbm-social-f-live: oklch(0.5 0.16 262);
  --dbm-social-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-social-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-social-out: cubic-bezier(.19, 1, .22, 1);
  --dbm-social-spring: linear(0, .04 1.8%, .17 4.5%, .42 8.5%, .72 13.5%, .92 19%, 1.04 25%, 1.07 30%, 1.05 36%, 1.01 46%, .995 60%, 1);
  width: 100%;
  height: var(--dbm-social-h, 680px);
  container-type: inline-size;
  container-name: dbm-social;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 20px;
  background: var(--dbm-social-bg);
  color: var(--dbm-social-ink);
  font: 13px/1.45 var(--dbm-social-sans);
  accent-color: var(--dbm-social-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dbm-social-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2.5px solid var(--dbm-social-accent); outline-offset: 2px; border-radius: 8px; }
}
.dbm-social__app {
  height: 100%; display: grid;
  grid-template-columns: 196px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "side head" "side kpi" "side main";
}

/* ------------------------------------------------------------ side */
