.dbm-social__range, .dbm-social__xm {
  display: inline-flex; gap: 3px; padding: 3px; border-radius: 999px; background: var(--dbm-social-card); box-shadow: inset 0 0 0 1px var(--dbm-social-line);
  & button { height: 28px; padding: 0 13px; border-radius: 999px; font-size: 12px; font-weight: 650; color: var(--dbm-social-mute); white-space: nowrap; transition: background-color .25s, color .25s; }
