.dbm-social__curve { grid-column: 1 / -1; height: 44px; & svg { width: 100%; height: 100%; display: block; overflow: visible; } & path.a { fill: color-mix(in oklch, var(--c) 18%, transparent); } & path.l { fill: none; stroke: var(--c); stroke-width: 1.8; } & text { font: 500 9.5px var(--dbm-social-mono); fill: var(--dbm-social-faint); } }

/* ------------------------------------------------------------ heatmap */
.dbm-social__heatp { grid-area: heat; display: flex; flex-direction: column; }
.dbm-social__heat {
  flex: 1; display: grid; grid-template-columns: 30px repeat(8, minmax(0, 1fr)); grid-auto-rows: minmax(14px, 1fr); gap: 3px; padding: 8px 14px 12px; min-height: 160px;
