}
function renderPost(swap) {
  if (!S.sel || !byId[S.sel]) { const vs = visible(); S.sel = vs.length ? vs.reduce((b, p) => p.eng > b.eng ? p : b).id : null; }
  $$('.dbm-social__postp').forEach(el => {
    el.innerHTML = S.sel ? postCard(byId[S.sel]) : '<p class="dbm-social__hint">No posts in range.</p>';
    el.classList.remove('is-swap'); if (swap && !RM) { void el.offsetWidth; el.classList.add('is-swap'); }
  });
}
function selectPost(id) {
  S.sel = id; markDots(); renderPost(true);
  $$('.dbm-social__table tbody tr').forEach(tr => tr.setAttribute('aria-selected', tr.dataset.id === id));
}

/* ---------------------------------------------------------------- heatmap */
const heat = $('.dbm-social__heat');
function renderHeat() {
  const vs = visible(), cells = {};
  vs.forEach(p => { const k = slotOf(p); (cells[k] = cells[k] || []).push(p); });
  const avgs = Object.values(cells).map(xs => xs.reduce((a, p) => a + p.eng, 0) / xs.reduce((a, p) => a + p.reach, 0));
  const lo = Math.min(...avgs), hi = Math.max(...avgs);
  let html = '<span class="hl"></span>' + ['00', '03', '06', '09', '12', '15', '18', '21'].map(h => `<span class="hl hc">${h}</span>`).join('');
  let i = 0;
  WD.forEach((w, wd) => {
    html += `<span class="hl">${w}</span>`;
    for (let s = 0; s < 8; s++) {
      const xs = cells[wd + '-' + s], key = wd + '-' + s;
      if (!xs) { html += `<button class="none" disabled aria-label="${w} ${s * 3}:00 to ${s * 3 + 3}:00, no posts" style="--i:${i++}"></button>`; continue; }
      const er = xs.reduce((a, p) => a + p.eng, 0) / xs.reduce((a, p) => a + p.reach, 0);
      html += `<button data-k="${key}" data-er="${er}" data-n="${xs.length}" aria-pressed="${S.slot === key}" aria-label="${w} ${s * 3}:00 to ${s * 3 + 3}:00, ${pct(er)} across ${xs.length} posts" style="--v:${hi > lo ? ((er - lo) / (hi - lo)).toFixed(3) : .5};--i:${i++}"></button>`;
    }
  });
  heat.innerHTML = html;
  const best = Object.entries(cells).filter(([, xs]) => xs.length >= 2).map(([k, xs]) => [k, xs.reduce((a, p) => a + p.eng, 0) / xs.reduce((a, p) => a + p.reach, 0), xs.length]).sort((a, b) => b[1] - a[1])[0];
  $('.dbm-social__best').innerHTML = best ? `Best slot: <b>${WD[+best[0].split('-')[0]]} ${+best[0].split('-')[1] * 3}:00 to ${+best[0].split('-')[1] * 3 + 3}:00</b>, ${pct(best[1])} across ${best[2]} posts. Click a cell to spotlight its posts.` : 'Not enough posts for a pattern yet.';
  $('.dbm-social__clear').hidden = !S.slot;
}
heat.addEventListener('click', e => {
  const b = e.target.closest('button[data-k]'); if (!b) return;
  S.slot = S.slot === b.dataset.k ? null : b.dataset.k;
  $$('button[data-k]', heat).forEach(x => x.setAttribute('aria-pressed', x.dataset.k === S.slot));
  $('.dbm-social__clear').hidden = !S.slot; markDots();
});
heat.addEventListener('pointermove', e => { const b = e.target.closest('button[data-k]'); if (!b) { hideTip(); return; } const [w, s] = b.dataset.k.split('-').map(Number); showTip(`<h4>${WD[w]}, ${s * 3}:00 to ${s * 3 + 3}:00</h4><p><span>Engagement rate</span><b>${pct(+b.dataset.er)}</b></p><p><span>Posts</span><b>${b.dataset.n}</b></p>`, e.clientX, e.clientY); });
heat.addEventListener('pointerleave', hideTip);
$('.dbm-social__clear').addEventListener('click', () => { S.slot = null; $$('button[data-k]', heat).forEach(x => x.setAttribute('aria-pressed', false)); $('.dbm-social__clear').hidden = true; markDots(); });

/* ---------------------------------------------------------------- posts table */
const tbody = $('.dbm-social__table tbody');
function renderTable() {
  const key = { cap: p => p.caption, t: p => p.t, reach: p => p.reach, er: p => p.er, saves: p => p.saves, follows: p => p.follows }[S.sort];
  const vs = visible().sort((a, b) => { const x = key(a), y = key(b); return (typeof x === 'string' ? x.localeCompare(y) : x - y) * S.dir; });
  $$('.dbm-social__table th').forEach(th => th.setAttribute('aria-sort', th.dataset.k === S.sort ? (S.dir > 0 ? 'ascending' : 'descending') : 'none'));
  tbody.innerHTML = vs.map(p => `<tr data-id="${p.id}" aria-selected="${p.id === S.sel}" tabindex="-1"><td><div class="pc"><i style="--c:var(--dbm-social-f-${p.f})"></i><div><span>${esc(p.caption)}</span><small>${FMT[p.f].n}</small></div></div></td><td class="n">${fDay(p.d)}</td><td class="n">${NF.format(p.reach)}</td><td class="n">${pct(p.er)}</td><td class="n">${NF.format(p.saves)}</td><td class="n">+${NF.format(p.follows)}</td></tr>`).join('');
}
$('.dbm-social__table thead').addEventListener('click', e => { const th = e.target.closest('th'); if (!th) return; if (S.sort === th.dataset.k) S.dir *= -1; else { S.sort = th.dataset.k; S.dir = th.dataset.k === 'cap' ? 1 : -1; } renderTable(); });
tbody.addEventListener('click', e => { const tr = e.target.closest('tr'); if (tr) selectPost(tr.dataset.id); });

/* ---------------------------------------------------------------- audience */
const fSvg = $('.dbm-social__fol svg');
let FL = null;
function renderAudience(intro) {
  const box = fSvg.parentElement, W = box.clientWidth, H = box.clientHeight; if (!W || !H) return;
  const a = NDAYS - S.days, days = FOL.slice(a - 1), m = { l: 52, r: 14, t: 12, b: 34 };
  const lo = Math.min(...days.map(d => d.f)), hi = Math.max(...days.map(d => d.f)), pad = (hi - lo) * .12 || 10;
  const X = d => m.l + (d - (a - 1)) / S.days * (W - m.l - m.r), Y = v => H - m.b - (v - (lo - pad)) / (hi - lo + pad * 2) * (H - m.t - m.b);
  let g = '';
  for (let k = 0; k <= 4; k++) { const v = lo - pad + (hi - lo + pad * 2) * k / 4; g += `<line class="gl" x1="${m.l}" x2="${W - m.r}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${m.l - 6}" y="${Y(v) + 3}" text-anchor="end">${kf(v)}</text>`; }
  days.forEach(d => { if (dayDate(d.d).getUTCDate() === 1 || (S.days <= 30 && wdOf(d.d) === 0)) g += `<text x="${X(d.d)}" y="${H - m.b + 26}" text-anchor="middle">${fDay(d.d)}</text>`; });
  const line = days.map((d, i) => (i ? 'L' : 'M') + X(d.d).toFixed(1) + ' ' + Y(d.f).toFixed(1)).join('');
  g += `<path class="ar" d="${line}L${X(NDAYS - 1)} ${H - m.b}L${X(a - 1)} ${H - m.b}Z"/><path class="ln" d="${line}"/>`;
  visible().forEach(p => g += `<line class="tk" style="--c:var(--dbm-social-f-${p.f})" x1="${X(p.d + p.h / 24)}" x2="${X(p.d + p.h / 24)}" y1="${H - m.b + 4}" y2="${H - m.b + 4 + Math.min(12, 3 + p.follows / 6)}"/>`);
  g += `<line class="xh" y1="${m.t}" y2="${H - m.b}" style="display:none"/><circle class="xd" r="4.5" style="display:none"/><rect class="hit" x="${m.l}" y="${m.t}" width="${W - m.l - m.r}" height="${H - m.t}"/>`;
  fSvg.setAttribute('viewBox', `0 0 ${W} ${H}`); fSvg.innerHTML = g;
  FL = { X, Y, a, m, W };
  fSvg.classList.remove('is-intro'); if (intro && !RM) { void fSvg.getBoundingClientRect(); fSvg.classList.add('is-intro'); }
  const net = FOL[NDAYS - 1].f - FOL[a - 1].f;
  $('.dbm-social__folsub').textContent = `· ${NF.format(FOL[NDAYS - 1].f)} now, +${NF.format(net)} in ${S.days} days. Ticks are posts, taller for more follows.`;
  // follows by format in range
  const by = FK.map(k => ({ k, n: POSTS.filter(p => p.f === k && inRange(p)).reduce((s, p) => s + p.follows, 0) }));
  const organic = days.slice(1).reduce((s, d) => s + d.net - d.fromPosts, 0), mx = Math.max(...by.map(b => b.n));
  $('.dbm-social__src').innerHTML = by.sort((x, y) => y.n - x.n).map(b => `<li style="--c:var(--dbm-social-f-${b.k})"><span>${FMT[b.k].n}</span><span class="tr"><i style="--w:${(b.n / mx).toFixed(3)}"></i></span><b>+${NF.format(b.n)}</b></li>`).join('') +
    `<li class="tot"><span>Organic, net of unfollows</span><span></span><b>${organic >= 0 ? '+' : '−'}${NF.format(Math.abs(organic))}</b></li><li><span><b>Net change</b></span><span></span><b>+${NF.format(net)}</b></li>`;
}
fSvg.addEventListener('pointermove', e => {
  if (!FL) return;
  const r = fSvg.getBoundingClientRect(), px = (e.clientX - r.left) * FL.W / r.width;
  const d = Math.round(FL.a - 1 + (px - FL.m.l) / (FL.W - FL.m.l - FL.m.r) * S.days); if (d < FL.a - 1 || d > NDAYS - 1) return;
  const day = FOL[d], xh = $('.xh', fSvg), xd = $('.xd', fSvg);
  xh.style.display = xd.style.display = ''; xh.setAttribute('x1', FL.X(d)); xh.setAttribute('x2', FL.X(d)); xd.setAttribute('cx', FL.X(d)); xd.setAttribute('cy', FL.Y(day.f));
  const ps = POSTS.filter(p => p.d === d && S.fmts.has(p.f));
  showTip(`<h4>${WD[wdOf(d)]} ${fDay(d)}</h4><p><span>Followers</span><b>${NF.format(day.f)}</b></p><p><span>Net that day</span><b>${day.net >= 0 ? '+' : '−'}${Math.abs(day.net)}</b></p>${ps.map(p => `<p><span>${FMT[p.f].n}</span><b>+${p.follows}</b></p>`).join('')}`, e.clientX, e.clientY);
});
fSvg.addEventListener('pointerleave', () => { const xh = $('.xh', fSvg), xd = $('.xd', fSvg); if (xh) xh.style.display = xd.style.display = 'none'; hideTip(); });

/* ---------------------------------------------------------------- orchestration */
const drawn = {};
function renderView(entering) {
  if (S.view === 'overview') { layoutSwarm(!drawn.o); renderHeat(); renderPost(false); drawn.o = 1; }
  else if (S.view === 'posts') { renderTable(); renderPost(false); }
  else { renderAudience(!drawn.a); drawn.a = 1; }
}
function renderAll() {
  if (S.sel && !visible().some(p => p.id === S.sel)) S.sel = null;
  renderFmtCounts(); renderKpis(); renderView(false);
}
renderFmtCounts(); renderKpis(); renderView(true);

let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; if (S.view === 'overview') layoutSwarm(false); else if (S.view === 'audience') renderAudience(false); });
});
ro.observe(sSvg.parentElement); ro.observe(fSvg.parentElement);
// the logo ring is the only perpetual animation: pause it when the component is off screen
const logo = $('.dbm-social__logo');
const io = new IntersectionObserver(es => { if (!root.isConnected) { io.disconnect(); return; } logo.style.animationPlayState = es[0].isIntersecting ? 'running' : 'paused'; });
io.observe(root);

