.dbm-seo {
  /* re-theme with these four */
  --dbm-seo-paper: oklch(0.972 0.013 135);
  --dbm-seo-ink: oklch(0.25 0.045 160);
  --dbm-seo-up: oklch(0.55 0.13 152);
  --dbm-seo-down: oklch(0.56 0.16 32);
  /* derived */
  --dbm-seo-card: color-mix(in oklch, var(--dbm-seo-paper), white 72%);
  --dbm-seo-rail: color-mix(in oklch, var(--dbm-seo-ink), var(--dbm-seo-paper) 8%);
  --dbm-seo-line: color-mix(in oklch, var(--dbm-seo-ink) 13%, transparent);
  --dbm-seo-hair: color-mix(in oklch, var(--dbm-seo-ink) 6.5%, transparent);
  --dbm-seo-mute: color-mix(in oklch, var(--dbm-seo-ink) 62%, var(--dbm-seo-paper));
  --dbm-seo-faint: color-mix(in oklch, var(--dbm-seo-ink) 42%, var(--dbm-seo-paper));
  --dbm-seo-mark: oklch(0.88 0.13 98);
  --dbm-seo-k-veg: oklch(0.62 0.1 122);
  --dbm-seo-k-soil: oklch(0.52 0.07 60);
  --dbm-seo-k-lawn: oklch(0.6 0.08 190);
  --dbm-seo-k-water: oklch(0.56 0.09 245);
  --dbm-seo-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-seo-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-seo-out: cubic-bezier(.23, 1, .32, 1);
  --dbm-seo-spring: linear(0, .05 2%, .2 5%, .48 9.5%, .78 15%, .96 21%, 1.04 27%, 1.05 31%, 1.03 38%, 1.005 50%, 1);
  width: 100%;
  height: var(--dbm-seo-h, 680px);
  container-type: inline-size;
  container-name: dbm-seo;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 14px;
  background: var(--dbm-seo-paper);
  color: var(--dbm-seo-ink);
  font: 13px/1.45 var(--dbm-seo-sans);
  accent-color: var(--dbm-seo-up);
  color-scheme: light;
  interpolate-size: allow-keywords;
  box-shadow: inset 0 0 0 1px var(--dbm-seo-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-seo-up); outline-offset: 2px; border-radius: 5px; }
}
.dbm-seo__app {
  height: 100%; display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "rail head" "rail main";
}

/* ------------------------------------------------------------ rail */
.dbm-seo__rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 14px 0; background: var(--dbm-seo-rail); color: var(--dbm-seo-paper); }
.dbm-seo__mark { width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; background: var(--dbm-seo-mark); & svg { width: 20px; height: 20px; fill: none; stroke: var(--dbm-seo-ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; } }
.dbm-seo__tabs {
  display: grid; gap: 4px;
  & button { width: 50px; padding: 7px 0 5px; border-radius: 10px; display: grid; justify-items: center; gap: 3px; font-size: 9.5px; font-weight: 650; letter-spacing: .02em; color: color-mix(in oklch, var(--dbm-seo-paper) 55%, transparent); transition: background-color .2s, color .2s; }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { color: var(--dbm-seo-paper); }
  & button[aria-selected="true"] { color: var(--dbm-seo-ink); background: var(--dbm-seo-mark); }
}

/* ------------------------------------------------------------ head */
.dbm-seo__head {
  grid-area: head; display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "t s" "f f"; gap: 10px 24px; align-items: end;
  padding: 16px 20px 12px; border-bottom: 1px solid var(--dbm-seo-line);
}
.dbm-seo__ht { grid-area: t; }
.dbm-seo__eyebrow { font: 600 10.5px var(--dbm-seo-mono); letter-spacing: .05em; color: var(--dbm-seo-faint); }
.dbm-seo__ht h2 { font-size: clamp(20px, 2.5cqi, 27px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; margin-top: 3px; }
.dbm-seo__stats {
  grid-area: s; display: grid; grid-template-columns: repeat(4, minmax(0, auto)); justify-content: end; gap: 0 22px;
  & div { display: grid; }
  & dt { font: 600 9.5px var(--dbm-seo-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbm-seo-faint); white-space: nowrap; }
  & dd { font-size: clamp(16px, 1.9cqi, 21px); font-weight: 760; letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { font: 650 11px var(--dbm-seo-sans); letter-spacing: 0; margin-left: 4px; }
  & .up { color: var(--dbm-seo-up); }
  & .dn { color: var(--dbm-seo-down); }
}
.dbm-seo__filters { grid-area: f; display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }
.dbm-seo__clusters {
  display: flex; gap: 5px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dbm-seo-mute); background: var(--dbm-seo-card); box-shadow: inset 0 0 0 1px var(--dbm-seo-line); transition: box-shadow .15s, color .15s, background-color .15s; }
  & button i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & button[aria-pressed="true"] { color: var(--dbm-seo-ink); box-shadow: inset 0 0 0 1.5px var(--c); background: color-mix(in oklch, var(--c) 10%, var(--dbm-seo-card)); }
  & label { display: inline-flex; align-items: center; gap: 6px; padding: 0 6px 0 10px; font-size: 12px; font-weight: 600; color: var(--dbm-seo-mute); cursor: pointer; }
  & label input { margin: 0; }
}
.dbm-seo__cmp {
  display: inline-flex; padding: 2px; border-radius: 7px; background: var(--dbm-seo-hair);
  & button { height: 24px; padding: 0 10px; border-radius: 5px; font: 650 11px var(--dbm-seo-mono); color: var(--dbm-seo-mute); }
  & button[aria-checked="true"] { background: var(--dbm-seo-card); color: var(--dbm-seo-ink); box-shadow: 0 1px 2px var(--dbm-seo-line); }
}

/* ------------------------------------------------------------ views */
.dbm-seo__main { grid-area: main; min-height: 0; padding: 12px 20px 16px; }
.dbm-seo__view { height: 100%; min-height: 0; display: grid; gap: 12px; }
.dbm-seo__view[hidden] { display: none; }
.dbm-seo__view:not([hidden]) { animation: dbm-seo-in .45s var(--dbm-seo-out) both; }
@keyframes dbm-seo-in { from { opacity: 0; translate: 0 6px; } }
.dbm-seo__v-rank { grid-template-columns: 310px minmax(0, 1fr); grid-template-rows: 172px minmax(0, 1fr); grid-template-areas: "ladder vis" "ladder table"; }
.dbm-seo__v-movers { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.dbm-seo__v-pages { grid-template-columns: minmax(0, 1fr); }
.dbm-seo__panel {
  min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbm-seo-line) transparent;
  border-radius: 12px; background: var(--dbm-seo-card); box-shadow: 0 0 0 1px var(--dbm-seo-line);
}
.dbm-seo__ph {
  padding: 11px 14px 4px;
  & h3 { font-size: 13px; font-weight: 700; letter-spacing: -.01em; }
  & h3 small { font-weight: 500; color: var(--dbm-seo-faint); font-size: 11px; margin-left: 3px; }
  & p { font-size: 11.5px; color: var(--dbm-seo-mute); text-wrap: pretty; margin-top: 1px; }
}

/* ------------------------------------------------------------ ladder */
.dbm-seo__ladderp { grid-area: ladder; display: flex; flex-direction: column; overflow: hidden; }
.dbm-seo__scrub { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; align-items: center; padding: 10px 12px 8px; border-bottom: 1px solid var(--dbm-seo-hair); }
.dbm-seo__play {
  width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--dbm-seo-ink); color: var(--dbm-seo-paper);
  transition: scale .2s var(--dbm-seo-out);
  &:active { scale: .92; }
  & svg { width: 15px; height: 15px; fill: currentColor; }
  & .pa { display: none; }
  &[aria-pressed="true"] .pa { display: block; }
  &[aria-pressed="true"] .pl { display: none; }
}
.dbm-seo__sl { display: grid; gap: 1px; & input { width: 100%; margin: 0; } }
.dbm-seo__date { font: 700 12px var(--dbm-seo-mono); letter-spacing: .02em; display: flex; justify-content: space-between; & small { font-weight: 500; color: var(--dbm-seo-faint); } }
.dbm-seo__ladder { flex: 1; min-height: 0; display: grid; grid-template-rows: repeat(20, minmax(0, 1fr)); padding: 4px 10px 2px 6px; }
.dbm-seo__rung {
  position: relative; display: grid; grid-template-columns: 24px minmax(0, 1fr); align-items: center; gap: 6px; min-height: 0;
  border-bottom: 1px solid var(--dbm-seo-hair);
  & > b { font: 650 10px var(--dbm-seo-mono); color: var(--dbm-seo-faint); text-align: right; font-variant-numeric: tabular-nums; }
  &:nth-child(-n+3) > b { color: var(--dbm-seo-ink); }
  &:nth-child(10) { border-bottom: 1.5px dashed var(--dbm-seo-mute); }
  &:nth-child(10)::after { content: "page 2 ↓"; position: absolute; right: 0; bottom: -7px; padding: 0 4px; background: var(--dbm-seo-card); font: 600 8.5px var(--dbm-seo-mono); letter-spacing: .06em; color: var(--dbm-seo-faint); text-transform: uppercase; }
  & .chips { display: flex; gap: 3px; min-width: 0; align-items: center; height: 100%; padding: 2px 0; }
}
.dbm-seo__chip {
  --st: var(--dbm-seo-faint);
  flex: 0 1 auto; min-width: 34px; display: inline-flex; align-items: center; gap: 4px; height: min(18px, 100%); max-width: 128px; padding: 0 6px 0 4px; border-radius: 4px;
  font-size: 10.5px; font-weight: 600; white-space: nowrap; cursor: default;
  background: color-mix(in oklch, var(--st) 13%, var(--dbm-seo-card)); box-shadow: inset 2px 0 0 var(--c), inset 0 0 0 1px color-mix(in oklch, var(--st) 30%, transparent);
  transition: background-color .3s, box-shadow .3s;
