.dbm-seo__tray {
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 8px; padding: 7px 12px 9px; border-top: 1px solid var(--dbm-seo-line); background: var(--dbm-seo-hair);
  & .dbm-seo__trayl { font: 650 10px var(--dbm-seo-mono); color: var(--dbm-seo-mute); white-space: nowrap; }
