/* ------------------------------------------------------------ visibility chart */
.dbm-seo__visp { grid-area: vis; display: flex; flex-direction: column; }
.dbm-seo__plot { position: relative; flex: 1; min-height: 0; margin: 0 10px 6px; & svg { display: block; width: 100%; height: 100%; overflow: visible; touch-action: none; cursor: ew-resize; } }
.dbm-seo__plot {
