const CL = { veg: 'Vegetables', soil: 'Soil & compost', lawn: 'Lawn', water: 'Watering' };
const EVENTS = [{ d: 54, k: 'core', t: 'Core update', a: 'start', lv: 0 }, { d: 68, k: 'garlic', t: 'Garlic guide refreshed', a: 'end', lv: 1 }, { d: 79, k: 'beds', t: 'Raised-bed guide live', a: 'end', lv: 0 }];
