/* ---------------------------------------------------------------- filters */
const clBox = $('.dbm-seo__clusters');
clBox.innerHTML = Object.entries(CL).map(([k, n]) => `<button aria-pressed="true" data-c="${k}" style="--c:var(--dbm-seo-k-${k})"><i></i>${n}</button>`).join('') + `<label><input type="checkbox" class="dbm-seo__p1"> Page one only</label>`;
