const cmpBox = $('.dbm-seo__cmp');
cmpBox.addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; setCmp(b); });
cmpBox.addEventListener('keydown', e => { if (!/Arrow/.test(e.key)) return; e.preventDefault(); const bs = $$('button', cmpBox); const n = bs.find(b => b.getAttribute('aria-checked') !== 'true'); n.focus(); setCmp(n); });
function setCmp(b) { $$('button', cmpBox).forEach(x => { const on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; }); S.cmp = +b.dataset.c; renderAll(false); }

