/* ---------------------------------------------------------------- header stats */
function renderStats() {
  const L = kws(), d0 = prevDay(), v1 = vis(L, S.day), v0 = vis(L, d0);
  const t1 = L.reduce((a, k) => a + visits(k, S.day), 0), t0 = L.reduce((a, k) => a + visits(k, d0), 0);
  const top3 = d => L.filter(k => k.r[d] <= 3).length, p1 = d => L.filter(k => k.r[d] <= 10).length;
  const dl = (x, unit = '') => `<small class="${x > 0 ? 'up' : x < 0 ? 'dn' : ''}">${x > 0 ? '▲' : x < 0 ? '▼' : '±'}${Math.abs(x)}${unit}</small>`;
  $('.dbm-seo__stats').innerHTML = `
    <div><dt>Visibility</dt><dd>${(v1 * 100).toFixed(1)}%${dl(+((v1 - v0) * 100).toFixed(1), ' pts')}</dd></div>
    <div><dt>Est. visits / mo</dt><dd>${kf(t1)}${dl(Math.round((t1 / t0 - 1) * 100), '%')}</dd></div>
    <div><dt>Top 3</dt><dd>${top3(S.day)}${dl(top3(S.day) - top3(d0))}</dd></div>
    <div><dt>Page one</dt><dd>${p1(S.day)} <span style="font-size:12px;color:var(--dbm-seo-faint);font-weight:500">of ${L.length}</span>${dl(p1(S.day) - p1(d0))}</dd></div>`;
}

/* ---------------------------------------------------------------- the ladder */
const ladder = $('.dbm-seo__ladder'), tray = $('.dbm-seo__trayc');
ladder.innerHTML = Array.from({ length: 20 }, (_, i) => `<li class="dbm-seo__rung"><b>${i + 1}</b><div class="chips"></div></li>`).join('');
const rungs = $$('.chips', ladder);
const chipEl = new Map();
KW.forEach(k => {
  const el = document.createElement('span');
  el.className = 'dbm-seo__chip'; el.dataset.k = k.i; el.tabIndex = -1;
  el.style.setProperty('--c', `var(--dbm-seo-k-${k.cl})`);
  el.innerHTML = `<span>${esc(k.kw)}</span><em></em>`;
  chipEl.set(k.i, el);
});
function placeChips(animate) {
  const L = kws(), ids = new Set(L.map(k => k.i));
  const first = new Map();
  if (animate && !RM) chipEl.forEach((el, i) => { if (el.isConnected) first.set(i, el.getBoundingClientRect()); });
  chipEl.forEach(el => el.getAnimations().forEach(a => a.cancel()));
  rungs.forEach(r => r.replaceChildren()); tray.replaceChildren();
  const beyond = [];
  L.slice().sort((a, b) => a.r[S.day] - b.r[S.day] || b.vol - a.vol).forEach(k => {
    const el = chipEl.get(k.i), r = k.r[S.day], d = delta(k);
    el.classList.toggle('is-up', d > 0); el.classList.toggle('is-dn', d < 0);
    $('em', el).textContent = d > 0 ? '▲' + d : d < 0 ? '▼' + -d : '';
    el.setAttribute('aria-label', `${k.kw}, position ${r}${d ? (d > 0 ? ', up ' + d : ', down ' + -d) : ''}`);
    if (r <= 20) rungs[r - 1].appendChild(el); else beyond.push([k, el]);
  });
  beyond.forEach(([, el]) => tray.appendChild(el));
  $('.dbm-seo__trayl').textContent = `21+ · ${beyond.length}`;
  chipEl.forEach((el, i) => { if (!ids.has(i)) el.remove(); });
  if (!animate || RM) return;
  chipEl.forEach((el, i) => {
    const f = first.get(i); if (!f || !el.isConnected) { if (el.isConnected) el.animate([{ opacity: 0, transform: 'scale(.8)' }, { opacity: 1, transform: 'none' }], { duration: 300, easing: 'ease-out' }); return; }
    const l = el.getBoundingClientRect(), dx = f.left - l.left, dy = f.top - l.top;
    if (Math.abs(dx) + Math.abs(dy) > 1) el.animate([{ transform: `translate(${dx}px,${dy}px)` }, { transform: 'none' }], { duration: S.playing ? 260 : 520, easing: S.playing ? 'cubic-bezier(.3,.7,.4,1)' : 'cubic-bezier(.23,1,.32,1)' });
  });
}
function hot(i) {
  chipEl.forEach((el, j) => el.classList.toggle('is-hot', j === i));
  $$('tr', tbody).forEach(tr => tr.classList.toggle('is-hot', +tr.dataset.k === i));
}
const ladderP = $('.dbm-seo__ladderp');
ladderP.addEventListener('pointerover', e => { const c = e.target.closest('.dbm-seo__chip'); if (c) { hot(+c.dataset.k); } });
ladderP.addEventListener('pointermove', e => { const c = e.target.closest('.dbm-seo__chip'); if (c) showTip(kwTip(KW[+c.dataset.k]), e.clientX, e.clientY); else hideTip(); });
ladderP.addEventListener('pointerleave', () => { hot(-1); hideTip(); });

/* ---------------------------------------------------------------- scrubber + play loop */
const slider = $('.dbm-seo__sl input'), playBtn = $('.dbm-seo__play');
function setDay(d, animate = true) {
  S.day = Math.max(0, Math.min(N - 1, d));
  slider.value = S.day;
  slider.setAttribute('aria-valuetext', fDL(S.day));
  $('.dbm-seo__date').innerHTML = `${fDL(S.day)} <small>${S.day === N - 1 ? 'latest' : (N - 1 - S.day) + ' days ago'}</small>`;
  renderStats(); placeChips(animate); moveCursor();
  if (S.view === 'rank') renderTable(); else renderView(false);
}
slider.addEventListener('input', () => setDay(+slider.value));
let timer = 0, visibleOnScreen = true;
function play(on) {
  S.playing = on; playBtn.setAttribute('aria-pressed', on); playBtn.setAttribute('aria-label', on ? 'Pause rank history' : 'Play rank history');
  clearInterval(timer);
  if (!on) return;
  if (S.day >= N - 1) setDay(0, false);
  timer = setInterval(() => {
    if (!root.isConnected) { clearInterval(timer); return; }
    if (document.hidden || !visibleOnScreen) return;
    if (S.day >= N - 1) { play(false); return; }
    setDay(S.day + 1);
  }, RM ? 400 : 190);
}
playBtn.addEventListener('click', () => play(!S.playing));
const io = new IntersectionObserver(es => { if (!root.isConnected) { io.disconnect(); return; } visibleOnScreen = es[0].isIntersecting; });
io.observe(root);

/* ---------------------------------------------------------------- visibility chart */
const vSvg = $('.dbm-seo__visp svg');
let VC = null;
function drawVis(intro) {
  const box = vSvg.parentElement, W = box.clientWidth, H = box.clientHeight; if (!W || !H) return;
  const L = kws(), series = Array.from({ length: N }, (_, d) => vis(L, d));
  const lo = Math.floor(Math.min(...series) * 50) / 50, hi = Math.ceil(Math.max(...series) * 50) / 50 + .01;
  const m = { l: 36, r: 12, t: 32, b: 18 };
  const X = d => m.l + d / (N - 1) * (W - m.l - m.r), Y = v => H - m.b - (v - lo) / (hi - lo) * (H - m.t - m.b);
  let g = '';
  for (let k = 0; k <= 3; k++) { const v = lo + (hi - lo) * k / 3; g += `<line class="gl" x1="${m.l}" x2="${W - m.r}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${m.l - 5}" y="${Y(v) + 3}" text-anchor="end">${Math.round(v * 100)}%</text>`; }
  [0, 28, 59, 89].forEach(d => g += `<text x="${X(d)}" y="${H - 4}" text-anchor="${d === 0 ? 'start' : d === 89 ? 'end' : 'middle'}">${fD(d)}</text>`);
  const line = series.map((v, d) => (d ? 'L' : 'M') + X(d).toFixed(1) + ' ' + Y(v).toFixed(1)).join('');
  g += `<path class="ar" d="${line}L${X(N - 1)} ${H - m.b}L${X(0)} ${H - m.b}Z"/><path class="ln" d="${line}"/>`;
  EVENTS.forEach(E => { const y = m.t - 20 + E.lv * 12; g += `<line class="ev" x1="${X(E.d)}" x2="${X(E.d)}" y1="${y}" y2="${H - m.b}"/><circle class="evd" cx="${X(E.d)}" cy="${y}" r="3.5"/><text class="evt" x="${X(E.d) + (E.a === 'end' ? -7 : 7)}" y="${y + 3.5}" text-anchor="${E.a}">${E.t}</text>`; });
  g += `<g class="cg"><line class="cur" y1="${m.t}" y2="${H - m.b}"/><circle class="curd" r="5"/><text class="curt" text-anchor="middle"></text></g>`;
  vSvg.setAttribute('viewBox', `0 0 ${W} ${H}`); vSvg.innerHTML = g;
  VC = { X, Y, series, m, W };
  moveCursor();
  vSvg.classList.remove('is-intro'); if (intro && !RM) { void vSvg.getBoundingClientRect(); vSvg.classList.add('is-intro'); }
}
function moveCursor() {
  if (!VC || !vSvg.querySelector('.cg')) return;
  const { X, Y, series, W } = VC, x = X(S.day), y = Y(series[S.day]);
  const ln = $('.cur', vSvg); ln.setAttribute('x1', x); ln.setAttribute('x2', x);
  const c = $('.curd', vSvg); c.setAttribute('cx', x); c.setAttribute('cy', y);
  const t = $('.curt', vSvg); t.setAttribute('x', Math.max(30, Math.min(W - 30, x))); t.setAttribute('y', y - 10); t.textContent = (series[S.day] * 100).toFixed(1) + '%';
}
function dayFromEvent(e) { const r = vSvg.getBoundingClientRect(), px = (e.clientX - r.left) * VC.W / r.width; return Math.round((px - VC.m.l) / (VC.W - VC.m.l - VC.m.r) * (N - 1)); }
vSvg.addEventListener('pointerdown', e => { if (!VC) return; play(false); vSvg.setPointerCapture(e.pointerId); setDay(dayFromEvent(e)); });
vSvg.addEventListener('pointermove', e => {
  if (!VC) return;
  if (vSvg.hasPointerCapture(e.pointerId)) { const d = dayFromEvent(e); if (d !== S.day && d >= 0 && d < N) setDay(d); return; }
  const d = dayFromEvent(e); if (d < 0 || d >= N) return;
  const ev = EVENTS.find(E => Math.abs(E.d - d) <= 1);
  showTip(`<h4>${fDL(d)}</h4><p><span>Visibility</span><b>${(VC.series[d] * 100).toFixed(1)}%</b></p>${ev ? `<p><span>${ev.t}</span></p>` : ''}`, e.clientX, e.clientY);
});
vSvg.addEventListener('pointerleave', hideTip);

/* ---------------------------------------------------------------- table */
const tbody = $('.dbm-seo__table tbody');
function spark(k) {
  const W = 96, H = 24, mx = Math.min(100, Math.max(12, ...k.r) + 2), X = d => d / (N - 1) * W, Y = r => (r - 1) / (mx - 1) * H;
  return `<svg viewBox="0 0 ${W} ${H}" aria-hidden="true"><rect class="p1" x="0" y="0" width="${W}" height="${Y(10.5)}"/><path d="M${k.r.map((r, d) => X(d).toFixed(1) + ' ' + Y(r).toFixed(1)).join('L')}"/><circle cx="${X(S.day)}" cy="${Y(k.r[S.day])}" r="2.6"/></svg>`;
}
function renderTable() {
  const key = { kw: k => k.kw, pos: k => k.r[S.day], d: k => delta(k), vol: k => k.vol, vis: k => visits(k, S.day) }[S.sort];
  const L = kws().filter(k => !S.p1 || k.r[S.day] <= 10).sort((a, b) => { const x = key(a), y = key(b); return (typeof x === 'string' ? x.localeCompare(y) : x - y) * S.dir; });
  $$('.dbm-seo__table th[data-k]').forEach(th => th.setAttribute('aria-sort', th.dataset.k === S.sort ? (S.dir > 0 ? 'ascending' : 'descending') : 'none'));
  tbody.innerHTML = L.map(k => { const d = delta(k); return `<tr data-k="${k.i}"><td><span class="kw" style="--c:var(--dbm-seo-k-${k.cl})"><b>${esc(k.kw)}</b><small>${esc(k.url)}</small></span></td><td class="n pos">${k.r[S.day]}</td><td class="n ${d > 0 ? 'up' : d < 0 ? 'dn' : 'fl'}">${d > 0 ? '▲ ' + d : d < 0 ? '▼ ' + -d : '·'}</td><td class="n">${NF.format(k.vol)}</td><td class="n">${NF.format(Math.round(visits(k, S.day)))}</td><td>${spark(k)}</td></tr>`; }).join('');
}
$('.dbm-seo__table thead').addEventListener('click', e => { const th = e.target.closest('th[data-k]'); if (!th) return; if (S.sort === th.dataset.k) S.dir *= -1; else { S.sort = th.dataset.k; S.dir = th.dataset.k === 'pos' || th.dataset.k === 'kw' ? 1 : -1; } renderTable(); });
tbody.addEventListener('pointerover', e => { const tr = e.target.closest('tr'); if (tr) hot(+tr.dataset.k); });
tbody.addEventListener('pointerleave', () => hot(-1));

/* ---------------------------------------------------------------- movers */
function renderMovers() {
  const L = kws().filter(k => !S.p1 || k.r[S.day] <= 10 || k.r[prevDay()] <= 10).map(k => ({ k, d: delta(k) }));
  const up = L.filter(x => x.d > 0).sort((a, b) => b.d - a.d).slice(0, 9), dn = L.filter(x => x.d < 0).sort((a, b) => a.d - b.d).slice(0, 9);
  $$('.dbm-seo__msub').forEach(s => s.textContent = `· ${fD(prevDay())} to ${fD(S.day)}`);
  const row = ({ k, d }, i) => {
    const a = k.r[prevDay()], b = k.r[S.day], mx = Math.max(a, b, 12), Y = r => 4 + (r - 1) / (mx - 1) * 26;
    return `<li style="--i:${i}"><span class="kw"><b>${esc(k.kw)}</b><small>${NF.format(k.vol)} searches/mo · ${CL[k.cl]}</small></span><svg viewBox="0 0 80 34" aria-label="from ${a} to ${b}"><line x1="14" x2="66" y1="${Y(a)}" y2="${Y(b)}"/><circle cx="14" cy="${Y(a)}" r="3.5"/><circle class="e" cx="66" cy="${Y(b)}" r="3.5"/><text x="8" y="${Y(a) + 3}" text-anchor="end">${a}</text><text x="72" y="${Y(b) + 3}">${b}</text></svg><span class="d">${d > 0 ? '▲' : '▼'}${Math.abs(d)}</span></li>`;
  };
  $('.dbm-seo__up').innerHTML = up.length ? up.map(row).join('') : '<li class="dbm-seo__empty">Nothing climbed in this window.</li>';
  $('.dbm-seo__dn').innerHTML = dn.length ? dn.map(row).join('') : '<li class="dbm-seo__empty">Nothing slipped in this window.</li>';
}

/* ---------------------------------------------------------------- pages */
function renderPages() {
  const by = {};
  kws().forEach(k => (by[k.url] = by[k.url] || []).push(k));
  const rows = Object.entries(by).map(([url, ks]) => ({ url, ks, v: ks.reduce((a, k) => a + visits(k, S.day), 0), best: Math.min(...ks.map(k => k.r[S.day])) })).sort((a, b) => b.v - a.v);
  const mx = Math.max(...rows.map(r => r.v)), tot = rows.reduce((a, r) => a + r.v, 0);
  $('.dbm-seo__psub').textContent = `· ${rows.length} pages, ${NF.format(Math.round(tot))} visits/mo on ${fD(S.day)}`;
  const open = new Set($$('.dbm-seo__pages details[open]').map(d => d.dataset.u));
  $('.dbm-seo__pages').innerHTML = rows.map(r => `<details data-u="${esc(r.url)}"${open.has(r.url) ? ' open' : ''}><summary><span class="u">${esc(r.url)}<small>${r.ks.length} keyword${r.ks.length > 1 ? 's' : ''} · best #${r.best}</small></span><span class="bar"><i style="--w:${(r.v / mx).toFixed(3)}"></i></span><span class="n">${NF.format(Math.round(r.v))}<small>visits/mo</small></span><span class="n">${((r.v / tot) * 100).toFixed(1)}%<small>of total</small></span></summary><ul>${r.ks.sort((a, b) => a.r[S.day] - b.r[S.day]).map(k => `<li><span>${esc(k.kw)}</span><span>#${k.r[S.day]}</span><span>${NF.format(Math.round(visits(k, S.day)))}</span></li>`).join('')}</ul></details>`).join('');
}

/* ---------------------------------------------------------------- orchestration */
function renderView(entering) {
  if (S.view === 'rank') { drawVis(entering && !drawn); renderTable(); drawn = true; }
  else if (S.view === 'movers') renderMovers();
  else renderPages();
}
let drawn = false;
function renderAll(anim) { renderStats(); placeChips(anim); if (S.view === 'rank') { drawVis(false); renderTable(); } else renderView(false); }

setDay(N - 1, false);
drawVis(true); drawn = true;
if (!RM) { ladderP.classList.add('is-intro'); $$('.dbm-seo__chip').forEach((c, i) => c.style.setProperty('--i', i)); setTimeout(() => { if (root.isConnected) ladderP.classList.remove('is-intro'); }, 1600); }
let rz = 0;
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); play(false); return; } cancelAnimationFrame(rz); rz = requestAnimationFrame(() => { if (!root.isConnected) return; if (S.view === 'rank') drawVis(false); }); });
ro.observe(vSvg.parentElement);

css:
@property --dbm-segment-share {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 0%;
}
.dbm-segment {
  /* re-theme with these three */
  --dbm-segment-bg: oklch(0.185 0.014 152);
  --dbm-segment-ink: oklch(0.95 0.012 118);
  --dbm-segment-accent: oklch(0.9 0.19 124);
  /* derived */
  --dbm-segment-low: oklch(from var(--dbm-segment-accent) 0.72 0.13 32);
  --dbm-segment-panel: color-mix(in oklch, var(--dbm-segment-bg), var(--dbm-segment-ink) 4%);
  --dbm-segment-raise: color-mix(in oklch, var(--dbm-segment-bg), var(--dbm-segment-ink) 9%);
  --dbm-segment-deep: color-mix(in oklch, var(--dbm-segment-bg), black 22%);
  --dbm-segment-line: color-mix(in oklch, var(--dbm-segment-ink) 12%, transparent);
  --dbm-segment-hair: color-mix(in oklch, var(--dbm-segment-ink) 6.5%, transparent);
  --dbm-segment-mute: color-mix(in oklch, var(--dbm-segment-ink) 62%, var(--dbm-segment-bg));
  --dbm-segment-faint: color-mix(in oklch, var(--dbm-segment-ink) 40%, var(--dbm-segment-bg));
  --dbm-segment-glow: color-mix(in oklch, var(--dbm-segment-accent) 22%, transparent);
  --dbm-segment-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-segment-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-segment-out: cubic-bezier(.16, 1, .3, 1);
  --dbm-segment-spring: linear(0, .05 2%, .21 5%, .5 9.5%, .8 15%, .97 21%, 1.05 27%, 1.06 31%, 1.03 39%, 1.003 51%, .999 66%, 1);
  width: 100%;
  height: var(--dbm-segment-h, 680px);
  container-type: inline-size;
  container-name: dbm-segment;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dbm-segment-bg);
  color: var(--dbm-segment-ink);
  font: 13px/1.45 var(--dbm-segment-sans);
  accent-color: var(--dbm-segment-accent);
  color-scheme: dark;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button, select, input) { font: inherit; color: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-segment-accent); outline-offset: 2px; border-radius: 6px; }
}
.dbm-segment__app {
  height: 100%; display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head" "side main";
}

/* ------------------------------------------------------------ side */
.dbm-segment__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 18px; padding: 16px 12px; background: var(--dbm-segment-deep); border-right: 1px solid var(--dbm-segment-line); }
.dbm-segment__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & span:last-child { display: grid; line-height: 1.2; }
  & b { font-weight: 760; letter-spacing: -.02em; font-size: 14px; }
  & small { font: 500 10px var(--dbm-segment-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbm-segment-faint); }
}
.dbm-segment__logo { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: var(--dbm-segment-accent); & svg { width: 20px; height: 20px; fill: none; stroke: var(--dbm-segment-bg); stroke-width: 2.2; stroke-linecap: round; } }
.dbm-segment__nav {
  display: grid; gap: 2px;
  & button { display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 9px; font-weight: 600; color: var(--dbm-segment-mute); transition: background-color .2s, color .2s; }
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  & button:hover { color: var(--dbm-segment-ink); background: var(--dbm-segment-hair); }
  & button[aria-selected="true"] { color: var(--dbm-segment-ink); background: var(--dbm-segment-raise); }
  & button[aria-selected="true"] svg { stroke: var(--dbm-segment-accent); }
}
.dbm-segment__lbl { font: 600 10px var(--dbm-segment-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--dbm-segment-faint); }
.dbm-segment__saved { min-height: 0; display: flex; flex-direction: column; gap: 8px; flex: 1; & .dbm-segment__lbl { padding: 0 6px; } }
.dbm-segment__slist {
  overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbm-segment-line) transparent; display: grid; align-content: start; gap: 2px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; padding: 8px 9px; border-radius: 9px; cursor: pointer; transition: background-color .15s; }
  & li:hover { background: var(--dbm-segment-hair); }
  & li[aria-selected="true"] { background: var(--dbm-segment-raise); box-shadow: inset 2px 0 0 var(--dbm-segment-accent); }
  & b { font-size: 12.5px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .n { font: 600 11px var(--dbm-segment-mono); color: var(--dbm-segment-accent); font-variant-numeric: tabular-nums; }
  & small { grid-column: 1 / -1; font-size: 11px; color: var(--dbm-segment-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & li.is-new { animation: dbm-segment-new .9s var(--dbm-segment-out); }
}
@keyframes dbm-segment-new { from { background: var(--dbm-segment-glow); translate: -8px 0; } }

/* ------------------------------------------------------------ head */
.dbm-segment__head { grid-area: head; display: flex; justify-content: space-between; align-items: end; gap: 14px; padding: 16px 20px 12px; }
.dbm-segment__eyebrow { font: 600 10.5px var(--dbm-segment-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-segment-faint); }
.dbm-segment__name {
  display: block; width: min(460px, 100%); margin: 2px 0 0 -6px; padding: 2px 6px; border: 0; border-radius: 6px; background: transparent;
  font-size: clamp(19px, 2.4cqi, 25px); font-weight: 740; letter-spacing: -.03em; outline: none; transition: background-color .2s, box-shadow .2s;
