  --dbm-calendar-side: color-mix(in oklch, var(--dbm-calendar-paper), var(--dbm-calendar-ink) 4%);
  --dbm-calendar-line: color-mix(in oklch, var(--dbm-calendar-ink) 13%, transparent);
  --dbm-calendar-hair: color-mix(in oklch, var(--dbm-calendar-ink) 7%, transparent);
  --dbm-calendar-mute: color-mix(in oklch, var(--dbm-calendar-ink) 62%, var(--dbm-calendar-paper));
  --dbm-calendar-faint: color-mix(in oklch, var(--dbm-calendar-ink) 42%, var(--dbm-calendar-paper));
  --dbm-calendar-t-blog: var(--dbm-calendar-accent);
  --dbm-calendar-t-news: oklch(0.6 0.08 150);
  --dbm-calendar-t-social: oklch(0.74 0.13 82);
  --dbm-calendar-t-video: oklch(0.55 0.08 252);
  --dbm-calendar-t-webinar: oklch(0.52 0.1 340);
  --dbm-calendar-t-case: oklch(0.58 0.08 196);
  --dbm-calendar-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-calendar-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --dbm-calendar-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-calendar-out: cubic-bezier(.2, .9, .2, 1);
  --dbm-calendar-spring: linear(0, .06 2.3%, .25 5.6%, .54 10%, .82 15.5%, .98 21.5%, 1.05 27%, 1.06 31%, 1.03 39%, 1.005 51%, 1);
  width: 100%;
  height: var(--dbm-calendar-h, 680px);
  container-type: inline-size;
  container-name: dbm-calendar;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dbm-calendar-paper);
  color: var(--dbm-calendar-ink);
  font: 13px/1.45 var(--dbm-calendar-sans);
  accent-color: var(--dbm-calendar-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dbm-calendar-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button, select) { font: inherit; color: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-calendar-accent); outline-offset: 2px; border-radius: 6px; }
}
.dbm-calendar__app {
  height: 100%; display: grid; position: relative;
  grid-template-columns: 224px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head" "side main";
}
.dbm-calendar__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

/* ------------------------------------------------------------ side */
.dbm-calendar__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 15px; padding: 16px 14px; background: var(--dbm-calendar-side); border-right: 1px solid var(--dbm-calendar-line); overflow: auto; scrollbar-width: thin; }
.dbm-calendar__brand {
  display: flex; align-items: center; gap: 10px;
  & span:last-child { display: grid; line-height: 1.2; }
  & b { font: 700 15px var(--dbm-calendar-serif); letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dbm-calendar-faint); }
}
.dbm-calendar__logo { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; background: var(--dbm-calendar-ink); & svg { width: 18px; height: 18px; fill: none; stroke: var(--dbm-calendar-paper); stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; } }
.dbm-calendar__nav {
  display: grid; gap: 2px;
  & button { display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 9px; font-weight: 600; color: var(--dbm-calendar-mute); transition: background-color .2s, color .2s; }
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { background: var(--dbm-calendar-hair); color: var(--dbm-calendar-ink); }
  & button[aria-selected="true"] { background: var(--dbm-calendar-card); color: var(--dbm-calendar-ink); box-shadow: 0 1px 0 var(--dbm-calendar-line), 0 0 0 1px var(--dbm-calendar-hair); }
  & button[aria-selected="true"] svg { stroke: var(--dbm-calendar-accent); }
}
.dbm-calendar__lbl { font: 650 10px var(--dbm-calendar-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--dbm-calendar-faint); margin-bottom: 7px; }
.dbm-calendar__types {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--dbm-calendar-mute); box-shadow: inset 0 0 0 1px var(--dbm-calendar-line); transition: background-color .15s, color .15s, opacity .15s; }
  & button i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & button[aria-pressed="true"] { background: color-mix(in oklch, var(--c) 14%, var(--dbm-calendar-card)); color: var(--dbm-calendar-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent); }
  & button[aria-pressed="false"] { opacity: .6; }
}
.dbm-calendar__owners {
  display: flex; gap: 0;
  & button { width: 32px; height: 32px; margin-right: -6px; border-radius: 50%; display: grid; place-items: center; font: 700 10.5px var(--dbm-calendar-sans); color: white; background: var(--c); box-shadow: 0 0 0 2px var(--dbm-calendar-side); transition: translate .25s var(--dbm-calendar-spring), opacity .2s, filter .2s; }
  & button:hover { translate: 0 -3px; z-index: 1; }
  & button[aria-pressed="false"] { opacity: .35; filter: grayscale(1); }
}
.dbm-calendar__cad {
  display: block; width: 100%; height: auto; overflow: visible;
  & .hit { fill: transparent; }
  & .wk { cursor: pointer; outline: none; }
  & .st rect { transition: y .5s var(--dbm-calendar-out), height .5s var(--dbm-calendar-out), filter .15s; }
  & .wk:hover .st rect { filter: brightness(1.08) saturate(1.15); }
  & .wk:focus-visible .hit { fill: color-mix(in oklch, var(--dbm-calendar-accent) 10%, transparent); stroke: var(--dbm-calendar-accent); stroke-width: 1.2; rx: 4px; }
  & text { font: 650 8.5px var(--dbm-calendar-mono); fill: var(--dbm-calendar-faint); text-anchor: middle; font-variant-numeric: tabular-nums; }
  & .v { font-size: 10px; font-weight: 750; fill: var(--dbm-calendar-ink); paint-order: stroke; stroke: var(--dbm-calendar-side); stroke-width: 3px; stroke-linejoin: round; transition: y .5s var(--dbm-calendar-out); }
  & .wk.is-under .v { fill: var(--dbm-calendar-mute); }
  & .wk.is-launch .x { fill: var(--dbm-calendar-accent); }
  & .base { stroke: var(--dbm-calendar-line); }
  & .tg { stroke: var(--dbm-calendar-ink); stroke-opacity: .5; stroke-dasharray: 2 3; transition: y1 .5s, y2 .5s; }
  &.is-enter .st { transform-box: fill-box; transform-origin: 50% 100%; animation: dbm-calendar-grow .8s var(--dbm-calendar-spring) both; animation-delay: calc(var(--i) * 70ms + 200ms); }
  &.is-enter .v { animation: dbm-calendar-fade .4s ease-out both; animation-delay: calc(var(--i) * 70ms + 500ms); }
}
@keyframes dbm-calendar-grow { from { transform: scaleY(0); } }
@keyframes dbm-calendar-fade { from { opacity: 0; } }
.dbm-calendar__cadsum { font-family: var(--dbm-calendar-sans); letter-spacing: 0; text-transform: none; }
.dbm-calendar__backlogw { flex: 1; min-height: 120px; display: flex; flex-direction: column; }
.dbm-calendar__bcount { font-family: var(--dbm-calendar-sans); letter-spacing: 0; text-transform: none; }
.dbm-calendar__backlog {
  flex: 1; display: grid; align-content: start; gap: 5px; padding: 6px; border-radius: 10px; border: 1.5px dashed var(--dbm-calendar-line); transition: background-color .15s, border-color .15s;
  &.is-over { background: color-mix(in oklch, var(--dbm-calendar-accent) 8%, transparent); border-color: var(--dbm-calendar-accent); }
  & .dbm-calendar__chip { height: auto; padding: 6px 8px; white-space: normal; }
  & .dbm-calendar__chip b { white-space: normal; }
}

/* ------------------------------------------------------------ head */
.dbm-calendar__head { grid-area: head; display: flex; justify-content: space-between; align-items: end; gap: 14px; flex-wrap: wrap; padding: 16px 20px 10px; }
.dbm-calendar__eyebrow { font: 650 10.5px var(--dbm-calendar-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbm-calendar-accent); }
.dbm-calendar__title { font: 600 clamp(26px, 3.6cqi, 40px)/1 var(--dbm-calendar-serif); letter-spacing: -.025em; margin-top: 3px; & span { color: var(--dbm-calendar-faint); font-weight: 400; } }
.dbm-calendar__hr { display: flex; align-items: center; gap: 14px; }
.dbm-calendar__stat {
  display: flex; gap: 14px;
  & li { display: grid; text-align: right; }
  & b { font-size: 18px; font-weight: 750; letter-spacing: -.02em; font-variant-numeric: tabular-nums; line-height: 1.1; }
  & span { font: 600 9.5px var(--dbm-calendar-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-calendar-faint); }
}
.dbm-calendar__wnav {
  display: flex; align-items: center; gap: 4px; padding: 3px; border-radius: 9px; background: var(--dbm-calendar-card); box-shadow: inset 0 0 0 1px var(--dbm-calendar-line);
  & button { width: 26px; height: 26px; border-radius: 6px; display: grid; place-items: center; }
  & button:hover { background: var(--dbm-calendar-hair); }
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & span { font: 650 12px var(--dbm-calendar-mono); min-width: 120px; text-align: center; }
  &[hidden] { display: none; }
}

/* ------------------------------------------------------------ views */
.dbm-calendar__main { grid-area: main; min-height: 0; padding: 0 20px 16px; }
.dbm-calendar__view { height: 100%; min-height: 0; }
.dbm-calendar__view[hidden] { display: none; }
.dbm-calendar__view:not([hidden]) { animation: dbm-calendar-in .4s var(--dbm-calendar-out) both; }
@keyframes dbm-calendar-in { from { opacity: 0; translate: 0 8px; } }

/* month */
.dbm-calendar__v-month { display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dbm-calendar__dow, .dbm-calendar__grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); }
.dbm-calendar__dow span { padding: 0 8px 6px; font: 650 10px var(--dbm-calendar-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbm-calendar-faint); }
.dbm-calendar__grid {
  grid-auto-rows: minmax(0, 1fr); border-radius: 12px; overflow: hidden; background: var(--dbm-calendar-line); gap: 1px;
  box-shadow: 0 0 0 1px var(--dbm-calendar-line);
}
.dbm-calendar__day {
  position: relative; min-height: 0; display: flex; flex-direction: column; gap: 3px; padding: 5px 5px 4px; background: var(--dbm-calendar-card);
  transition: background-color .15s;
  & .dn { display: flex; justify-content: space-between; align-items: center; font: 650 11.5px var(--dbm-calendar-sans); font-variant-numeric: tabular-nums; padding: 0 2px; }
  & .dn small { font: 600 9.5px var(--dbm-calendar-mono); color: var(--dbm-calendar-faint); }
  & .items { display: grid; gap: 3px; min-height: 0; overflow: hidden; align-content: start; }
  & .more { font: 600 10px var(--dbm-calendar-mono); color: var(--dbm-calendar-mute); padding: 0 4px; text-align: left; }
  & .more:hover { color: var(--dbm-calendar-accent); }
  &.is-out { background: color-mix(in oklch, var(--dbm-calendar-card), var(--dbm-calendar-paper) 70%); }
  &.is-out .dn { color: var(--dbm-calendar-faint); }
  &.is-wknd { background: color-mix(in oklch, var(--dbm-calendar-card), var(--dbm-calendar-paper) 45%); }
  &.is-today .dn span { display: inline-grid; place-items: center; min-width: 21px; height: 21px; border-radius: 999px; background: var(--dbm-calendar-accent); color: white; margin-left: -3px; }
  &.is-launch { background: repeating-linear-gradient(-45deg, var(--dbm-calendar-card) 0 9px, color-mix(in oklch, var(--dbm-calendar-accent) 6%, var(--dbm-calendar-card)) 9px 18px); }
  &.is-over { background: color-mix(in oklch, var(--dbm-calendar-accent) 13%, var(--dbm-calendar-card)); box-shadow: inset 0 0 0 2px var(--dbm-calendar-accent); }
}
.dbm-calendar__chip {
  --c: var(--dbm-calendar-faint);
  position: relative; display: flex; align-items: center; gap: 5px; height: 21px; padding: 0 6px 0 7px; border-radius: 5px; min-width: 0; text-align: left;
  background: color-mix(in oklch, var(--c) 13%, var(--dbm-calendar-card)); box-shadow: inset 2.5px 0 0 var(--c);
  font-size: 11px; font-weight: 600; cursor: grab; touch-action: none; user-select: none;
  transition: background-color .15s, box-shadow .15s, opacity .2s;
  & b { flex: 1; min-width: 0; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .ow { flex: none; width: 15px; height: 15px; border-radius: 50%; display: grid; place-items: center; font-size: 7.5px; font-weight: 750; color: white; background: var(--oc); }
  & .st { flex: none; width: 6px; height: 6px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--c); }
  & .st.s3, & .st.s4 { background: var(--c); }
  &:hover { background: color-mix(in oklch, var(--c) 24%, var(--dbm-calendar-card)); }
  &.is-done b { text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--dbm-calendar-ink) 35%, transparent); color: var(--dbm-calendar-mute); }
  &.is-lift { opacity: .25; }
  &.is-open { box-shadow: inset 2.5px 0 0 var(--c), 0 0 0 1.5px var(--dbm-calendar-ink); }
}
.dbm-calendar__ghost {
  position: absolute; z-index: 50; left: 0; top: 0; pointer-events: none; width: 170px;
  rotate: -2.5deg; scale: 1.04; box-shadow: inset 2.5px 0 0 var(--c), 0 16px 30px -10px color-mix(in oklch, var(--dbm-calendar-ink) 45%, transparent);
  background: color-mix(in oklch, var(--c) 18%, var(--dbm-calendar-card)); cursor: grabbing;
}
@starting-style { .dbm-calendar__ghost { rotate: 0deg; scale: 1; } }
.dbm-calendar__ghost { transition: rotate .25s var(--dbm-calendar-spring), scale .25s var(--dbm-calendar-spring); }

/* week */
.dbm-calendar__wgrid {
  height: 100%; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 8px;
  & .wd { min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbm-calendar-card); box-shadow: 0 0 0 1px var(--dbm-calendar-line); transition: background-color .15s, box-shadow .15s; }
  & .wd.is-over { background: color-mix(in oklch, var(--dbm-calendar-accent) 10%, var(--dbm-calendar-card)); box-shadow: 0 0 0 2px var(--dbm-calendar-accent); }
  & .wd.is-today { box-shadow: 0 0 0 1.5px var(--dbm-calendar-accent); }
  & .wh { padding: 9px 10px 6px; border-bottom: 1px solid var(--dbm-calendar-hair); display: flex; justify-content: space-between; align-items: baseline; }
  & .wh b { font: 600 22px/1 var(--dbm-calendar-serif); }
  & .wh span { font: 650 10px var(--dbm-calendar-mono); letter-spacing: .07em; text-transform: uppercase; color: var(--dbm-calendar-faint); }
  & .wl { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 7px; display: grid; align-content: start; gap: 6px; }
  & .dbm-calendar__chip { height: auto; flex-direction: column; align-items: stretch; gap: 4px; padding: 7px 8px 7px 10px; }
  & .dbm-calendar__chip b { white-space: normal; font-size: 11.5px; line-height: 1.3; }
  & .dbm-calendar__chip .meta { display: flex; justify-content: space-between; align-items: center; font: 600 9.5px var(--dbm-calendar-mono); text-transform: uppercase; letter-spacing: .05em; color: var(--dbm-calendar-mute); }
  & .empty { color: var(--dbm-calendar-faint); font-size: 11.5px; text-align: center; padding: 10px 0; }
}

/* pipeline */
.dbm-calendar__cols {
  height: 100%; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px;
  & .col { min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbm-calendar-side); box-shadow: inset 0 0 0 1px var(--dbm-calendar-hair); }
  & .ch { display: flex; justify-content: space-between; padding: 10px 12px 6px; font-weight: 700; font-size: 12.5px; }
  & .ch span { font: 650 11px var(--dbm-calendar-mono); color: var(--dbm-calendar-faint); }
  & .cl { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 4px 8px 10px; display: grid; align-content: start; gap: 6px; }
  & .card { --c: var(--dbm-calendar-faint); display: grid; gap: 5px; padding: 9px 10px; border-radius: 9px; background: var(--dbm-calendar-card); box-shadow: inset 3px 0 0 var(--c), 0 1px 2px var(--dbm-calendar-line); }
  & .card b { font-size: 12px; line-height: 1.3; text-wrap: pretty; cursor: pointer; }
  & .card b:hover { text-decoration: underline; }
  & .card .meta { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 4px 6px; font: 600 10px var(--dbm-calendar-mono); color: var(--dbm-calendar-mute); text-transform: uppercase; letter-spacing: .04em; & > span { white-space: nowrap; } }
  & .card .adv { white-space: nowrap; font: 650 10.5px var(--dbm-calendar-sans); letter-spacing: 0; text-transform: none; padding: 3px 7px; border-radius: 5px; color: var(--dbm-calendar-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbm-calendar-accent) 40%, transparent); }
  & .card .adv:hover { background: color-mix(in oklch, var(--dbm-calendar-accent) 10%, transparent); }
}
@supports (animation-timeline: view()) {
  .dbm-calendar__cols .card { animation: dbm-calendar-card linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
@keyframes dbm-calendar-card { from { opacity: .3; scale: .96; } }

/* ------------------------------------------------------------ drawer */
.dbm-calendar__drawer {
  position: absolute; z-index: 40; top: 10px; right: 10px; bottom: 10px; width: min(320px, calc(100% - 20px));
  display: flex; flex-direction: column; gap: 10px; padding: 16px; border-radius: 14px; overflow: auto;
  background: var(--dbm-calendar-card); box-shadow: 0 0 0 1px var(--dbm-calendar-line), -20px 0 50px -20px color-mix(in oklch, var(--dbm-calendar-ink) 40%, transparent);
  translate: 0 0; opacity: 1; transition: translate .4s var(--dbm-calendar-out), opacity .25s, display .4s allow-discrete;
  &[hidden] { display: none; translate: 30px 0; opacity: 0; }
}
@starting-style { .dbm-calendar__drawer:not([hidden]) { translate: 30px 0; opacity: 0; } }
.dbm-calendar__dh { display: flex; justify-content: space-between; align-items: center; }
.dbm-calendar__dtype { display: inline-flex; align-items: center; gap: 6px; font: 650 10.5px var(--dbm-calendar-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--c); &::before { content: ""; width: 9px; height: 9px; border-radius: 2px; background: var(--c); } }
.dbm-calendar__close { width: 28px; height: 28px; border-radius: 7px; display: grid; place-items: center; &:hover { background: var(--dbm-calendar-hair); } & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; } }
.dbm-calendar__dtitle { font: 600 20px/1.2 var(--dbm-calendar-serif); letter-spacing: -.01em; text-wrap: balance; }
.dbm-calendar__dcamp { font-size: 12px; color: var(--dbm-calendar-mute); }
.dbm-calendar__dform {
  display: grid; gap: 8px; padding: 10px 0; border-block: 1px solid var(--dbm-calendar-hair);
  & label { display: grid; grid-template-columns: 96px minmax(0, 1fr); align-items: center; gap: 8px; font-size: 12px; color: var(--dbm-calendar-mute); }
  & select { height: 30px; border-radius: 7px; border: 0; padding: 0 8px; background: var(--dbm-calendar-paper); box-shadow: inset 0 0 0 1px var(--dbm-calendar-line); font-size: 12.5px; color: var(--dbm-calendar-ink); }
}
.dbm-calendar__ddate {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) 30px; height: 30px; border-radius: 7px; box-shadow: inset 0 0 0 1px var(--dbm-calendar-line); background: var(--dbm-calendar-paper); overflow: hidden;
  & button { font-size: 16px; color: var(--dbm-calendar-ink); } & button:hover { background: var(--dbm-calendar-hair); }
  & output { display: grid; place-items: center; font: 650 12px var(--dbm-calendar-mono); color: var(--dbm-calendar-ink); }
}
.dbm-calendar__check {
  display: grid; gap: 4px;
  & label { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 7px; font-size: 12.5px; cursor: pointer; transition: background-color .15s; }
  & label:hover { background: var(--dbm-calendar-hair); }
  & input { margin: 0; width: 15px; height: 15px; }
  & label:has(input:checked) span { color: var(--dbm-calendar-mute); text-decoration: line-through; }
}
.dbm-calendar__unsched { margin-top: auto; height: 32px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--dbm-calendar-mute); box-shadow: inset 0 0 0 1px var(--dbm-calendar-line); &:hover { color: var(--dbm-calendar-ink); background: var(--dbm-calendar-hair); } }

.dbm-calendar__tip {
  position: absolute; z-index: 60; left: 0; top: 0; pointer-events: none; max-width: 240px; padding: 8px 10px; border-radius: 8px;
  background: var(--dbm-calendar-ink); color: var(--dbm-calendar-paper); font-size: 11.5px; opacity: 0; transition: opacity .12s;
  &.is-on { opacity: 1; }
  & h4 { margin: 0 0 3px; font-size: 12px; line-height: 1.3; }
  & p { color: color-mix(in oklch, var(--dbm-calendar-paper) 72%, transparent); }
}

/* ------------------------------------------------------------ container responses */
@container dbm-calendar (width < 1000px) {
  .dbm-calendar__app { grid-template-columns: 190px minmax(0, 1fr); }
  .dbm-calendar__stat { display: none; }
  .dbm-calendar__cols { grid-template-columns: repeat(5, minmax(150px, 1fr)); overflow-x: auto; }
  .dbm-calendar__wgrid { grid-template-columns: repeat(7, minmax(110px, 1fr)); overflow-x: auto; }
}
@container dbm-calendar (width < 760px) {
