const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const doc = root.ownerDocument;

/* ---------------------------------------------------------------- calendar frame: Mon Sep 28 to Sun Nov 1 2026 */
const DAY = 864e5, D0 = Date.UTC(2026, 8, 28), NDAYS = 35, TODAY = 4, LAUNCH = 16;
const dt = d => new Date(D0 + d * DAY);
const fD = d => dt(d).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' });
const fS = d => dt(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const di = (m, d) => Math.round((Date.UTC(2026, m - 1, d) - D0) / DAY);
const TYPES = { blog: 'Blog', news: 'Newsletter', social: 'Social', video: 'Video', webinar: 'Webinar', case: 'Case study' };
const OWNERS = { ML: ['Mara Lindqvist', 'oklch(0.55 0.12 40)'], DO: ['Dev Okafor', 'oklch(0.5 0.08 150)'], PN: ['Priya Natarajan', 'oklch(0.52 0.1 300)'], TR: ['Tomás Reyes', 'oklch(0.5 0.09 245)'], JH: ['June Hollis', 'oklch(0.6 0.12 75)'] };
const STATUS = ['Idea', 'Drafting', 'In review', 'Scheduled', 'Published'];
const CHECKS = {
  blog: ['Outline approved', 'Draft complete', 'Images exported', 'SEO title and slug set'],
  news: ['Sections assigned', 'Copy edited', 'Links checked', 'Test send to team'],
  social: ['Copy written', 'Visual exported', 'Alt text added', 'Queued in scheduler'],
  video: ['Script locked', 'Rough cut', 'Captions', 'Thumbnail'],
  webinar: ['Speakers confirmed', 'Registration page live', 'Run of show', 'Reminder emails'],
  case: ['Customer interview', 'Draft approved by customer', 'Quotes signed off', 'Design pass']
};
const RAW = [
  ['Why we rebuilt the layers panel', 'blog', 'ML', 4, di(10, 1), 'Evergreen'],
  ['Teaser: something new on the 14th', 'social', 'JH', 4, di(10, 1), 'Halyard 4 launch'],
  ['The Halyard Dispatch #41', 'news', 'DO', 4, di(10, 2), 'Weekly dispatch'],
  ['September changelog roundup', 'blog', 'TR', 4, di(9, 29), 'Evergreen'],
  ['Poll: dark or light canvas?', 'social', 'JH', 4, di(9, 30), 'Community'],
  ['Design tokens without the drama', 'blog', 'PN', 3, di(10, 5), 'Evergreen'],
  ['Behind the canvas: Ana Ruiz', 'social', 'JH', 3, di(10, 6), 'Community'],
  ['Auto-layout in 90 seconds', 'video', 'TR', 2, di(10, 6), 'Halyard 4 launch'],
  ['How Brightline cut handoff time 40%', 'case', 'ML', 2, di(10, 7), 'Customer stories'],
  ['Live: components at scale', 'webinar', 'PN', 3, di(10, 8), 'Halyard 4 launch'],
  ['The Halyard Dispatch #42', 'news', 'DO', 1, di(10, 9), 'Weekly dispatch'],
  ['A field guide to variable fonts in UI', 'blog', 'TR', 1, di(10, 12), 'Evergreen'],
  ['Countdown: one day to go', 'social', 'JH', 1, di(10, 13), 'Halyard 4 launch'],
  ['Halyard 4 trailer', 'video', 'TR', 2, di(10, 13), 'Halyard 4 launch'],
  ['Introducing Halyard 4', 'blog', 'ML', 2, di(10, 14), 'Halyard 4 launch'],
  ['Halyard 4 is here', 'news', 'DO', 1, di(10, 14), 'Halyard 4 launch'],
  ['Launch thread: 12 things in Halyard 4', 'social', 'JH', 1, di(10, 14), 'Halyard 4 launch'],
  ['Halyard 4 keynote cut', 'video', 'TR', 1, di(10, 14), 'Halyard 4 launch'],
  ['Halyard 4 deep dive', 'webinar', 'PN', 3, di(10, 15), 'Halyard 4 launch'],
  ['The Halyard Dispatch #43', 'news', 'DO', 0, di(10, 16), 'Weekly dispatch'],
  ['Northpine’s design system migration', 'case', 'ML', 1, di(10, 19), 'Customer stories'],
  ['User spotlight: Kofi Mensah', 'social', 'JH', 0, di(10, 20), 'Community'],
  ['Shipping multiplayer cursors', 'blog', 'PN', 1, di(10, 21), 'Engineering'],
  ['Prototyping tips, part 3', 'video', 'TR', 0, di(10, 22), 'Evergreen'],
  ['The Halyard Dispatch #44', 'news', 'DO', 0, di(10, 23), 'Weekly dispatch'],
  ['Accessibility checks while you design', 'blog', 'PN', 0, di(10, 26), 'Evergreen'],
  ['Halloween icon pack drop', 'social', 'JH', 0, di(10, 27), 'Community'],
  ['Office hours: Halyard 4 Q&A', 'webinar', 'PN', 0, di(10, 28), 'Halyard 4 launch'],
  ['Studio Vela on async critique', 'case', 'ML', 0, di(10, 29), 'Customer stories'],
  ['The Halyard Dispatch #45', 'news', 'DO', 0, di(10, 30), 'Weekly dispatch'],
  ['Interview: the team behind our icons', 'blog', 'ML', 0, null, 'Evergreen'],
  ['Shortcut cheat sheet carousel', 'social', 'JH', 0, null, 'Evergreen'],
  ['Plugin API walkthrough', 'video', 'TR', 0, null, 'Engineering'],
  ['Q4 customer roundtable', 'webinar', 'PN', 0, null, 'Customer stories']
];
const ITEMS = RAW.map(([title, t, o, s, d, camp], i) => ({ id: 'c' + i, title, t, o, s, d, camp, ck: CHECKS[t].map((_, k) => k < [0, 1, 2, 4, 4][s]) }));
const byId = Object.fromEntries(ITEMS.map(x => [x.id, x]));

/* ---------------------------------------------------------------- state */
const S = { view: 'month', types: new Set(Object.keys(TYPES)), owners: new Set(Object.keys(OWNERS)), week: 0, open: null };
const shown = x => S.types.has(x.t) && S.owners.has(x.o);
const sr = $('.dbm-calendar__sr');

/* ---------------------------------------------------------------- tooltip */
const tip = $('.dbm-calendar__tip');
function showTip(x, cx, cy) { showTipHTML(`<h4>${esc(x.title)}</h4><p>${TYPES[x.t]} · ${OWNERS[x.o][0]} · ${STATUS[x.s]}</p>`, cx, cy); }
function showTipHTML(html, cx, cy) {
  tip.innerHTML = html; tip.classList.add('is-on');
  const rr = root.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let lx = cx - rr.left + 12, ly = cy - rr.top - th - 12;
  if (lx + tw > rr.width - 8) lx = cx - rr.left - tw - 12;
  if (ly < 8) ly = cy - rr.top + 16;
  tip.style.translate = `${Math.max(8, lx)}px ${ly}px`;
}
const hideTip = () => tip.classList.remove('is-on');

/* ---------------------------------------------------------------- filters */
const typeBox = $('.dbm-calendar__types'), ownBox = $('.dbm-calendar__owners');
typeBox.innerHTML = Object.entries(TYPES).map(([k, n]) => `<button aria-pressed="true" data-t="${k}" style="--c:var(--dbm-calendar-t-${k})"><i></i>${n}</button>`).join('');
ownBox.innerHTML = Object.entries(OWNERS).map(([k, [n, c]]) => `<button aria-pressed="true" data-o="${k}" style="--c:${c}" title="${n}" aria-label="${n}">${k}</button>`).join('');
function toggle(set, k, all) { if (set.has(k) && set.size === 1) all.forEach(x => set.add(x)); else set.has(k) ? set.delete(k) : set.add(k); }
typeBox.addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; toggle(S.types, b.dataset.t, Object.keys(TYPES)); $$('button', typeBox).forEach(x => x.setAttribute('aria-pressed', S.types.has(x.dataset.t))); render(); });
ownBox.addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; toggle(S.owners, b.dataset.o, Object.keys(OWNERS)); $$('button', ownBox).forEach(x => x.setAttribute('aria-pressed', S.owners.has(x.dataset.o))); render(); });

/* ---------------------------------------------------------------- chips */
function chip(x, big) {
  const meta = big ? `<span class="meta"><span>${STATUS[x.s]}</span><span class="ow" style="--oc:${OWNERS[x.o][1]}">${x.o}</span></span>` : `<span class="st s${x.s}"></span><span class="ow" style="--oc:${OWNERS[x.o][1]}">${x.o}</span>`;
  return `<button class="dbm-calendar__chip${x.s === 4 ? ' is-done' : ''}${S.open === x.id ? ' is-open' : ''}" data-id="${x.id}" style="--c:var(--dbm-calendar-t-${x.t})" aria-label="${esc(x.title)}, ${TYPES[x.t]}, ${STATUS[x.s]}, ${x.d == null ? 'unscheduled' : fD(x.d)}. Shift and arrow keys move it." aria-haspopup="dialog"><b>${esc(x.title)}</b>${meta}</button>`;
}
function rects() { const m = new Map(); $$('.dbm-calendar__chip:not(.dbm-calendar__ghost), .dbm-calendar__cols .card').forEach(el => m.set(el.dataset.id, el.getBoundingClientRect())); return m; }
function flipFrom(before, special) {
  if (RM) return;
  $$('.dbm-calendar__chip:not(.dbm-calendar__ghost), .dbm-calendar__cols .card').forEach(el => {
    const b = special && special.id === el.dataset.id ? special.r : before.get(el.dataset.id); if (!b) return;
    const a = el.getBoundingClientRect(), dx = b.left - a.left, dy = b.top - a.top;
    if (Math.abs(dx) + Math.abs(dy) < 1) return;
    el.animate([{ transform: `translate(${dx}px,${dy}px)${special && special.id === el.dataset.id ? ' rotate(-2.5deg) scale(1.04)' : ''}` }, { transform: 'none' }], { duration: 480, easing: 'cubic-bezier(.2,.9,.2,1)' });
  });
}

/* ---------------------------------------------------------------- month */
const grid = $('.dbm-calendar__grid');
function renderMonth() {
  const items = ITEMS.filter(x => shown(x) && x.d != null);
  const w = root.clientWidth, pitch = w < 520 ? 9 : w < 760 ? 21 : 24;
  const cellH = grid.clientHeight / 5 || 100, fit = Math.max(1, Math.floor((cellH - 26) / pitch));
  let html = '';
  for (let d = 0; d < NDAYS; d++) {
    const date = dt(d), out = date.getUTCMonth() !== 9, wk = d % 7 >= 5, its = items.filter(x => x.d === d);
    const wkCount = d % 7 === 0 ? items.filter(x => x.d >= d && x.d < d + 7).length : 0;
    const vis = its.length > fit ? its.slice(0, fit - 1) : its;
    html += `<div class="dbm-calendar__day${out ? ' is-out' : ''}${wk ? ' is-wknd' : ''}${d === TODAY ? ' is-today' : ''}${d === LAUNCH ? ' is-launch' : ''}" data-drop="${d}" role="group" aria-label="${fD(d)}, ${its.length} item${its.length === 1 ? '' : 's'}">
      <span class="dn"><span>${date.getUTCDate()}</span>${d % 7 === 0 ? `<small>W${40 + d / 7} · ${wkCount}</small>` : d === LAUNCH ? '<small>LAUNCH</small>' : ''}</span>
      <div class="items">${vis.map(x => chip(x)).join('')}${its.length > vis.length ? `<button class="more" data-week="${Math.floor(d / 7)}">+${its.length - vis.length} more</button>` : ''}</div></div>`;
  }
  grid.innerHTML = html;
}
grid.addEventListener('click', e => { const m = e.target.closest('.more'); if (m) { S.week = +m.dataset.week; setView('week'); } });

/* ---------------------------------------------------------------- week */
const wgrid = $('.dbm-calendar__wgrid');
function renderWeek() {
  const d0 = S.week * 7;
  $('.dbm-calendar__wlabel').textContent = `${fS(d0)} to ${fS(d0 + 6)}`;
  let html = '';
  for (let d = d0; d < d0 + 7; d++) {
    const its = ITEMS.filter(x => shown(x) && x.d === d);
    html += `<div class="wd${d === TODAY ? ' is-today' : ''}" data-drop="${d}" role="group" aria-label="${fD(d)}"><div class="wh"><b>${dt(d).getUTCDate()}</b><span>${dt(d).toLocaleDateString('en-US', { weekday: 'short', timeZone: 'UTC' })}${d === LAUNCH ? ' · launch' : ''}</span></div><div class="wl">${its.length ? its.map(x => chip(x, true)).join('') : '<p class="empty">Nothing planned</p>'}</div></div>`;
  }
  wgrid.innerHTML = html;
}
$('.dbm-calendar__wnav').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; S.week = Math.max(0, Math.min(4, S.week + +b.dataset.w)); renderWeek(); });

/* ---------------------------------------------------------------- pipeline */
const cols = $('.dbm-calendar__cols');
function renderPipe() {
  cols.innerHTML = STATUS.map((st, s) => {
    const its = ITEMS.filter(x => shown(x) && x.s === s).sort((a, b) => (a.d ?? 99) - (b.d ?? 99));
    return `<section class="col" aria-label="${st}"><div class="ch">${st}<span>${its.length}</span></div><div class="cl">${its.map(x => `<article class="card" data-id="${x.id}" style="--c:var(--dbm-calendar-t-${x.t})"><b tabindex="0" role="button" aria-haspopup="dialog">${esc(x.title)}</b><div class="meta"><span>${x.d == null ? 'Unscheduled' : fS(x.d)} · ${x.o}</span>${s < 4 ? `<button class="adv" data-id="${x.id}" aria-label="Move ${esc(x.title)} to ${STATUS[s + 1]}">→ ${STATUS[s + 1]}</button>` : ''}</div></article>`).join('')}</div></section>`;
  }).join('');
}
cols.addEventListener('click', e => {
  const a = e.target.closest('.adv');
  if (a) { const x = byId[a.dataset.id], before = rects(); x.s = Math.min(4, x.s + 1); x.ck = x.ck.map((v, k) => v || k < [0, 1, 2, 4, 4][x.s]); render(); flipFrom(before); sr.textContent = `${x.title} moved to ${STATUS[x.s]}`; const n = $(`.adv[data-id="${x.id}"]`, cols) || $(`.card[data-id="${x.id}"] b`, cols); if (n) n.focus(); return; }
  const b = e.target.closest('.card b'); if (b) openDrawer(b.closest('.card').dataset.id);
});
cols.addEventListener('keydown', e => { const b = e.target.closest('.card b'); if (b && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); openDrawer(b.closest('.card').dataset.id); } });

/* ---------------------------------------------------------------- backlog + stats */
const backlog = $('.dbm-calendar__backlog');
function renderSide() {
  const bl = ITEMS.filter(x => shown(x) && x.d == null);
  backlog.innerHTML = bl.map(x => `<li>${chip(x)}</li>`).join('') || '<li style="font-size:11.5px;color:var(--dbm-calendar-faint);padding:6px">Everything is scheduled.</li>';
  $('.dbm-calendar__bcount').textContent = `· ${bl.length}`;
  const oct = ITEMS.filter(x => shown(x) && x.d != null && dt(x.d).getUTCMonth() === 9);
  $('.dbm-calendar__stat').innerHTML = [['Planned', oct.length], ['In review', oct.filter(x => x.s === 2).length], ['Scheduled', oct.filter(x => x.s === 3).length], ['Published', oct.filter(x => x.s === 4).length]].map(([k, v]) => `<li><b>${v}</b><span>${k}</span></li>`).join('');
}

/* ---------------------------------------------------------------- cadence chart: scheduled items per week, stacked by type */
const cad = $('.dbm-calendar__cad'), TKEYS = Object.keys(TYPES), TARGET = 6;
const CW = 196, CH = 90, CB = 15, CT = 14, GAP = 9, BW = (CW - GAP * 4) / 5;
cad.setAttribute('viewBox', `0 0 ${CW} ${CH}`);
cad.innerHTML = `<line class="tg" x1="0" x2="${CW}"/>` + [0, 1, 2, 3, 4].map(w => `<g class="wk${w * 7 <= LAUNCH && LAUNCH < w * 7 + 7 ? ' is-launch' : ''}" data-w="${w}" tabindex="0" role="button" style="--i:${w}"><rect class="hit" x="${w * (BW + GAP) - GAP / 2}" y="0" width="${BW + GAP}" height="${CH}"/><g class="st">${TKEYS.map(t => `<rect data-t="${t}" x="${w * (BW + GAP)}" width="${BW}" rx="1.5" style="fill:var(--dbm-calendar-t-${t})"/>`).join('')}</g><text class="v" x="${w * (BW + GAP) + BW / 2}"></text><text class="x" x="${w * (BW + GAP) + BW / 2}" y="${CH - 3}">W${40 + w}</text></g>`).join('') +
  `<line class="base" x1="0" x2="${CW}" y1="${CH - CB + .5}" y2="${CH - CB + .5}"/>`;
function weekStats(w) { const its = ITEMS.filter(x => shown(x) && x.d != null && x.d >= w * 7 && x.d < w * 7 + 7); return { n: its.length, by: TKEYS.map(t => its.filter(x => x.t === t).length) }; }
function renderCad() {
  const st = [0, 1, 2, 3, 4].map(weekStats), max = Math.max(TARGET + 2, ...st.map(s => s.n)), ph = CH - CB - CT, y = v => CH - CB - v / max * ph;
  st.forEach((s, w) => {
    const g = $(`.wk[data-w="${w}"]`, cad); let acc = 0;
    s.by.forEach((n, k) => { const r = g.querySelectorAll('.st rect')[k]; r.style.y = (y(acc + n) + (n ? .6 : 0)) + 'px'; r.style.height = Math.max(0, (n / max) * ph - (n ? .6 : 0)) + 'px'; acc += n; });
    const v = $('.v', g); v.textContent = s.n; v.setAttribute('y', y(s.n) - 4);
    g.setAttribute('aria-label', `Week ${40 + w}, ${fS(w * 7)} to ${fS(w * 7 + 6)}: ${s.n} item${s.n === 1 ? '' : 's'}, target ${TARGET}`);
    g.classList.toggle('is-under', s.n < TARGET);
  });
  const ty = y(TARGET) + .5; $('.tg', cad).setAttribute('y1', ty); $('.tg', cad).setAttribute('y2', ty);
  const oct = st.reduce((a, s) => a + s.n, 0);
  $('.dbm-calendar__cadsum').textContent = `· avg ${(oct / 5).toFixed(1)} · target ${TARGET}`;
}
function weekTip(g, cx, cy) {
  const w = +g.dataset.w, s = weekStats(w);
  showTipHTML(`<h4>W${40 + w} · ${fS(w * 7)} to ${fS(w * 7 + 6)}</h4><p>${s.by.map((n, k) => n ? `${n} ${TYPES[TKEYS[k]].toLowerCase()}` : '').filter(Boolean).join(' · ') || 'Nothing scheduled'}</p><p>${s.n} of ${TARGET} target${w * 7 <= LAUNCH && LAUNCH < w * 7 + 7 ? ' · launch week' : ''}</p>`, cx, cy);
}
cad.addEventListener('click', e => { const g = e.target.closest('.wk'); if (g) { S.week = +g.dataset.w; setView('week'); } });
cad.addEventListener('keydown', e => {
  const g = e.target.closest('.wk'); if (!g) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); S.week = +g.dataset.w; setView('week'); return; }
  const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key]; if (d == null) return;
  e.preventDefault(); const n = $(`.wk[data-w="${(+g.dataset.w + d + 5) % 5}"]`, cad); n.focus();
});
cad.addEventListener('focusin', e => { const g = e.target.closest('.wk'); if (g) { const r = g.getBoundingClientRect(); weekTip(g, r.left + r.width / 2, r.top + 10); } });
cad.addEventListener('focusout', hideTip);
setTimeout(() => cad.classList.remove('is-enter'), 1600);

/* ---------------------------------------------------------------- views */
const tabs = $$('.dbm-calendar__nav [role="tab"]');
function setView(v, focus) {
  S.view = v; hideTip();
  tabs.forEach(t => { const on = t.dataset.view === v; t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); });
  $$('.dbm-calendar__view').forEach(p => p.hidden = p.dataset.view !== v);
  $('.dbm-calendar__wnav').hidden = v !== 'week';
  $('.dbm-calendar__title').innerHTML = v === 'pipe' ? 'Pipeline <span>Oct 2026</span>' : 'October <span>2026</span>';
  render();
}
$('.dbm-calendar__nav').addEventListener('click', e => { const t = e.target.closest('[role="tab"]'); if (t) setView(t.dataset.view); });
$('.dbm-calendar__nav').addEventListener('keydown', e => { const i = tabs.indexOf(doc.activeElement), d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (i < 0 || d == null) return; e.preventDefault(); setView(tabs[(i + d + tabs.length) % tabs.length].dataset.view, true); });
function render() {
  renderSide(); renderCad();
  if (S.view === 'month') renderMonth(); else if (S.view === 'week') renderWeek(); else renderPipe();
  if (S.open) fillDrawer();
}

/* ---------------------------------------------------------------- drag and drop (pointer events, captured on the chip) */
let drag = null, swallowClick = false;
const app = $('.dbm-calendar__app');
root.addEventListener('pointerdown', e => {
  const c = e.target.closest('.dbm-calendar__chip'); if (!c || e.button !== 0 || c.classList.contains('dbm-calendar__ghost')) return;
  drag = { id: c.dataset.id, x0: e.clientX, y0: e.clientY, el: c, started: false, pid: e.pointerId, over: null };
});
root.addEventListener('pointermove', e => {
  if (!drag) {
    const c = e.target.closest('.dbm-calendar__chip'), g = e.target.closest('.dbm-calendar__cad .wk');
    if (c && !c.closest('.dbm-calendar__wgrid')) showTip(byId[c.dataset.id], e.clientX, e.clientY); else if (g) weekTip(g, e.clientX, e.clientY); else hideTip();
    return;
  }
  if (!drag.started) {
    if (Math.hypot(e.clientX - drag.x0, e.clientY - drag.y0) < 5) return;
    drag.started = true; hideTip();
    try { drag.el.setPointerCapture(drag.pid); } catch (_) { }
    const r = drag.el.getBoundingClientRect();
    drag.dx = e.clientX - r.left; drag.dy = e.clientY - r.top;
    const g = drag.el.cloneNode(true); g.classList.add('dbm-calendar__ghost'); g.removeAttribute('aria-label'); g.setAttribute('aria-hidden', 'true'); g.style.width = Math.max(150, r.width) + 'px';
    app.appendChild(g); drag.ghost = g; drag.el.classList.add('is-lift');
  }
  const rr = root.getBoundingClientRect();
  drag.ghost.style.translate = `${e.clientX - rr.left - drag.dx}px ${e.clientY - rr.top - drag.dy}px`;
  const under = doc.elementFromPoint(e.clientX, e.clientY), tgt = under && root.contains(under) ? under.closest('[data-drop]') : null;
  if (tgt !== drag.over) { if (drag.over) drag.over.classList.remove('is-over'); if (tgt) tgt.classList.add('is-over'); drag.over = tgt; }
});
function endDrag(cancel) {
  const d = drag; drag = null;
  if (!d || !d.started) return;
  swallowClick = true; setTimeout(() => { swallowClick = false; }, 0);
  const gr = d.ghost.getBoundingClientRect(); d.ghost.remove(); d.el.classList.remove('is-lift');
  if (d.over) d.over.classList.remove('is-over');
  if (cancel || !d.over) return;
  const x = byId[d.id], to = d.over.dataset.drop === 'backlog' ? null : +d.over.dataset.drop;
  if (to === x.d) return;
  const before = rects(); x.d = to; render(); flipFrom(before, { id: x.id, r: gr });
  sr.textContent = `${x.title} moved to ${to == null ? 'unscheduled' : fD(to)}`;
}
root.addEventListener('pointerup', () => endDrag(false));
root.addEventListener('pointercancel', () => endDrag(true));
root.addEventListener('pointerleave', () => { if (!drag) hideTip(); });

/* click opens details; Shift+arrows reschedule from the keyboard */
root.addEventListener('click', e => {
  if (swallowClick) return;
  const c = e.target.closest('.dbm-calendar__chip'); if (c && !c.classList.contains('dbm-calendar__ghost')) openDrawer(c.dataset.id);
});
root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { if (drag && drag.started) { endDrag(true); return; } if (S.open) { closeDrawer(); return; } }
  const c = e.target.closest('.dbm-calendar__chip');
  if (!c || !e.shiftKey) return;
  const step = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key]; if (step == null) return;
  e.preventDefault();
  const x = byId[c.dataset.id]; if (x.d == null) x.d = TODAY;
  const to = Math.max(0, Math.min(NDAYS - 1, x.d + step)); if (to === x.d) return;
  if (S.view === 'week' && Math.floor(to / 7) !== S.week) S.week = Math.floor(to / 7);
  const before = rects(); x.d = to; render(); flipFrom(before);
  sr.textContent = `${x.title} moved to ${fD(to)}`;
  const n = $(`.dbm-calendar__chip[data-id="${x.id}"]`); if (n) n.focus();
});

/* ---------------------------------------------------------------- drawer */
const drawer = $('.dbm-calendar__drawer');
let opener = null;
$('.dbm-calendar__dstatus').innerHTML = STATUS.map((s, i) => `<option value="${i}">${s}</option>`).join('');
$('.dbm-calendar__downer').innerHTML = Object.entries(OWNERS).map(([k, [n]]) => `<option value="${k}">${n}</option>`).join('');
function fillDrawer() {
  const x = byId[S.open]; if (!x) return;
  const ty = $('.dbm-calendar__dtype'); ty.textContent = TYPES[x.t]; ty.style.setProperty('--c', `var(--dbm-calendar-t-${x.t})`);
  $('.dbm-calendar__dtitle').textContent = x.title;
  $('.dbm-calendar__dcamp').textContent = `${x.camp} · owned by ${OWNERS[x.o][0]}`;
  $('.dbm-calendar__ddate output').textContent = x.d == null ? 'Unscheduled' : fD(x.d);
  $('.dbm-calendar__dstatus').value = x.s; $('.dbm-calendar__downer').value = x.o;
  $('.dbm-calendar__check').innerHTML = CHECKS[x.t].map((c, k) => `<li><label><input type="checkbox" data-k="${k}"${x.ck[k] ? ' checked' : ''}><span>${c}</span></label></li>`).join('');
  $('.dbm-calendar__unsched').hidden = x.d == null;
  $$('.dbm-calendar__chip').forEach(el => el.classList.toggle('is-open', el.dataset.id === x.id));
}
function openDrawer(id) {
  opener = doc.activeElement && root.contains(doc.activeElement) ? doc.activeElement : null;
  S.open = id; drawer.hidden = false; fillDrawer(); hideTip();
  $('.dbm-calendar__close').focus({ preventScroll: true });
}
function closeDrawer() {
  const id = S.open; S.open = null; drawer.hidden = true;
  $$('.dbm-calendar__chip.is-open').forEach(el => el.classList.remove('is-open'));
  const back = $(`.dbm-calendar__chip[data-id="${id}"]`) || opener; if (back && back.isConnected) back.focus({ preventScroll: true });
}
$('.dbm-calendar__close').addEventListener('click', closeDrawer);
drawer.addEventListener('change', e => {
  const x = byId[S.open]; if (!x) return;
  if (e.target.classList.contains('dbm-calendar__dstatus')) { x.s = +e.target.value; render(); }
  else if (e.target.classList.contains('dbm-calendar__downer')) { x.o = e.target.value; render(); }
  else if (e.target.dataset.k != null) x.ck[+e.target.dataset.k] = e.target.checked;
});
drawer.addEventListener('click', e => {
  const x = byId[S.open]; if (!x) return;
  const b = e.target.closest('[data-dd]');
  if (b) { const before = rects(); x.d = Math.max(0, Math.min(NDAYS - 1, (x.d ?? TODAY) + +b.dataset.dd)); if (S.view === 'week') S.week = Math.floor(x.d / 7); render(); flipFrom(before); return; }
  if (e.target.closest('.dbm-calendar__unsched')) { const before = rects(); x.d = null; render(); flipFrom(before); }
});

/* ---------------------------------------------------------------- mount */
render();
if (!RM) $$('.dbm-calendar__chip', grid).forEach((c, i) => c.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 420, delay: 80 + i * 18, easing: 'cubic-bezier(.2,.9,.2,1)', fill: 'backwards' }));
let lastH = 0;
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } const h = grid.clientHeight; if (S.view === 'month' && Math.abs(h - lastH) > 20) { lastH = h; renderMonth(); } });
ro.observe(grid);

