@property --dbm-warroom-sold {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 0%;
}
.dbm-warroom {
  /* re-theme with these four */
  --dbm-warroom-bg: oklch(0.17 0.006 255);
  --dbm-warroom-ink: oklch(0.95 0.005 250);
  --dbm-warroom-signal: oklch(0.72 0.19 42);
  --dbm-warroom-go: oklch(0.8 0.16 152);
  /* status and series */
  --dbm-warroom-warn: oklch(0.85 0.15 88);
  --dbm-warroom-bad: oklch(0.66 0.22 25);
  --dbm-warroom-s0: oklch(0.86 0.02 250);
  --dbm-warroom-s1: var(--dbm-warroom-signal);
  --dbm-warroom-s2: oklch(0.74 0.14 352);
  --dbm-warroom-s3: oklch(0.87 0.12 95);
  --dbm-warroom-s4: oklch(0.68 0.12 300);
  --dbm-warroom-s5: oklch(0.72 0.1 222);
  /* derived */
  --dbm-warroom-panel: color-mix(in oklch, var(--dbm-warroom-bg), var(--dbm-warroom-ink) 4%);
  --dbm-warroom-raise: color-mix(in oklch, var(--dbm-warroom-bg), var(--dbm-warroom-ink) 8%);
  --dbm-warroom-line: color-mix(in oklch, var(--dbm-warroom-ink) 11%, transparent);
  --dbm-warroom-hair: color-mix(in oklch, var(--dbm-warroom-ink) 6%, transparent);
  --dbm-warroom-mute: color-mix(in oklch, var(--dbm-warroom-ink) 64%, var(--dbm-warroom-bg));
  --dbm-warroom-faint: color-mix(in oklch, var(--dbm-warroom-ink) 42%, var(--dbm-warroom-bg));
  --dbm-warroom-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbm-warroom-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbm-warroom-out: cubic-bezier(.16, 1, .3, 1);
  --dbm-warroom-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.077, 1.121 24.6%, 1.149 27.6%, 1.159 31.4%, 1.146 35.4%, 1.051 49.3%, 1.017 56.5%, .992 66%, 1.001 85%, 1);
  width: 100%;
  height: var(--dbm-warroom-h, 680px);
  container-type: inline-size;
  container-name: dbm-warroom;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background:
    radial-gradient(120% 70% at 50% -20%, color-mix(in oklch, var(--dbm-warroom-signal) 9%, transparent), transparent 60%),
    var(--dbm-warroom-bg);
  color: var(--dbm-warroom-ink);
  font: 13px/1.45 var(--dbm-warroom-sans);
  accent-color: var(--dbm-warroom-signal);
  color-scheme: dark;
  scrollbar-color: color-mix(in oklch, var(--dbm-warroom-ink) 20%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ol, ul) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbm-warroom-signal); outline-offset: 2px; border-radius: 6px; }
  & svg { overflow: visible; }
}
.dbm-warroom__app { height: 100%; display: grid; grid-template-columns: 64px minmax(0, 1fr); grid-template-areas: "rail main"; }

/* ------------------------------------------------------------ rail */
.dbm-warroom__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 16px 0 14px;
  border-right: 1px solid var(--dbm-warroom-line); background: color-mix(in oklch, var(--dbm-warroom-bg), black 22%);
}
.dbm-warroom__mark {
  width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center;
  background: var(--dbm-warroom-signal); color: var(--dbm-warroom-bg);
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.dbm-warroom__tabs {
  display: grid; gap: 6px;
  & button { position: relative; width: 48px; height: 50px; border-radius: 11px; display: grid; place-items: center; align-content: center; gap: 3px; color: var(--dbm-warroom-faint); transition: color .2s, background-color .2s; }
  & svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & span { font-size: 9.5px; font-weight: 650; letter-spacing: .02em; }
  & button:hover { color: var(--dbm-warroom-ink); background: var(--dbm-warroom-hair); }
  & button[aria-selected="true"] { color: var(--dbm-warroom-ink); background: var(--dbm-warroom-raise); }
  & button[aria-selected="true"]::before { content: ""; position: absolute; left: -8px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbm-warroom-signal); }
}
.dbm-warroom__late { position: absolute; top: 7px; right: 9px; width: 7px; height: 7px; border-radius: 50%; background: var(--dbm-warroom-bad); box-shadow: 0 0 0 2px color-mix(in oklch, var(--dbm-warroom-bg), black 22%); &[hidden] { display: none; } }
.dbm-warroom__oncall { margin-top: auto; width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font: 700 10.5px var(--dbm-warroom-sans); background: color-mix(in oklch, var(--dbm-warroom-s4) 45%, var(--dbm-warroom-bg)); box-shadow: 0 0 0 2px var(--dbm-warroom-bg), 0 0 0 3.5px var(--dbm-warroom-go); }

/* ------------------------------------------------------------ main + head */
.dbm-warroom__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 14px 16px 16px; overflow: auto; scrollbar-width: thin; }
.dbm-warroom__head { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 12px; }
.dbm-warroom__id { min-width: 0; & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; & span { font-weight: 450; color: var(--dbm-warroom-mute); } } }
.dbm-warroom__eyebrow { display: flex; align-items: center; gap: 7px; font: 650 10.5px var(--dbm-warroom-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--dbm-warroom-signal); }
.dbm-warroom__live {
  position: relative; width: 7px; height: 7px; border-radius: 50%; background: var(--dbm-warroom-signal);
  &::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; border: 1.5px solid var(--dbm-warroom-signal); animation: dbm-warroom-ping 1.8s var(--dbm-warroom-out) infinite; }
}
.dbm-warroom:has(.dbm-warroom__play[aria-pressed="false"]) .dbm-warroom__live { background: var(--dbm-warroom-faint); &::after { animation: none; opacity: 0; } }
@keyframes dbm-warroom-ping { from { scale: .4; opacity: 1; } to { scale: 1.8; opacity: 0; } }
.dbm-warroom__clock {
  display: grid; justify-items: center; line-height: 1;
  & .dbm-warroom__tplus { font: 650 clamp(22px, 3.1cqi, 34px) var(--dbm-warroom-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & .dbm-warroom__wall { margin-top: 4px; font: 600 10.5px var(--dbm-warroom-mono); letter-spacing: .08em; color: var(--dbm-warroom-faint); font-variant-numeric: tabular-nums; }
}
.dbm-warroom__ctl { display: flex; justify-content: end; align-items: center; gap: 6px; }
.dbm-warroom__go {
  --c: var(--dbm-warroom-go);
  display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 11px; border-radius: 8px; margin-right: 4px;
  font: 700 11px var(--dbm-warroom-mono); letter-spacing: .08em; color: var(--c);
  background: color-mix(in oklch, var(--c) 13%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 40%, transparent);
  transition: color .3s, background-color .3s, box-shadow .3s;
  &::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: currentColor; }
  &[data-s="watch"] { --c: var(--dbm-warroom-warn); }
  &[data-s="nogo"] { --c: var(--dbm-warroom-bad); }
}
.dbm-warroom__btn {
  height: 30px; min-width: 30px; padding: 0 8px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; gap: 5px;
  font: 700 11px var(--dbm-warroom-mono); color: var(--dbm-warroom-mute); box-shadow: inset 0 0 0 1px var(--dbm-warroom-line); transition: color .2s, background-color .2s, box-shadow .2s;
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { color: var(--dbm-warroom-ink); background: var(--dbm-warroom-hair); }
  &.dbm-warroom__ff[aria-pressed="true"] { color: var(--dbm-warroom-bg); background: var(--dbm-warroom-signal); box-shadow: none; }
  &.dbm-warroom__ff svg { fill: currentColor; stroke-width: 1.2; }
}
.dbm-warroom__play { & .p2 { display: none; fill: currentColor; } &[aria-pressed="false"] { color: var(--dbm-warroom-signal); & .p1 { display: none; } & .p2 { display: block; } } }

/* ------------------------------------------------------------ KPIs */
.dbm-warroom__kpis {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; border-radius: 12px; background: var(--dbm-warroom-panel); box-shadow: inset 0 0 0 1px var(--dbm-warroom-line);
  & > div { position: relative; display: grid; grid-template-rows: auto auto auto; align-content: start; gap: 2px; padding: 10px 14px 11px; min-width: 0; animation: dbm-warroom-rise .7s var(--dbm-warroom-out) both; animation-delay: calc(var(--i, 0) * 50ms); }
  & > div + div { box-shadow: inset 1px 0 0 var(--dbm-warroom-hair); }
  & dt { font: 650 10px var(--dbm-warroom-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--dbm-warroom-faint); }
  & dd { font: 700 clamp(18px, 2.2cqi, 25px)/1.1 var(--dbm-warroom-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { font-size: .55em; font-weight: 600; color: var(--dbm-warroom-mute); letter-spacing: 0; margin-left: 5px; }
  & .sub { font-size: 11.5px; color: var(--dbm-warroom-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .up { color: var(--dbm-warroom-go); font-weight: 650; }
  & .dn { color: var(--dbm-warroom-bad); font-weight: 650; }
  & .hot { color: var(--dbm-warroom-signal); font-weight: 650; }
}
.dbm-warroom__pop { position: absolute; right: 12px; top: 8px; font: 700 11px var(--dbm-warroom-mono); color: var(--dbm-warroom-go); pointer-events: none; }
.dbm-warroom__gauge {
  --dbm-warroom-sold: 0%;
  position: relative; height: 5px; margin-top: 3px; border-radius: 3px; background: var(--dbm-warroom-line); overflow: hidden;
  transition: --dbm-warroom-sold 1s var(--dbm-warroom-out);
  &::before { content: ""; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(90deg, color-mix(in oklch, var(--dbm-warroom-signal) 55%, var(--dbm-warroom-bg)), var(--dbm-warroom-signal) var(--dbm-warroom-sold), transparent var(--dbm-warroom-sold)); }
}

/* ------------------------------------------------------------ panels */
.dbm-warroom__view { min-height: 0; }
.dbm-warroom__view[hidden] { display: none; }
.dbm-warroom__view:not([hidden]) { animation: dbm-warroom-in .45s var(--dbm-warroom-out) both; }
@keyframes dbm-warroom-in { from { opacity: 0; translate: 0 6px; } }
@keyframes dbm-warroom-rise { from { opacity: 0; translate: 0 8px; filter: blur(3px); } }
.dbm-warroom__v-live {
  height: 100%; display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1fr) clamp(280px, 29cqi, 340px);
  grid-template-rows: minmax(0, 1.28fr) minmax(0, 1fr);
  grid-template-areas: "hero sys" "traffic feed";
}
.dbm-warroom__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 8px; padding: 12px 14px; border-radius: 12px;
  background: var(--dbm-warroom-panel); box-shadow: inset 0 0 0 1px var(--dbm-warroom-line);
  animation: dbm-warroom-rise .7s var(--dbm-warroom-out) both; animation-delay: calc(var(--i, 0) * 70ms + 120ms);
}
.dbm-warroom__ph {
  display: flex; justify-content: space-between; align-items: start; gap: 10px; flex-wrap: wrap;
  & h3 { font-size: 13px; font-weight: 700; letter-spacing: -.01em; text-wrap: balance; }
}
.dbm-warroom__sub { font-size: 11.5px; color: var(--dbm-warroom-mute); text-wrap: pretty; font-variant-numeric: tabular-nums; & b { color: var(--dbm-warroom-ink); font-weight: 650; } & .hot { color: var(--dbm-warroom-signal); font-weight: 650; } }
.dbm-warroom__seg {
  display: inline-flex; padding: 2px; border-radius: 8px; background: color-mix(in oklch, var(--dbm-warroom-bg), black 15%); box-shadow: inset 0 0 0 1px var(--dbm-warroom-hair);
  & button { height: 24px; padding: 0 9px; border-radius: 6px; font: 650 11px var(--dbm-warroom-mono); color: var(--dbm-warroom-faint); transition: color .15s, background-color .15s; }
  & button:hover { color: var(--dbm-warroom-ink); }
  & button[aria-checked="true"] { background: var(--dbm-warroom-raise); color: var(--dbm-warroom-ink); box-shadow: 0 1px 0 var(--dbm-warroom-line); }
}

/* hero chart */
.dbm-warroom__hero { grid-area: hero; }
.dbm-warroom__plot { position: relative; flex: 1; min-height: 120px; border-radius: 8px; cursor: crosshair; touch-action: pan-y; }
.dbm-warroom__cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.dbm-warroom__head-dot {
  position: absolute; left: 0; top: 0; width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; border-radius: 50%; pointer-events: none;
  background: var(--dbm-warroom-signal); box-shadow: 0 0 0 2px var(--dbm-warroom-panel), 0 0 14px 2px color-mix(in oklch, var(--dbm-warroom-signal) 60%, transparent);
  opacity: 0; transition: opacity .3s;
  &.is-on { opacity: 1; }
  &::after { content: ""; position: absolute; inset: -6px; border-radius: 50%; border: 1.5px solid var(--dbm-warroom-signal); animation: dbm-warroom-ping 1.6s var(--dbm-warroom-out) infinite; }
}
.dbm-warroom:has(.dbm-warroom__play[aria-pressed="false"]) .dbm-warroom__head-dot::after { animation-play-state: paused; opacity: 0; }
.dbm-warroom.is-offscreen :is(.dbm-warroom__head-dot, .dbm-warroom__live)::after { animation-play-state: paused; }
.dbm-warroom__legend {
  display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11px; color: var(--dbm-warroom-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & li::before { content: ""; width: 14px; height: 0; border-top: 2px solid var(--dbm-warroom-signal); }
  & .p::before { height: 8px; border: 0; border-radius: 2px; background: color-mix(in oklch, var(--dbm-warroom-ink) 16%, transparent); border-top: 1.5px dashed var(--dbm-warroom-mute); }
  & .f::before { border-top: 2px dotted var(--dbm-warroom-signal); }
  & .s::before { border-top: 1.5px solid var(--dbm-warroom-bad); }
}

/* systems */
.dbm-warroom__sys { grid-area: sys; }
.dbm-warroom__tiles { flex: 1; min-height: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); grid-auto-rows: minmax(0, 1fr); gap: 6px; }
.dbm-warroom__tile {
  --c: var(--dbm-warroom-go);
