}
@supports (animation-timeline: view()) {
  .dbm-warroom__steps li:not(.nowline) { animation: dbm-warroom-step linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
}
@keyframes dbm-warroom-step { from { opacity: .2; translate: 12px 0; } }

/* ------------------------------------------------------------ drawer + tooltip */
.dbm-warroom__drawer {
  --c: var(--dbm-warroom-go);
  position: absolute; z-index: 30; top: 10px; right: 10px; bottom: 10px; width: min(340px, calc(100% - 20px));
  display: flex; flex-direction: column; gap: 10px; padding: 16px; border-radius: 14px; overflow: auto; scrollbar-width: thin;
  background: color-mix(in oklch, var(--dbm-warroom-bg), var(--dbm-warroom-ink) 7%);
