  transition: translate .45s var(--dbm-warroom-out), opacity .25s, display .45s allow-discrete;
  &[hidden] { display: none; translate: 40px 0; opacity: 0; }
  &[data-s="watch"] { --c: var(--dbm-warroom-warn); }
