@starting-style { .dbm-warroom__drawer:not([hidden]) { translate: 40px 0; opacity: 0; } }
.dbm-warroom__dh { display: flex; justify-content: space-between; align-items: center; }
.dbm-warroom__dstate { font: 750 10.5px var(--dbm-warroom-mono); letter-spacing: .09em; color: var(--c); display: inline-flex; align-items: center; gap: 6px; &::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: currentColor; } }
.dbm-warroom__x { width: 28px; height: 28px; border-radius: 7px; display: grid; place-items: center; &:hover { background: var(--dbm-warroom-hair); } & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; } }
.dbm-warroom__dtitle { font-size: 18px; font-weight: 750; letter-spacing: -.02em; text-wrap: balance; }
.dbm-warroom__dnow { font: 700 28px/1 var(--dbm-warroom-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; & small { font-size: 12px; color: var(--dbm-warroom-faint); letter-spacing: 0; margin-left: -4px; } }
.dbm-warroom__dsvg {
  width: 100%; height: 150px; flex: none;
