  & .ln { fill: none; stroke: var(--c); stroke-width: 1.8; stroke-linejoin: round; }
  & .ln-enter { stroke-dasharray: 1; animation: dbm-warroom-draw 1s var(--dbm-warroom-out) both; }
  & text { font: 600 9.5px var(--dbm-warroom-mono); fill: var(--dbm-warroom-faint); }
}
@keyframes dbm-warroom-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
.dbm-warroom__dmeta {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 7px 12px; padding-top: 10px; border-top: 1px solid var(--dbm-warroom-hair); font-size: 12px;
