  .dbm-warroom__late { top: 4px; right: 3px; }
  .dbm-warroom__oncall { margin: 0 0 0 auto; width: 28px; height: 28px; }
  .dbm-warroom__head { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "id ctl" "clock clock"; }
  .dbm-warroom__id { grid-area: id; } .dbm-warroom__ctl { grid-area: ctl; } .dbm-warroom__clock { grid-area: clock; grid-auto-flow: column; justify-content: start; align-items: baseline; gap: 10px; }
  .dbm-warroom__v-live { grid-template-columns: minmax(0, 1fr); grid-template-rows: 280px auto 230px 300px; grid-template-areas: "hero" "sys" "traffic" "feed"; }
  .dbm-warroom__tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dbm-warroom__table td:nth-child(6), .dbm-warroom__table th:nth-child(6), .dbm-warroom__table td:nth-child(7), .dbm-warroom__table th:nth-child(7) { display: none; }
}
@container dbm-warroom (width < 480px) {
