  .dbm-warroom__steps li { grid-template-columns: 44px 20px minmax(0, 1fr); }
  .dbm-warroom__steps li::before { left: 58px; }
  .dbm-warroom__steps .pill { grid-column: 3; justify-self: start; }
  .dbm-warroom__steps .phase { padding-left: 64px; }
}

@media (prefers-reduced-motion: reduce) {
  .dbm-warroom__kpis > div, .dbm-warroom__panel, .dbm-warroom__view:not([hidden]), .dbm-warroom__tsvg.is-enter .bars, .dbm-warroom__tile.is-flash { animation: none; }
  .dbm-warroom__live::after, .dbm-warroom__head-dot::after { animation: none; opacity: 0; }
