const nf = n => NF.format(Math.round(n));
const money = n => n >= 1e6 ? '$' + (n / 1e6).toFixed(2) + 'M' : n >= 1e4 ? '$' + (n / 1e3).toFixed(1) + 'k' : '$' + nf(n);
const pct = (n, d = 1) => (n * 100).toFixed(d) + '%';
const sgn = (n, d = 1) => (n >= 0 ? '+' : '−') + Math.abs(n * 100).toFixed(d) + '%';
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const pad = n => String(n).padStart(2, '0');
/* minute 0 is 09:00 PT on launch day; minute 900 is midnight */
const hm = m => { const t = Math.floor(9 * 60 + m); return pad(Math.floor(t / 60) % 24 === 0 && t >= 1440 ? 24 : Math.floor(t / 60)) + ':' + pad(((t % 60) + 60) % 60); };
const dur = mins => { const h = Math.floor(mins / 60), m = Math.round(mins % 60); return h ? `${h}h ${pad(m)}m` : `${m}m`; };

/* ---------------------------------------------------------------- model: the launch day, minute by minute, seeded */
const M = 900, STOCK = 11500, PRICE = 189, START = 372 + 18 / 60;
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const R = rng(20261001);
const gauss = () => { let u = 0; while (!u) u = R(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * R()); };
const pois = l => { if (l <= 0) return 0; if (l < 40) { const L = Math.exp(-l); let k = 0, p = 1; do { k++; p *= R(); } while (p > L); return k - 1; } return Math.max(0, Math.round(l + Math.sqrt(l) * gauss())); };
