    let se = 0, o = 0, u = 0, sp = 0, po = 0;
    for (let m = 0; m < m1; m++) { se += sess[i][m]; o += ord[i][m]; u += uni[i][m]; sp += spend[i][m]; po += planO[i][m]; }
    return { i, name: s.name, sess: se, ord: o, cr: se ? o / se : 0, rev: u * PRICE, spend: sp, roas: sp ? u * PRICE / sp : null, vs: po ? o / po - 1 : 0, po };
