  tb.innerHTML = rows.map(r => `<tr data-i="${r.i}"><td style="--c:var(--dbm-warroom-s${r.i})"><span><i></i>${r.name}</span></td><td>${nf(r.sess)}</td><td>${nf(r.ord)}</td><td>${pct(r.cr, 2)}</td><td>${money(r.rev)}</td><td class="${r.spend ? '' : 'na'}">${r.spend ? money(r.spend) : '—'}</td><td class="${r.roas == null ? 'na' : ''}">${r.roas == null ? '—' : r.roas.toFixed(1) + '×'}</td><td class="${r.vs >= 0 ? 'up' : 'dn'}">${sgn(r.vs)}</td></tr>`).join('');
  if (before.size) $$('tr', tb).forEach(tr => { const b = before.get(tr.dataset.i); if (b == null) return; const dy = b - tr.getBoundingClientRect().top; if (Math.abs(dy) > 1) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.16,1,.3,1)' }); });
