  $('.dbm-warroom__table tfoot').innerHTML = `<tr><td>All sources</td><td>${nf(T.sess)}</td><td>${nf(T.ord)}</td><td>${pct(T.sess ? T.ord / T.sess : 0, 2)}</td><td>${money(T.rev)}</td><td>${money(T.spend)}</td><td title="Revenue from paid search and social over their spend">${T.spend ? (rows.reduce((a, r) => a + (r.spend ? r.rev : 0), 0) / T.spend).toFixed(1) + '×' : '—'}</td><td class="${T.ord >= T.po ? 'up' : 'dn'}">${sgn(T.ord / T.po - 1)}</td></tr>`;
  $$('.dbm-warroom__table th').forEach(th => th.setAttribute('aria-sort', th.dataset.k === k ? (dir > 0 ? 'ascending' : 'descending') : 'none'));
  const byShare = SRC.map((s, i) => ({ i, s, o: rows.find(r => r.i === i).ord }));
  const mix = $('.dbm-warroom__mix');
  if (!mix.children.length) mix.innerHTML = byShare.map(x => `<span style="--c:var(--dbm-warroom-s${x.i})" data-i="${x.i}"></span>`).join('');
  byShare.forEach(x => { const el = $(`span[data-i="${x.i}"]`, mix), sh = T.ord ? x.o / T.ord : 0; el.style.setProperty('--w', sh.toFixed(4)); el.textContent = sh > .05 ? `${x.s.short} ${pct(sh, 0)}` : ''; el.title = `${x.s.name}: ${nf(x.o)} orders, ${pct(sh)}`; });
