/* ---------------------------------------------------------------- runbook */
const steps = $('.dbm-warroom__steps');
function renderRunbook() {
  const t = S.t; let html = '', ph = '', nowPlaced = false, late = 0, done = 0;
  RB.forEach(x => {
    if (x.phase !== ph) { ph = x.phase; html += `<li class="phase" aria-hidden="true">${ph}</li>`; }
    if (!nowPlaced && x.m > t) { html += `<li class="nowline" aria-hidden="true"><span>NOW ${hm(t)}</span></li>`; nowPlaced = true; }
    const isLate = !x.done && x.m <= t, soon = !x.done && x.m > t && x.m - t <= 30, isNow = Math.abs(x.m - t) <= 15 && !x.done;
    if (isLate) late++; if (x.done) done++;
    const pill = x.done ? 'Done' : isLate ? `Late ${dur(t - x.m)}` : soon ? `Due in ${dur(x.m - t)}` : `In ${dur(x.m - t)}`;
    html += `<li class="${x.done ? 'is-done' : ''}${isLate ? ' is-late' : ''}${soon ? ' is-soon' : ''}${isNow ? ' is-now' : ''}"><time>${hm(x.m)}</time><input type="checkbox" data-i="${x.i}"${x.done ? ' checked' : ''} aria-label="${x.title}"><span class="t"><b>${x.title}</b><span>${x.who}</span></span><span class="pill">${pill}</span></li>`;
  });
  if (!nowPlaced) html += `<li class="nowline" aria-hidden="true"><span>NOW ${hm(t)}</span></li>`;
  const focused = doc.activeElement && steps.contains(doc.activeElement) ? doc.activeElement.dataset.i : null;
  steps.innerHTML = html;
  if (focused != null) { const f = $(`input[data-i="${focused}"]`, steps); if (f) f.focus({ preventScroll: true }); }
  $('.dbm-warroom__rbSub').innerHTML = `<b>${done}</b> of ${RB.length} done${late ? ` · <span class="hot">${late} late</span>` : ''} · times are PT`;
  const badge = $('.dbm-warroom__late'); badge.hidden = !late; tabs[2].setAttribute('aria-label', `Runbook${late ? `, ${late} late` : ''}`);
}
steps.addEventListener('change', e => {
  const i = e.target.dataset.i; if (i == null) return; const x = RB[+i]; x.done = e.target.checked;
  if (x.done) addFeed({ m: S.t, kind: 'comms', html: `Runbook: <b>${x.title}</b> marked done.` }, true);
  renderRunbook();
});

